    'zanzibar_why_badge' => 'Perché aggiungere Zanzibar',
    'zanzibar_why_title' => 'Il modo perfetto per concludere un safari',
    'zanzibar_why_1_title' => 'Il contrasto perfetto',
    'zanzibar_why_1_desc' => 'Scambia i game drive all\'alba con mattine lente e acqua calda — la polvere della savana con l\'aria di mare.',
    'zanzibar_why_2_title' => 'Un viaggio, due mondi',
    'zanzibar_why_2_desc' => 'Stesso visto, stessa valuta, un semplice volo interno — nessuna vacanza separata da organizzare.',
    'zanzibar_why_3_title' => 'Pensiamo noi alla logistica',
    'zanzibar_why_3_desc' => 'Voli, trasferimenti e hotel prenotati come parte del tuo itinerario. Tu devi solo arrivare e disfare le valigie.',

