    'zanzibar_beaches_badge' => 'Scegli la tua costa',
    'zanzibar_beaches_title' => 'Quale spiaggia fa per te',
    'zanzibar_beaches_intro' => 'L\'isola è piccola, ma le coste sono molto diverse tra loro. Le maree contano più di quanto la maggior parte dei visitatori si aspetti.',
    'zanzibar_beach_north_region' => 'Nord',
    'zanzibar_beach_north_name' => 'Nungwi & Kendwa',
    'zanzibar_beach_north_desc' => 'Le uniche spiagge dove puoi nuotare con qualsiasi marea. La zona più vivace dell\'isola, con più hotel e ristoranti, e i tramonti migliori.',
    'zanzibar_beach_north_best' => 'Ideale per: prima visita, nuoto, vita notturna',
    'zanzibar_beach_se_region' => 'Sud-est',
    'zanzibar_beach_se_name' => 'Paje & Jambiani',
    'zanzibar_beach_se_desc' => 'Ampia laguna, maree forti e vento costante — la costa del kitesurf. Più tranquilla, più giovane, più rilassata rispetto al nord.',
    'zanzibar_beach_se_best' => 'Ideale per: kitesurf, lunghe passeggiate, rapporto qualità-prezzo',
    'zanzibar_beach_east_region' => 'Est e Sud',
    'zanzibar_beach_east_name' => 'Matemwe & Kizimkazi',
    'zanzibar_beach_east_desc' => 'Matemwe è di fronte all\'atollo di Mnemba, il miglior snorkeling dell\'isola. Kizimkazi è dove partono le barche per l\'avvistamento dei delfini.',
    'zanzibar_beach_east_best' => 'Ideale per: snorkeling, immersioni, tranquillità',
    'zanzibar_tide_note' => '<strong>Sulle maree:</strong> sulle coste est e sud-est il mare si ritira per centinaia di metri con la bassa marea e nuotare non è possibile per parte della giornata. Non è un problema — è semplicemente come funziona l\'isola — ma se nuotare quando vuoi è importante per te, scegli il nord.',

    'zanzibar_excursions_badge' => 'Oltre la spiaggia',
    'zanzibar_excursions_title' => 'Escursioni da non perdere',
    'zanzibar_exc_stonetown_title' => 'Stone Town',
    'zanzibar_exc_stonetown_desc' => 'Patrimonio UNESCO: porte intagliate, l\'ex mercato degli schiavi, il mercato notturno del cibo di Forodhani. Mezza giornata con una guida locale.',
    'zanzibar_exc_spice_title' => 'Tour delle spezie',
    'zanzibar_exc_spice_desc' => 'Le piantagioni che hanno dato il nome all\'isola: chiodi di garofano, vaniglia, noce moscata e cannella, assaggiati direttamente dall\'albero.',
    'zanzibar_exc_safariblue_title' => 'Safari Blue',
    'zanzibar_exc_safariblue_desc' => 'Una giornata intera in dhow: banchi di sabbia, snorkeling, pranzo a base di pesce sull\'isola di Kwale e canali di mangrovie.',
    'zanzibar_exc_jozani_title' => 'Foresta di Jozani',
    'zanzibar_exc_jozani_desc' => 'L\'ultimo habitat del colobo rosso, presente solo qui al mondo. Due ore, facilmente combinabile con la costa sud.',
    'zanzibar_exc_mnemba_title' => 'Atollo di Mnemba',
    'zanzibar_exc_mnemba_desc' => 'Il miglior snorkeling e immersioni dell\'isola, raggiungibile in barca da Matemwe.',
    'zanzibar_exc_prison_title' => 'Prison Island',
    'zanzibar_exc_prison_desc' => 'Tartarughe giganti di Aldabra, alcune con più di un secolo di vita, a breve distanza in barca da Stone Town.',

    'zanzibar_when_badge' => 'Pianificazione',
    'zanzibar_when_title' => 'Quando andare',
    'zanzibar_when_dry_period' => 'Giugno – Ottobre',
    'zanzibar_when_dry_temp' => '26–30°C',
    'zanzibar_when_dry_desc' => 'Secco, soleggiato e meno umido. L\'alta stagione, naturale continuazione di un safari in stagione secca.',
    'zanzibar_when_dry_tag' => 'Il migliore',
    'zanzibar_when_summer_period' => 'Dicembre – Febbraio',
    'zanzibar_when_summer_temp' => '28–32°C',
    'zanzibar_when_summer_desc' => 'Caldo, mare calmo, ottima visibilità per le immersioni. Possibili brevi rovesci.',
    'zanzibar_when_summer_tag' => 'Molto buono',
    'zanzibar_when_long_rains_period' => 'Marzo – Maggio',
    'zanzibar_when_long_rains_temp' => '27–31°C',
    'zanzibar_when_long_rains_desc' => 'Le piogge lunghe. Prezzi più bassi e spiagge vuote, ma alcuni hotel chiudono ad aprile e maggio.',
    'zanzibar_when_long_rains_tag' => 'Bassa stagione',
    'zanzibar_when_nov_period' => 'Novembre',
    'zanzibar_when_nov_temp' => '27–31°C',
    'zanzibar_when_nov_desc' => 'Piogge brevi: acquazzoni pomeridiani di breve durata, altrimenti soleggiato. Buon rapporto qualità-prezzo prima del boom di dicembre.',
    'zanzibar_when_nov_tag' => 'Buon valore',

    'zanzibar_featured_badge' => 'Combinazione più richiesta',
    'zanzibar_featured_title' => 'Safari di 7 Giorni + Zanzibar',
    'zanzibar_featured_desc' => '5 notti di safari sul circuito del nord, 2 notti di relax a Zanzibar, volo interno incluso.',
    'zanzibar_featured_price' => 'da €2.200 a persona',
    'zanzibar_featured_cta' => 'Vedi questo pacchetto',

    'zanzibar_practical_badge' => 'Utile da sapere',
    'zanzibar_practical_title' => 'Note pratiche',
    'zanzibar_practical_entry_title' => 'Requisiti di ingresso',
    'zanzibar_practical_entry_desc' => 'Zanzibar fa parte della Tanzania, quindi si applica lo stesso visto. Dal 2024 è richiesta anche una polizza assicurativa rilasciata da un fornitore approvato zanzibarino all\'arrivo; costa circa 44 USD e possiamo organizzarla con la tua prenotazione.',
    'zanzibar_practical_dress_title' => 'Abbigliamento e usanze',
    'zanzibar_practical_dress_desc' => 'Zanzibar è a maggioranza musulmana. Il costume da bagno va bene in spiaggia e in hotel, ma copri spalle e ginocchia a Stone Town e nei villaggi. Durante il Ramadan molti ristoranti fuori dai resort chiudono di giorno.',
    'zanzibar_practical_flight_title' => 'Come arrivare dal safari',
    'zanzibar_practical_flight_desc' => 'Un volo diretto dalle piste del Serengeti impiega circa 1 ora e 30 minuti; da Arusha o dall\'aeroporto del Kilimanjaro, circa un\'ora. Prenotiamo questi voli interni come parte del tuo itinerario.',
    'zanzibar_practical_malaria_title' => 'Malaria',
    'zanzibar_practical_malaria_desc' => 'Zanzibar è un\'area a rischio malaria. Si consiglia la profilassi — chiedi al tuo medico o a un centro di medicina del viaggio — e usa repellente al tramonto. Bevi acqua in bottiglia o filtrata.',

    'zanzibar_faq_title' => 'Domande comuni',
    'zanzibar_faq_q1' => 'Quanti giorni dovrei aggiungere per Zanzibar?',
    'zanzibar_faq_a1' => 'Tre notti sono il minimo per sentirsi in vacanza e non solo in transito. Quattro o cinque ti danno il tempo per una giornata in spiaggia, un\'escursione e Stone Town senza fretta.',
    'zanzibar_faq_q2' => 'Zanzibar è inclusa nel prezzo del safari?',
    'zanzibar_faq_a2' => 'No, è un\'estensione opzionale. La quotiamo separatamente insieme al tuo safari così puoi vedere esattamente cosa aggiunge, incluso il volo interno.',
    'zanzibar_faq_q3' => 'Quale spiaggia dovrebbero scegliere i visitatori alla prima visita?',
    'zanzibar_faq_a3' => 'Nungwi o Kendwa a nord — nuotabili con qualsiasi marea, con più hotel e ristoranti, e l\'introduzione più semplice all\'isola.',
    'zanzibar_faq_q4' => 'Servono vaccinazioni extra per Zanzibar?',
    'zanzibar_faq_a4' => 'Nessuna vaccinazione oltre a quelle richieste per la Tanzania continentale. Si consiglia la profilassi antimalarica, e la polizza assicurativa locale è obbligatoria all\'arrivo.',

    'zanzibar_cta_title' => 'Pianifica il tuo viaggio con noi',
    'zanzibar_cta_intro' => 'Inviaci le tue date, la dimensione del gruppo e il budget. Ti rispondiamo con un itinerario scritto e un preventivo dettagliato — senza impegno.',
    'zanzibar_cta_whatsapp' => 'Scrivici su WhatsApp',
    'zanzibar_cta_contact_form' => 'Modulo di contatto',

    'trekking_meta_title' => 'Trekking Kilimanjaro & Monte Meru | Serengeti Budget Safari',
    'trekking_meta_description' => 'Scala il Kilimanjaro con un operatore locale di Arusha: route Machame, Lemosho, Marangu, Rongai e Northern Circuit, oltre al Monte Meru, Ol Doinyo Lengai e i monti Usambara.',
    'trekking_hero_badge' => 'Trekking',
    'trekking_hero_title_1' => 'Trekking sul',
    'trekking_hero_title_2' => 'Kilimanjaro',
    'trekking_hero_sub' => 'Il punto più alto d\'Africa a 5.895 m, oltre al Monte Meru, Ol Doinyo Lengai e le colline Usambara — scalati con la nostra squadra di montagna.',
    'trekking_hero_cta_quote' => 'Richiedi un preventivo',

    'trekking_routes_badge' => 'Scegli il tuo percorso',
    'trekking_routes_title' => 'Scegli la tua route',
    'trekking_routes_intro' => 'La montagna non è tecnica — la sfida è l\'altitudine. Più lunga è la route, meglio il corpo si acclimata e maggiori sono le probabilità di raggiungere Uhuru Peak.',

    'trekking_route_lemosho_tagline' => 'Miglior panorama e acclimatazione',
    'trekking_route_lemosho_name' => 'Lemosho',
    'trekking_route_lemosho_days' => '7–8 giorni',
    'trekking_route_lemosho_desc' => 'Un inizio tranquillo attraverso la foresta, che si unisce a Machame più in alto. Il miglior profilo di acclimatazione tra tutte le route.',
    'trekking_route_lemosho_success' => 'Massima',

    'trekking_route_machame_tagline' => 'La "Whiskey Route" · la più popolare',
    'trekking_route_machame_name' => 'Machame',
    'trekking_route_machame_days' => '6–7 giorni',
    'trekking_route_machame_desc' => 'Panoramica, ripida in alcuni tratti, con un buon profilo di acclimatazione. La route scelta dalla maggior parte degli scalatori.',
    'trekking_route_machame_success' => 'Alta',

    'trekking_route_northern_tagline' => 'Sentieri più tranquilli, route più lunga',
    'trekking_route_northern_name' => 'Northern Circuit',
    'trekking_route_northern_days' => '9 giorni',
    'trekking_route_northern_desc' => 'Quasi un giro completo della montagna. La route più lunga, con pochissimi altri gruppi sul sentiero.',
    'trekking_route_northern_success' => 'Massima',

    'trekking_route_rongai_tagline' => 'La più secca nei mesi delle piogge',
    'trekking_route_rongai_name' => 'Rongai',
    'trekking_route_rongai_days' => '6–7 giorni',
    'trekking_route_rongai_desc' => 'Si avvicina dal lato nord più secco. La scelta migliore se scali fuori dalla stagione secca principale.',
    'trekking_route_rongai_success' => 'Buona',

    'trekking_route_marangu_tagline' => 'Rifugi invece di tende',
    'trekking_route_marangu_name' => 'Marangu',
    'trekking_route_marangu_days' => '5–6 giorni',
    'trekking_route_marangu_desc' => 'L\'unica route con alloggio in rifugio. Stesso percorso in salita e discesa, e l\'opzione più breve.',
    'trekking_route_marangu_success' => 'Più bassa',

    'trekking_routes_note' => 'Se hai i giorni a disposizione, scegli la route più lunga. La notte in più è l\'assicurazione più economica che puoi comprare contro il mal di montagna.',

    'trekking_included_title' => 'Cosa include ogni scalata',
    'trekking_included_subtitle' => 'La stessa trasparenza dei nostri safari — nessun costo nascosto una volta in montagna.',
    'trekking_included_heading' => 'Incluso',
    'trekking_included_1' => 'Tasse del parco, tasse di campeggio o rifugio e tasse di soccorso',
    'trekking_included_2' => 'Guida di montagna certificata, guide assistenti, cuoco e portatori',
    'trekking_included_3' => 'Tutti i pasti in montagna e acqua potabile',
    'trekking_included_4' => 'Tende, materassini, tenda mensa e attrezzatura da cucina',
    'trekking_included_5' => 'Controlli con pulsossimetro e kit di primo soccorso portato dalla guida',
    'trekking_included_6' => 'Trasferimenti tra Arusha e il punto di partenza',
    'trekking_included_7' => 'Due notti ad Arusha, prima e dopo la scalata',
    'trekking_excluded_heading' => 'Non incluso',
    'trekking_excluded_1' => 'Voli internazionali e visto',
    'trekking_excluded_2' => 'Assicurazione di viaggio che copra il trekking fino a 6.000 m (obbligatoria)',
    'trekking_excluded_3' => 'Attrezzatura personale e sacco a pelo (noleggio disponibile)',
    'trekking_excluded_4' => 'Mance per la squadra di montagna',
    'trekking_excluded_5' => 'Ossigeno portatile o portatore personale, su richiesta',

    'trekking_other_badge' => 'Oltre il Kilimanjaro',
    'trekking_other_title' => 'Altre montagne',
    'trekking_meru_name' => 'Monte Meru — 4.566 m',
    'trekking_meru_desc' => 'Tre o quattro giorni all\'interno dell\'Arusha National Park, camminando con un ranger armato tra bufali e giraffe. La migliore acclimatazione possibile prima del Kilimanjaro.',
    'trekking_lengai_name' => 'Ol Doinyo Lengai — 2.962 m',
    'trekking_lengai_desc' => 'La "Montagna di Dio" dei Maasai, un vulcano attivo scalato di notte per raggiungere il bordo del cratere all\'alba. Ripido, caldo e davvero impegnativo.',
    'trekking_usambara_name' => 'Usambara & Udzungwa',
    'trekking_usambara_desc' => 'Montagne verdi, cascate e villaggi, percorsi in due o quattro giorni a bassa altitudine. Una buona opzione nella stagione delle piogge o con bambini.',

    'trekking_guide_badge' => 'Approfondisci',
    'trekking_guide_title' => 'Leggi la guida completa del parco',
    'trekking_guide_intro' => 'Tutto sul Parco Nazionale del Kilimanjaro in un unico posto — tutte e sette le route confrontate con i tassi di successo, le tasse del parco 2026 dettagliate, il mal di montagna spiegato, e come trattare i portatori.',
    'trekking_guide_kili_badge' => 'Guida del parco',
    'trekking_guide_kili_title' => 'Parco Nazionale del Kilimanjaro',
    'trekking_guide_kili_desc' => 'Cinque zone climatiche, sette route, 5.895 m. Solo le tasse del parco sono circa 956 $ per una scalata di sette giorni — ti mostriamo esattamente come viene calcolato.',
    'trekking_guide_kili_cta' => 'Guida completa del Kilimanjaro',
    'trekking_guide_meru_badge' => 'Guida del parco',
    'trekking_guide_meru_title' => 'Arusha NP & Monte Meru',
    'trekking_guide_meru_desc' => 'Il Meru a 4.566 m è la migliore acclimatazione disponibile prima del Kilimanjaro — e una montagna superba, quasi vuota, di per sé.',
    'trekking_guide_meru_cta' => 'Guida completa dell\'Arusha NP',

    'trekking_faq_title' => 'Prima di prenotare',
    'trekking_faq_q1' => 'Serve esperienza di scalata?',
    'trekking_faq_a1' => 'No. Il Kilimanjaro è una lunga camminata, non una scalata — non ci sono corde né terreno tecnico. Ciò che richiede è resistenza per sei-nove giorni di cammino e la capacità di gestire l\'aria rarefatta. Allenati camminando in salita per diverse ore consecutive.',
    'trekking_faq_q2' => 'Qual è il periodo migliore per scalare?',
    'trekking_faq_a2' => 'Da gennaio a inizio marzo e da giugno a ottobre. Aprile, maggio e novembre sono i mesi delle piogge: la montagna è ancora scalabile, ma i sentieri sono scivolosi e le viste spesso coperte. Rongai è la route più secca in condizioni marginali.',
    'trekking_faq_q3' => 'E il mal di montagna?',
    'trekking_faq_a3' => 'Lievi mal di testa e affanno sono normali sopra i 4.000 m. Le nostre guide controllano la saturazione di ossigeno due volte al giorno e portano un kit di primo soccorso. La regola sulle nostre scalate è semplice: se una guida giudica che devi scendere, scendi. Nessuno viene spinto a continuare.',

    'trekking_cta_title' => 'Pianifica il tuo viaggio con noi',
    'trekking_cta_intro' => 'Inviaci le tue date, la dimensione del gruppo e il budget. Ti rispondiamo con un itinerario scritto e un preventivo dettagliato — senza impegno.',
    'trekking_cta_whatsapp' => 'Scrivici su WhatsApp',
    'trekking_cta_contact_form' => 'Modulo di contatto',

    'groups_meta_title' => 'Safari di Gruppo in Tanzania | Serengeti Budget Safari',
    'groups_meta_description' => 'Unisciti a un safari di gruppo programmato in Tanzania e dividi il costo di un 4x4 privato senza dividere l\'esperienza. Partenze fisse, piccoli gruppi, adatto a chi viaggia da solo.',
    'groups_hero_badge' => 'Safari di Gruppo',
    'groups_hero_title_1' => 'Unisciti a un safari,',
    'groups_hero_title_2' => 'non a una folla',
    'groups_hero_sub' => 'Piccole partenze condivise per chi viaggia da solo e per le coppie — il prezzo di un gruppo, la sensazione di un viaggio privato.',
    'groups_hero_cta_quote' => 'Chiedi della prossima partenza',

    'groups_how_badge' => 'Come funziona',
    'groups_how_title' => 'Dalla richiesta al veicolo',
    'groups_how_1_title' => 'Dicci le tue date',
    'groups_how_1_desc' => 'Scrivici il mese in cui vuoi viaggiare e quanti giorni hai a disposizione.',
    'groups_how_2_title' => 'Ti abbiniamo a una partenza',
    'groups_how_2_desc' => 'Verifichiamo quale gruppo programmato è più vicino alle tue date e confermiamo i posti disponibili.',
    'groups_how_3_title' => 'Ti unisci a un piccolo gruppo',
    'groups_how_3_desc' => 'Massimo 6 persone per veicolo, condiviso con altri viaggiatori nelle stesse date.',
    'groups_how_4_title' => 'Un 4x4 condiviso, una guida',
    'groups_how_4_desc' => 'Stessa guida, stesso veicolo e stesso itinerario di un safari privato — a un prezzo condiviso.',

    'groups_why_badge' => 'Perché unirsi a un gruppo',
    'groups_why_title' => 'Pensato per chi viaggia da solo e per le coppie',
    'groups_why_1_title' => 'Costo per persona più basso',
    'groups_why_1_desc' => 'Le tasse del parco e il veicolo sono costi fissi — condividerli con altri 3-5 viaggiatori riduce notevolmente il prezzo.',
    'groups_why_2_title' => 'Incontra persone, non estranei',
    'groups_why_2_desc' => 'I gruppi restano piccoli (massimo 6) e vengono abbinati per date di viaggio, non assemblati a caso — la maggior parte degli ospiti si conosce già dal secondo giorno.',
    'groups_why_3_title' => 'Stessa qualità, nessun compromesso',
    'groups_why_3_desc' => 'Stessa guida, 4x4 e standard di itinerario dei nostri safari privati. Condividi il veicolo, non l\'esperienza.',

    'groups_departures_badge' => 'Esempio di calendario',
    'groups_departures_title' => 'Come appare un calendario di partenze',
    'groups_departures_intro' => 'Questo è un esempio di come sono programmate le nostre partenze di gruppo — le date effettive e la disponibilità dei posti vengono confermate quando ci contatti, poiché cambiano man mano che arrivano le prenotazioni.',
    'groups_departures_col_departure' => 'Partenza',
    'groups_departures_col_itinerary' => 'Itinerario',
    'groups_departures_col_price' => 'Prezzo a persona',
    'groups_departures_col_seats' => 'Posti',
    'groups_departures_note' => 'Esempio illustrativo — scrivici per le date reali attualmente disponibili.',
    'groups_seats_open' => 'Disponibile',
    'groups_seats_filling' => 'Quasi pieno',
    'groups_seats_full' => 'Completo',

    'groups_availability_title' => 'Chiedi della prossima partenza disponibile',
    'groups_availability_intro' => 'Dicci il tuo mese di viaggio e la dimensione del gruppo — ti rispondiamo con la partenza programmata più vicina, il prezzo esatto a persona e quanti posti restano.',
    'groups_availability_stat1' => '6',
    'groups_availability_stat1_label' => 'Max per veicolo',
    'groups_availability_stat2' => '24h',
    'groups_availability_stat2_label' => 'Tempo di risposta tipico',
    'groups_availability_stat3' => '0',
    'groups_availability_stat3_label' => 'Costi nascosti',
    'groups_availability_whatsapp' => 'Verifica disponibilità su WhatsApp',
    'groups_availability_contact' => 'Oppure usa il modulo di contatto',

    'groups_faq_title' => 'Domande comuni',
    'groups_faq_q1' => 'Cosa succede se una partenza non si riempie?',
    'groups_faq_a1' => 'Le nostre partenze programmate operano con un minimo di 2 viaggiatori. Se si sono prenotate meno persone, te lo comunichiamo in anticipo invece di cancellare all\'ultimo momento — puoi aspettare la data successiva o chiedere un safari privato a un prezzo adeguato.',
    'groups_faq_q2' => 'Posso prenotare un safari di gruppo da solo?',
    'groups_faq_a2' => 'Sì — la maggior parte dei nostri viaggiatori di gruppo viaggia da sola. Condividerai il veicolo e la guida con un piccolo numero di altri viaggiatori nelle stesse date, non sarai l\'unico ospite.',
    'groups_faq_q3' => 'Con quanto anticipo dovrei prenotare?',
    'groups_faq_a3' => 'Per giugno-ottobre (alta stagione) punta a 2-3 mesi di anticipo. Fuori da questo periodo, di solito bastano 3-4 settimane, ma scrivici presto se le tue date sono fisse.',
    'groups_faq_q4' => 'Coppie o amici possono viaggiare insieme in un safari di gruppo?',
    'groups_faq_a4' => 'Sì, condividerai il veicolo con altri viaggiatori ma sarete seduti insieme come coppia o piccolo gruppo — riempiamo semplicemente i posti restanti con altri ospiti nelle stesse date.',

