    'pkg3d_itinerary_badge' => 'Giorno per giorno',
    'pkg3d_itinerary_title' => 'Il tuo itinerario',
    'pkg3d_day1_title' => 'Giorno 1 — Arusha verso il Serengeti',
    'pkg3d_day1_desc' => 'Partenza mattutina dal tuo hotel ad Arusha. Attraversiamo l\'Area di Conservazione di Ngorongoro con una sosta al punto panoramico del cratere, poi scendiamo nel Serengeti per un game drive pomeridiano verso il campo.',
    'pkg3d_day2_title' => 'Giorno 2 — Giornata intera, Serengeti Centrale',
    'pkg3d_day2_desc' => 'Una giornata intera di game drive nella regione di Seronera — la più alta densità di predatori del parco. Pranzo al sacco nella savana. Ritorno al campo per la cena sotto le stelle.',
    'pkg3d_day3_title' => 'Giorno 3 — Cratere di Ngorongoro verso Arusha',
