    'pkg3d_faq_title' => 'Domande su questo safari',
    'pkg3d_faq_q1' => '3 giorni bastano per vedere il Serengeti?',
    'pkg3d_faq_a1' => 'È il minimo pratico. Hai una giornata intera nel parco più il Cratere di Ngorongoro, che insieme coprono le più alte concentrazioni di fauna selvatica in Tanzania. I viaggi più lunghi aggiungono altri parchi, non più Serengeti in sé.',
    'pkg3d_faq_q2' => 'Vedrò i Big Five?',
    'pkg3d_faq_a2' => 'Leone, elefante, bufalo e leopardo si vedono regolarmente su questo percorso. Il rinoceronte nero è realistico solo nel Cratere di Ngorongoro, motivo per cui questo itinerario lo include — nessun operatore può garantire l\'avvistamento di un animale selvatico, ma questa combinazione ti dà le migliori probabilità del paese.',
    'pkg3d_faq_q3' => 'Posso estendere questo safari a più giorni?',
    'pkg3d_faq_a3' => 'Sì — questo itinerario è la base dei nostri pacchetti di 4, 5 e 8 giorni, che aggiungono Tarangire, più giorni nel Serengeti, o il percorso della migrazione. Dicci le tue date e lo adatteremo.',

