    'pkg5d_overview_title' => 'Vivi il Cuore Selvaggio della Tanzania',
    'pkg5d_overview_p1' => 'Vivi un indimenticabile safari di 5 giorni in Tanzania tra Tarangire, Serengeti e Ngorongoro. Cerca i Big Five, esplora paesaggi mozzafiato e goditi un alloggio confortevole viaggiando a bordo di un 4x4 privato.',
    'pkg5d_overview_p2' => 'Ogni game drive è guidato dalle nostre stesse guide, con i nostri veicoli — la stessa squadra dal primo pickup ad Arusha all\'ultimo trasferimento. Nessun veicolo in subappalto, nessun itinerario condiviso con estranei a meno che tu non scelga una partenza di gruppo.',
