    'contact_faq_title' => 'Prima di scriverci',
    'contact_faq_q1' => 'Quanto velocemente riceverò una risposta?',
    'contact_faq_a1' => 'I messaggi WhatsApp ricevono solitamente risposta entro un\'ora durante il nostro orario di lavoro. Le richieste tramite modulo di contatto ed email ricevono risposta entro 24 ore.',
    'contact_faq_q2' => 'Devo pagare qualcosa per ricevere un preventivo?',
    'contact_faq_a2' => 'No. Ogni preventivo e itinerario scritto è gratuito e non comporta alcun impegno di prenotazione.',
    'contact_faq_q3' => 'E se non conosco ancora le date esatte?',
    'contact_faq_a3' => 'Va bene lo stesso — dicci il mese approssimativo o un intervallo di date e ti consiglieremo su disponibilità e prezzi per quel periodo.',

    'arusha_meta_title' => 'Guida al Parco Nazionale di Arusha (2026) | Serengeti Budget Safari',
    'arusha_meta_description' => 'Guida al Parco Nazionale di Arusha: Monte Meru, i laghi Momella, safari a piedi, leoni che si arrampicano sugli alberi, tasse del parco 2026, quando andare e dove alloggiare — a 40 minuti da Arusha.',
    'arusha_hero_badge' => 'Parco Nazionale di Arusha',
    'arusha_hero_title' => 'Parco Nazionale di Arusha',
    'arusha_hero_sub' => 'Il parco più sottovalutato della Tanzania — Monte Meru, i laghi Momella e safari a piedi, a soli 40 minuti da Arusha.',
    'arusha_hero_cta_quote' => 'Richiedi un preventivo',

    'arusha_intro_badge' => 'Panoramica',
    'arusha_intro_title' => 'Un piccolo parco con una varietà di paesaggi fuori scala',
    'arusha_intro_p1' => 'Il Parco Nazionale di Arusha è il parco più comodo della Tanzania — 40 minuti dal centro di Arusha e spesso visitato come escursione di mezza giornata o come giorno di acclimatazione prima di una scalata al Kilimanjaro o al Meru. Nonostante le dimensioni ridotte, racchiude quattro paesaggi distinti in una sola visita: il Cratere di Ngurdoto, i laghi Momella, la foresta montana e i pendii inferiori del Monte Meru stesso.',
    'arusha_intro_p2' => 'È anche uno dei soli tre parchi in Tanzania dove sono consentiti i safari a piedi, e l\'unico posto vicino ad Arusha dove puoi fare canoa tra ippopotami e fenicotteri sui laghi Momella.',
    'arusha_intro_p3' => 'La maggior parte dei visitatori lo combina con un itinerario di mezza giornata, anche se serve anche come trekking di acclimatazione prima di scalare il Monte Meru, la cui vetta si trova all\'interno dei confini del parco.',
    'arusha_fact_area' => 'Superficie',
    'arusha_fact_established' => 'Istituito nel',
    'arusha_fact_meru' => 'Vetta del Monte Meru',
    'arusha_fact_birds' => 'Specie di uccelli',
    'arusha_fact_lions' => 'Predatori',
    'arusha_fact_lions_value' => 'Leopardo, presente ma raramente visto',
    'arusha_fact_stay' => 'Visita tipica',
    'arusha_fact_stay_value' => 'Mezza giornata, o 3–4 giorni per il Meru',
    'arusha_fact_from_arusha' => 'Da Arusha città',
    'arusha_fact_from_airport' => 'Dall\'Aeroporto del Kilimanjaro',

    'arusha_regions_badge' => 'Tre paesaggi in un solo parco',
    'arusha_regions_title' => 'Cosa vedere',
    'arusha_regions_intro' => 'Arusha racchiude una varietà insolita di terreni in una piccola area — pianifica il tuo percorso intorno a queste tre zone.',
    'arusha_region_ngurdoto_name' => 'Cratere di Ngurdoto',
    'arusha_region_ngurdoto_desc' => 'Un fondo di cratere lussureggiante e paludoso circondato dalla foresta — spesso chiamato "Piccolo Ngorongoro". I veicoli non possono scendervi, quindi l\'osservazione avviene dal bordo, guardando bufali, facoceri e cobi d\'acqua pascolare sotto.',
    'arusha_region_momella_name' => 'Laghi Momella',
    'arusha_region_momella_desc' => 'Una catena di laghi alcalini poco profondi, ciascuno di una diversa tonalità di verde o blu a seconda del contenuto di alghe e minerali. Fenicotteri, giraffe e bufali si radunano sulle rive, ed è qui che partono i safari in canoa.',
    'arusha_region_meru_name' => 'Monte Meru',
    'arusha_region_meru_desc' => 'La quinta vetta più alta d\'Africa a 4.566m, e lo sfondo drammatico della maggior parte del parco. Scalabile in 3–4 giorni, con molti meno escursionisti rispetto al Kilimanjaro e viste superbe sullo stesso Kilimanjaro nelle giornate limpide.',

    'arusha_walking_badge' => 'Un permesso raro',
    'arusha_walking_title' => 'Safari a piedi',
    'arusha_walking_intro' => 'Arusha è uno dei soli tre parchi in Tanzania dove sono consentiti i safari a piedi — la maggior parte dei parchi del circuito nord richiede di restare nel veicolo.',
    'arusha_walking_p1' => 'Passeggiate guidate con un ranger armato ti permettono di avvicinarti a piedi a giraffe, zebre e bufali, leggendo tracce e escrementi, e ascoltando il bush a livello del terreno anziché attraverso un parabrezza.',
    'arusha_walking_p2' => 'Poiché i grandi predatori sono in gran parte assenti, camminare qui è più sicuro rispetto ai parchi più grandi — gli incontri pericolosi sono quasi sempre con i bufali, che il ranger è addestrato a gestire a distanza di sicurezza.',

    'arusha_wildlife_badge' => 'Chi vive qui',
    'arusha_wildlife_title' => 'Fauna selvatica',
    'arusha_wildlife_intro' => 'Arusha non ha leoni e pochissima della classica "grande fauna" del Serengeti — la sua attrazione faunistica è diversa: primati, uccelli e specie forestali che non vedrai in un safari nella savana.',
    'arusha_animal_giraffe' => 'Giraffa',
    'arusha_animal_colobus' => 'Colobo bianco e nero',
    'arusha_animal_zebra' => 'Zebra',
    'arusha_animal_buffalo' => 'Bufalo',
    'arusha_animal_waterbuck' => 'Cobo d\'acqua',
    'arusha_animal_flamingo' => 'Fenicottero',
    'arusha_animal_elephant' => 'Elefante (occasionale)',
    'arusha_animal_warthog' => 'Facocero',
    'arusha_wildlife_p1' => 'La vera specialità del parco sono i suoi gruppi di colobi bianchi e neri, facilmente visibili nella foresta montana, insieme a oltre 400 specie di uccelli registrate solo intorno ai laghi Momella.',
    'arusha_wildlife_p2' => 'Gli avvistamenti di elefanti avvengono ma sono occasionali piuttosto che affidabili — questo non è il parco da scegliere se i Big Five sono la tua priorità, ma ripaga i visitatori interessati a paesaggi, uccelli e un ritmo più tranquillo.',

    'arusha_when_badge' => 'Pianificazione',
    'arusha_when_title' => 'Quando andare',
    'arusha_when_intro' => 'Arusha è un parco visitabile tutto l\'anno — la sua bassa altitudine e la vicinanza alla città fanno sì che raramente chiuda, a differenza dei trekking ad alta quota.',
    'arusha_when_p1' => 'Da giugno a ottobre (stagione secca) offre le viste più nitide del Monte Meru e del Kilimanjaro, e le condizioni di trekking più facili.',
    'arusha_when_p2' => 'I mesi più piovosi (marzo–maggio) rendono il cratere e le rive dei laghi di un verde vivido e portano più uccelli, anche se i sentieri possono essere fangosi e le viste sulla montagna meno affidabili.',

    'arusha_stay_badge' => 'Dove alloggiare',
    'arusha_stay_title' => 'Alloggio',
    'arusha_stay_intro' => 'La maggior parte dei visitatori si basa nella città di Arusha e visita il parco in giornata, ma alcune strutture si trovano vicino all\'ingresso del parco per chi scala il Meru o lo combina con un altro parco.',
    'arusha_stay_town_title' => 'Città di Arusha',
    'arusha_stay_town_price' => 'Economico – Lusso',
    'arusha_stay_town_desc' => 'La scelta più comune — 30–40 minuti dall\'ingresso del parco, con la più ampia gamma di hotel e trasferimenti agevoli verso l\'Aeroporto del Kilimanjaro o il circuito del nord.',
    'arusha_stay_lodge_title' => 'Lodge vicino all\'ingresso',
    'arusha_stay_lodge_price' => 'Fascia media – Lusso',
    'arusha_stay_lodge_desc' => 'Alcuni lodge si trovano a breve distanza dall\'ingresso del parco, utili per una partenza mattutina per una scalata al Meru o un safari a piedi all\'alba.',
    'arusha_stay_camp_title' => 'Rifugi di montagna del Meru',
    'arusha_stay_camp_price' => 'Incluso nel pacchetto trekking',
    'arusha_stay_camp_desc' => 'Gli scalatori pernottano in una serie di rifugi di montagna durante la salita — Miriakamba e Saddle Hut — inclusi in ogni pacchetto di trekking al Monte Meru.',
    'arusha_stay_note' => 'Possiamo organizzare l\'alloggio a qualsiasi livello come parte di un\'escursione giornaliera o di un pacchetto trekking al Meru — chiedici la disponibilità attuale.',

    'arusha_fees_badge' => 'Tasse 2026',
    'arusha_fees_title' => 'Tasse di ingresso al parco',
    'arusha_fees_intro' => 'Le tasse sono per persona per periodo di 24 ore e includono il 18% di IVA. Pagabili con carta o tessera parco prepagata — il contante non è accettato all\'ingresso.',
    'arusha_table_category' => 'Categoria',
    'arusha_table_adult' => 'Adulto',
    'arusha_table_child' => 'Bambino (5–15)',
    'arusha_fee_entry' => 'Ingresso al parco',
    'arusha_fee_concession' => 'Concessione trekking Meru',
    'arusha_fee_campsite' => 'Tassa di campeggio',
    'arusha_fees_note' => 'Quando viaggi con noi, tutte le tasse del parco sono calcolate e incluse nel prezzo preventivato — nessun pagamento separato necessario all\'ingresso.',

    'arusha_gallery_badge' => 'Arusha in immagini',
    'arusha_gallery_title' => 'Cosa vedrai',
    'arusha_gallery_caption_1' => 'Colobi nella foresta',
    'arusha_gallery_caption_2' => 'Savana all\'alba',
    'arusha_gallery_caption_3' => 'Canoa sui laghi Momella',
    'arusha_gallery_caption_4' => 'Zebre nella pianura',
    'arusha_gallery_caption_5' => 'Elefante sotto un\'acacia',
    'arusha_gallery_caption_6' => 'Il bordo di un cratere, simile per forma a Ngurdoto',

    'arusha_back_to_parks' => 'Confronta tutti i nove parchi',

    'arusha_faq_badge' => 'FAQ',
    'arusha_faq_title' => 'Domande comuni',
    'arusha_faq_q1' => 'Posso visitare il Parco Nazionale di Arusha in mezza giornata?',
    'arusha_faq_a1' => 'Sì — è il modo più comune di visitarlo, solitamente combinato con una partenza mattutina dalla città di Arusha e il rientro nel primo pomeriggio.',
    'arusha_faq_q2' => 'Vedrò i Big Five qui?',
    'arusha_faq_a2' => 'No — Arusha non ha leoni né rinoceronti, e gli avvistamenti di elefanti sono occasionali. Viene scelto per i paesaggi, i safari a piedi, i colobi e l\'avifauna piuttosto che per i Big Five.',
    'arusha_faq_q3' => 'Camminare qui è sicuro?',
    'arusha_faq_a3' => 'Sì, relativamente — l\'assenza di leoni rende Arusha uno dei parchi più sicuri per camminare, anche se i bufali richiedono comunque cautela e un ranger armato accompagna sempre i gruppi a piedi.',
    'arusha_faq_q4' => 'Posso scalare il Monte Meru senza scalare il Kilimanjaro?',
    'arusha_faq_a4' => 'Sì, il Meru è un trekking a sé stante e una scelta popolare di per sé — molti scalatori lo preferiscono per i sentieri più tranquilli e la drammatica camminata sul bordo del cratere.',
    'arusha_faq_q5' => 'Come si confronta il Meru con il Kilimanjaro come scalata?',
    'arusha_faq_a5' => 'Il Meru è più breve (3–4 giorni contro 5–9), più ripido in alcuni tratti, e molto meno affollato. Viene anche comunemente usato come pratica di acclimatazione prima di un tentativo al Kilimanjaro.',
    'arusha_faq_q6' => 'Posso combinare Arusha con altri parchi?',
    'arusha_faq_a6' => 'Sì — la sua vicinanza alla città lo rende un facile aggiunta a un itinerario a Tarangire o Ngorongoro, o un rilassato primo/ultimo giorno di un safari più lungo.',
    'arusha_faq_q7' => 'Ci sono safari in canoa?',
    'arusha_faq_a7' => 'Sì, sui laghi Momella — un modo tranquillo per vedere ippopotami, fenicotteri e uccelli acquatici dall\'acqua, solitamente combinato con una parte a piedi o in veicolo della visita.',
    'arusha_faq_q8' => 'È richiesta una guida?',
    'arusha_faq_a8' => 'Sì per i safari a piedi e il trekking al Meru (un ranger armato è obbligatorio), e fortemente raccomandata per i game drive data la segnaletica limitata all\'interno del parco.',

    'arusha_cta_title' => 'Pronto a visitare il Parco Nazionale di Arusha?',
    'arusha_cta_intro' => 'Inviaci le tue date e la dimensione del gruppo. Ti rispondiamo con un itinerario scritto e il prezzo completo — senza impegno.',
    'arusha_cta_whatsapp' => 'Scrivici su WhatsApp',
    'arusha_cta_safaris' => 'Vedi i pacchetti safari',

    'kilimanjaro_meta_title' => 'Guida al Parco Nazionale del Kilimanjaro (2026) | Serengeti Budget Safari',
    'kilimanjaro_meta_description' => 'Guida al Parco Nazionale del Kilimanjaro: tutte e sette le route a confronto, tasse del parco 2026, tassi di successo, mal di montagna, quando scalare e dove dormire sulla montagna.',
    'kilimanjaro_hero_badge' => 'Parco Nazionale del Kilimanjaro',
    'kilimanjaro_hero_title' => 'Parco Nazionale del Kilimanjaro',
    'kilimanjaro_hero_sub' => 'Il punto più alto d\'Africa a 5.895m — cinque zone climatiche, sette route, e una vetta alla portata di qualsiasi camminatore ragionevolmente in forma.',
    'kilimanjaro_hero_cta_quote' => 'Richiedi un preventivo',

    'kilimanjaro_intro_badge' => 'Panoramica',
    'kilimanjaro_intro_title' => 'Il tetto dell\'Africa',
    'kilimanjaro_intro_p1' => 'Il Kilimanjaro è la montagna più alta d\'Africa e la vetta indipendente più alta del mondo — si innalza dalla savana a circa 900m fino a una vetta ghiacciata a 5.895m senza una catena montuosa collegata. La scalata è una lunga camminata, non un\'ascesa tecnica: niente corde, niente attrezzatura da arrampicata, solo diversi giorni di cammino costante in salita attraverso cinque distinte zone climatiche.',
    'kilimanjaro_intro_p2' => 'Quelle zone — terreno coltivato, foresta pluviale, brughiera, deserto alpino e la zona artica della vetta — fanno sì che un trekking sul Kilimanjaro sembri camminare dall\'equatore ai poli in meno di una settimana.',
    'kilimanjaro_intro_p3' => 'La vera sfida è l\'altitudine, non la forma fisica o l\'abilità tecnica. Il fattore singolo più importante per raggiungere la vetta è scegliere una route con giorni sufficienti per l\'acclimatazione del corpo.',
    'kilimanjaro_fact_area' => 'Superficie del parco',
    'kilimanjaro_fact_summit' => 'Vetta',
    'kilimanjaro_fact_status' => 'Stato',
    'kilimanjaro_fact_routes' => 'Route',
    'kilimanjaro_fact_duration' => 'Durata tipica',
    'kilimanjaro_fact_success' => 'Intervallo tasso di successo',
    'kilimanjaro_fact_climbers' => 'Scalatori all\'anno',
    'kilimanjaro_fact_days' => 'Minimo raccomandato',
    'kilimanjaro_fact_year' => '5+ giorni',
    'kilimanjaro_fact_from_arusha' => 'Da Arusha',

    'kilimanjaro_routes_badge' => 'Scegli il tuo percorso',
    'kilimanjaro_routes_title' => 'Le route',
    'kilimanjaro_routes_intro' => 'Sette route ufficiali raggiungono la vetta — queste quattro sono quelle che organizziamo, scelte per il loro profilo di acclimatazione e affidabilità.',
    'kilimanjaro_route_marangu_name' => 'Marangu',
    'kilimanjaro_route_marangu_desc' => 'L\'unica route con alloggio in rifugio invece delle tende, e lo stesso percorso usato sia per la salita che per la discesa. L\'opzione più breve, che le conferisce anche il tasso di successo più basso — meno tempo per acclimatarsi.',
    'kilimanjaro_route_machame_name' => 'Machame',
    'kilimanjaro_route_machame_desc' => 'Conosciuta come la "Whiskey Route" per la sua reputazione di scalata più impegnativa. Panoramica e varia, con campeggio in tenda, ed è la route più popolare della montagna grazie al suo solido profilo di acclimatazione.',
    'kilimanjaro_route_lemosho_name' => 'Lemosho',
    'kilimanjaro_route_lemosho_desc' => 'Un inizio più tranquillo attraverso foresta pluviale incontaminata, che si unisce alla route Machame più in alto. Ampiamente considerata la migliore combinazione di panorama e acclimatazione.',
    'kilimanjaro_route_rongai_name' => 'Rongai',
    'kilimanjaro_route_rongai_desc' => 'Si avvicina dal lato nord più secco della montagna, vicino al confine keniota. La scelta migliore durante i mesi di transizione piovosi, quando le route meridionali sono più umide.',

    'kilimanjaro_compare_badge' => 'A confronto',
    'kilimanjaro_compare_title' => 'Confronta tutte le route',
    'kilimanjaro_compare_intro' => 'I tassi di successo sono indicativi — aumentano notevolmente con più giorni sulla montagna, indipendentemente dalla route.',
    'kilimanjaro_table_route' => 'Route',
    'kilimanjaro_table_days' => 'Giorni',
    'kilimanjaro_table_sleeping' => 'Pernottamento',
    'kilimanjaro_table_scenery' => 'Panorama',
    'kilimanjaro_table_success' => 'Tasso di successo',
    'kilimanjaro_sleep_tents' => 'Tende',
    'kilimanjaro_sleep_huts' => 'Rifugi',
    'kilimanjaro_scenery_varied' => 'Vario, ripido in alcuni tratti',
    'kilimanjaro_scenery_best' => 'Il migliore in assoluto',
    'kilimanjaro_scenery_full' => 'Circuito completo della montagna',
    'kilimanjaro_scenery_direct' => 'Diretto, meno vario',
    'kilimanjaro_scenery_dry' => 'Più secco, sentieri più tranquilli',
    'kilimanjaro_northern_circuit' => 'Northern Circuit',
    'kilimanjaro_compare_note' => 'La notte extra su una route più lunga è l\'assicurazione più economica che puoi comprare contro il mal di montagna — se il tuo programma lo consente, scegli l\'opzione più lunga.',

    'kilimanjaro_wildlife_badge' => 'Durante la salita',
    'kilimanjaro_wildlife_title' => 'Fauna selvatica sulla montagna',
    'kilimanjaro_wildlife_intro' => 'Il Kilimanjaro non è una destinazione per l\'osservazione della fauna, ma le zone forestali inferiori hanno un genuino interesse faunistico — la maggior parte degli scalatori si sorprende di quanta vita esista sui fianchi della montagna.',
    'kilimanjaro_animal_colobus' => 'Colobo bianco e nero',
    'kilimanjaro_animal_blue_monkey' => 'Cercopiteco blu',
    'kilimanjaro_animal_bushbuck' => 'Tragelafo striato',
    'kilimanjaro_animal_buffalo' => 'Bufalo (zona forestale)',
    'kilimanjaro_animal_elephant' => 'Elefante (zona forestale, raro)',
    'kilimanjaro_animal_sunbird' => 'Nettarinia malachite',
    'kilimanjaro_animal_raven' => 'Corvo collobianco',
    'kilimanjaro_animal_groundsel' => 'Senecio gigante (pianta)',
    'kilimanjaro_wildlife_p1' => 'La zona di foresta pluviale, attraversata nel primo giorno o due sulla maggior parte delle route, ospita colobi e cercopitechi blu, antilopi forestali e occasionali bufali o elefanti — tutti incontrati lungo il sentiero piuttosto che cercati appositamente.',
    'kilimanjaro_wildlife_p2' => 'Sopra la foresta, le zone di brughiera e alpine sono più strane che selvagge — senecio giganti e lobelie che non si trovano da nessun\'altra parte, e uccelli come il corvo collobianco che seguono gli scalatori per gli avanzi ai campi alti.',

    'kilimanjaro_when_badge' => 'Pianificazione',
    'kilimanjaro_when_title' => 'Quando scalare',
    'kilimanjaro_when_intro' => 'Il Kilimanjaro può tecnicamente essere scalato tutto l\'anno, ma le condizioni variano considerevolmente a seconda della stagione.',
    'kilimanjaro_when_p1' => 'Da gennaio a inizio marzo e da giugno a ottobre sono le due finestre secche — le condizioni più affidabili, le viste sulla vetta più nitide e i sentieri più affollati, specialmente luglio–settembre.',
    'kilimanjaro_when_p2' => 'Aprile, maggio e novembre sono i mesi piovosi. La montagna rimane aperta e scalabile, ma i sentieri sono scivolosi e la copertura nuvolosa spesso nasconde la vetta — Rongai, sul lato nord più secco, è la scelta migliore se devi scalare in questo periodo.',

    'kilimanjaro_stay_badge' => 'Dove dormi',
    'kilimanjaro_stay_title' => 'Alloggio sulla montagna',
    'kilimanjaro_stay_intro' => 'Dove dormi dipende interamente dalla route scelta — è fisso, non una questione di fascia di budget.',
    'kilimanjaro_stay_huts_title' => 'Rifugi di montagna (solo Marangu)',
    'kilimanjaro_stay_huts_price' => 'Incluso nella route Marangu',
    'kilimanjaro_stay_huts_desc' => 'Rifugi in stile dormitorio con letti a castello, sale da pranzo condivise e servizi essenziali — l\'unica route che offre questa opzione, e parte del motivo per cui è la più breve e conveniente.',
    'kilimanjaro_stay_camping_title' => 'Campeggio in montagna (tutte le altre route)',
    'kilimanjaro_stay_camping_price' => 'Incluso nel prezzo della route',
    'kilimanjaro_stay_camping_desc' => 'Tende per due persone trasportate e montate dalla squadra a ogni campo, con una tenda mensa separata per i pasti — lo standard per Machame, Lemosho, Rongai e il Northern Circuit.',
    'kilimanjaro_stay_private_title' => 'Arusha, prima e dopo',
    'kilimanjaro_stay_private_price' => 'Incluso in ogni pacchetto',
    'kilimanjaro_stay_private_desc' => 'Una notte in hotel ad Arusha prima della scalata e dopo la discesa è inclusa in ogni pacchetto Kilimanjaro che organizziamo, per una doccia calda e un vero letto prima e dopo la montagna.',
    'kilimanjaro_stay_note' => 'Tutto l\'alloggio in montagna — rifugi o tende — è incluso nel prezzo del pacchetto trekking, insieme a tutte le tasse di campeggio e rifugio.',

    'kilimanjaro_fees_badge' => 'Tasse 2026',
    'kilimanjaro_fees_title' => 'Tasse del parco',
    'kilimanjaro_fees_intro' => 'Le tasse sono dettagliate per persona e incluse nel tuo pacchetto trekking — mostrate qui così sai esattamente per cosa stai pagando.',
    'kilimanjaro_table_category' => 'Tassa',
    'kilimanjaro_table_basis' => 'Base',
    'kilimanjaro_table_adult' => 'Adulto (USD)',
    'kilimanjaro_table_child' => 'Bambino (5–15)',
    'kilimanjaro_fee_conservation' => 'Tassa di conservazione',
    'kilimanjaro_fee_camping' => 'Tassa di campeggio',
    'kilimanjaro_fee_huts' => 'Tassa rifugio (Marangu)',
    'kilimanjaro_fee_rescue' => 'Tassa di soccorso',
    'kilimanjaro_fee_basis_day' => 'Al giorno',
    'kilimanjaro_fee_basis_night' => 'A notte',
    'kilimanjaro_fee_basis_once' => 'Una volta per trekking',
    'kilimanjaro_fees_example' => 'Per una scalata Lemosho di 7 giorni, solo le tasse del parco totalizzano circa 956 $ a persona — questo è completamente separato dai costi di guida, portatori, cibo e attrezzatura.',
    'kilimanjaro_fees_note' => 'Quando scali con noi, tutte le tasse del parco sono calcolate e incluse nel prezzo del trekking preventivato — nessun pagamento separato necessario all\'ingresso.',

    'kilimanjaro_gallery_badge' => 'Il Kilimanjaro in immagini',
    'kilimanjaro_gallery_title' => 'La montagna',
    'kilimanjaro_gallery_caption_1' => 'Savana alla base della montagna',
    'kilimanjaro_gallery_caption_2' => 'Fauna selvatica nelle pianure circostanti',
    'kilimanjaro_gallery_caption_3' => 'Una guida con gli scalatori prima dell\'ascesa',

    'kilimanjaro_back_to_parks' => 'Confronta tutti i nove parchi',

    'kilimanjaro_faq_badge' => 'FAQ',
    'kilimanjaro_faq_title' => 'Domande comuni',
    'kilimanjaro_faq_q1' => 'Serve esperienza di scalata?',
    'kilimanjaro_faq_a1' => 'No. Il Kilimanjaro è una lunga camminata, non una scalata tecnica — non ci sono corde né arrampicata. Ciò che richiede è resistenza per cinque-nove giorni di cammino e la capacità di gestire l\'aria rarefatta.',
    'kilimanjaro_faq_q2' => 'Quale route ha il tasso di successo più alto?',
    'kilimanjaro_faq_a2' => 'Il Northern Circuit e Lemosho, entrambi intorno al 90–95%, grazie al loro profilo di acclimatazione più lungo. Marangu, la route più breve, ha il tasso di successo più basso, circa il 50–60%.',
    'kilimanjaro_faq_q3' => 'E il mal di montagna?',
    'kilimanjaro_faq_a3' => 'Lievi mal di testa e affanno sono normali sopra i 4.000m. Le nostre guide controllano la saturazione di ossigeno due volte al giorno e portano un kit di primo soccorso — se una guida giudica che devi scendere, scendi, senza eccezioni.',
    'kilimanjaro_faq_q4' => 'Quanto devo essere in forma?',
    'kilimanjaro_faq_a4' => 'Non è richiesta una forma fisica da scalata tecnica, ma diverse ore di allenamento a piedi in precedenza fanno una vera differenza — la sfida è resistenza e altitudine, non forza.',
    'kilimanjaro_faq_q5' => 'Qual è il numero minimo di giorni?',
    'kilimanjaro_faq_a5' => 'Cinque giorni (Marangu) è il minimo legale, ma raccomandiamo almeno sei o sette giorni per una possibilità significativamente migliore di raggiungere la vetta.',
    'kilimanjaro_faq_q6' => 'I principianti possono scalare il Kilimanjaro?',
    'kilimanjaro_faq_a6' => 'Sì — non è richiesta esperienza di trekking precedente, anche se un po\' di forma fisica da escursionismo aiuta. Molti dei nostri scalatori non avevano mai fatto un trekking di più giorni prima.',
    'kilimanjaro_faq_q7' => 'Cosa è incluso in un pacchetto trekking?',
    'kilimanjaro_faq_a7' => 'Tutte le tasse del parco, una guida certificata, cuoco e portatori, pasti e acqua potabile in montagna, tasse di campeggio o rifugio, e trasferimenti ad Arusha — vedi l\'elenco completo di incluso/escluso sulla nostra pagina trekking.',
    'kilimanjaro_faq_q8' => 'Viene usato ossigeno portatile?',
    'kilimanjaro_faq_a8' => 'Non di routine — è disponibile su richiesta come misura di sicurezza extra, ma la corretta acclimatazione attraverso la scelta della route è la strategia principale su cui facciamo affidamento.',

    'kilimanjaro_cta_title' => 'Pronto a scalare il Kilimanjaro?',
    'kilimanjaro_cta_intro' => 'Inviaci le tue date e la route preferita. Ti rispondiamo con un itinerario scritto e il prezzo completo — senza impegno.',
    'kilimanjaro_cta_whatsapp' => 'Scrivici su WhatsApp',
