    'ruaha_meta_title' => 'Guida al Parco Nazionale di Ruaha (2026) | Serengeti Budget Safari',
    'ruaha_meta_description' => 'Guida al Parco Nazionale di Ruaha: il parco più grande della Tanzania, circa il 10% dei leoni del mondo, enormi mandrie di elefanti, licaoni, tasse del parco 2026 e dove alloggiare.',
    'ruaha_hero_badge' => 'Parco Nazionale di Ruaha',
    'ruaha_hero_title' => 'Parco Nazionale di Ruaha',
    'ruaha_hero_sub' => 'Il parco nazionale più grande della Tanzania — selvaggio, remoto, e casa di circa un decimo dei leoni rimasti al mondo.',
    'ruaha_hero_cta_quote' => 'Richiedi un preventivo',

    'ruaha_intro_badge' => 'Panoramica',
    'ruaha_intro_title' => 'Grande, selvaggio e quasi vuoto',
    'ruaha_intro_p1' => 'Ruaha è il parco nazionale più grande della Tanzania, con oltre 20.000 km² — più grande del Serengeti — eppure riceve una frazione dei visitatori, a causa del volo aggiuntivo richiesto da Dar es Salaam invece di un trasferimento stradale da Arusha.',
    'ruaha_intro_p2' => 'Quella distanza è esattamente il suo fascino: vaste pianure punteggiate di baobab, il Grande Fiume Ruaha, e alcune delle più alte densità di predatori in Africa, viste da un veicolo che spesso avrai tutto per te.',
    'ruaha_intro_p3' => 'Ripaga i viaggiatori che hanno già fatto il circuito del nord e vogliono qualcosa di genuinamente diverso — cieli più ampi, piste più accidentate, e una fauna selvatica che reagisce ai veicoli come dovrebbe, come una novità piuttosto che un evento quotidiano.',
    'ruaha_fact_area' => 'Superficie',
    'ruaha_fact_rank' => 'Classifica per dimensione',
    'ruaha_fact_rank_value' => 'Il parco più grande della Tanzania',
    'ruaha_fact_lions' => 'Popolazione di leoni',
    'ruaha_fact_lions_of_world' => '~10% dei leoni selvatici del mondo',
    'ruaha_fact_elephants' => 'Popolazione di elefanti',
    'ruaha_fact_kudu' => 'Specie notevoli',
    'ruaha_fact_kudu_value' => 'Grande e piccolo kudù',
    'ruaha_fact_visitors' => 'Densità di visitatori',
    'ruaha_fact_visitors_value' => 'Molto bassa',
    'ruaha_fact_stay' => 'Soggiorno consigliato',
    'ruaha_fact_days' => '3–4 giorni',
