    'ruaha_regions_badge' => 'Il paesaggio',
    'ruaha_regions_title' => 'Cosa vedere',
    'ruaha_regions_intro' => 'Ruaha alterna tre paesaggi distinti nella sua vasta area.',
    'ruaha_region_river_name' => 'Il Grande Fiume Ruaha',
    'ruaha_region_river_desc' => 'La linfa vitale del parco — durante la stagione secca, la fauna selvatica si concentra lungo le sue rive e banchi di sabbia in numeri che rivaleggiano con qualsiasi attraversamento di fiume del circuito del nord, senza la folla.',
    'ruaha_region_baobab_name' => 'Pianure di baobab',
    'ruaha_region_baobab_desc' => 'Colline ondulate punteggiate da antichi baobab, alcuni stimati con oltre mille anni di vita, che conferiscono a Ruaha una silhouette distintiva diversa da qualsiasi parco del nord.',
    'ruaha_region_miombo_name' => 'Foresta di miombo',
    'ruaha_region_miombo_desc' => 'Vasti tratti di foresta di miombo coprono gran parte dell\'interno del parco, casa di specie come il grande kudù e l\'antilope sable che preferiscono questo habitat rispetto alla prateria aperta.',

    'ruaha_wildlife_badge' => 'Chi vive qui',
    'ruaha_wildlife_title' => 'Fauna selvatica',
    'ruaha_wildlife_intro' => 'Ruaha si trova alla sovrapposizione tra specie dell\'Africa orientale e meridionale, dandogli una delle liste faunistiche più diverse di qualsiasi parco tanzaniano.',
    'ruaha_animal_lion' => 'Leone',
    'ruaha_animal_elephant' => 'Elefante',
    'ruaha_animal_leopard' => 'Leopardo',
    'ruaha_animal_cheetah' => 'Ghepardo',
    'ruaha_animal_wilddog' => 'Licaone africano',
    'ruaha_animal_buffalo' => 'Bufalo',
    'ruaha_animal_giraffe' => 'Giraffa',
    'ruaha_animal_zebra' => 'Zebra',
    'ruaha_animal_kudu' => 'Grande kudù',
    'ruaha_animal_hippo' => 'Ippopotamo',
    'ruaha_wildlife_p1' => 'Ruaha ospita circa il 10% dei leoni selvatici rimasti al mondo e una popolazione di elefanti tra le più grandi dell\'Africa orientale, insieme a un buon numero di leopardi e una delle migliori possibilità in Tanzania di incontrare il licaone africano.',
    'ruaha_wildlife_p2' => 'La combinazione di specie dell\'Africa orientale (leone, giraffa, zebra) e specie dell\'Africa meridionale (grande kudù, sable, antilope roana) che non si trova da nessun\'altra parte nel circuito del nord è parte di ciò che rende Ruaha genuinamente unico.',

    'ruaha_when_badge' => 'Pianificazione',
    'ruaha_when_title' => 'Quando andare',
    'ruaha_when_intro' => 'Ruaha si visita al meglio nella stagione secca, quando la fauna selvatica si concentra in modo prevedibile lungo il fiume.',
    'ruaha_when_p1' => 'Da giugno a ottobre è il picco della stagione secca — il fiume si riduce a pozze e banchi di sabbia, attirando grandi concentrazioni di fauna e i migliori avvistamenti di predatori dell\'anno.',
    'ruaha_when_p2' => 'Da novembre a maggio arrivano le piogge: il parco diventa verde, molti campi chiudono per la stagione, e le strade possono diventare impraticabili — non è un periodo realistico per la maggior parte dei visitatori.',

    'ruaha_stay_badge' => 'Dove alloggiare',
    'ruaha_stay_title' => 'Alloggio',
    'ruaha_stay_intro' => 'La lontananza di Ruaha significa meno strutture rispetto al circuito del nord, ma una buona distribuzione tra le fasce di budget vicino al fiume.',
    'ruaha_stay_budget_title' => 'Campi economici',
    'ruaha_stay_budget_price' => 'Campeggio / tenda base',
    'ruaha_stay_budget_desc' => 'Semplici campi tendati con servizi condivisi, gestiti da piccoli operatori locali — il modo più economico per vivere il parco.',
    'ruaha_stay_mid_title' => 'Campi fascia media',
    'ruaha_stay_mid_price' => 'Tented camp, con bagno privato',
    'ruaha_stay_mid_desc' => 'Confortevoli tented camp permanenti con bagni privati, spesso situati lungo la riva del fiume per viste sulla fauna direttamente dal campo.',
    'ruaha_stay_luxury_title' => 'Campi di lusso',
    'ruaha_stay_luxury_price' => 'Tented camp premium',
    'ruaha_stay_luxury_desc' => 'Un piccolo numero di campi di fascia alta offre guida privata, terrazze panoramiche rialzate e una sensazione genuinamente esclusiva data la scarsità di visitatori che il parco riceve.',
    'ruaha_stay_note' => 'Possiamo organizzare l\'alloggio a qualsiasi livello come parte del tuo itinerario a Ruaha, incluso il trasferimento in aereo leggero da Dar es Salaam.',

    'ruaha_fees_badge' => 'Tasse 2026',
    'ruaha_fees_title' => 'Tasse di ingresso al parco',
    'ruaha_fees_intro' => 'Le tasse sono per persona per periodo di 24 ore e includono il 18% di IVA. Pagabili con carta o tessera parco prepagata — il contante non è accettato all\'ingresso.',
    'ruaha_table_category' => 'Categoria',
    'ruaha_table_adult' => 'Adulto',
    'ruaha_table_child' => 'Bambino (5–15)',
    'ruaha_fee_entry' => 'Ingresso al parco',
    'ruaha_fee_concession' => 'Tassa di concessione',
    'ruaha_fee_campsite' => 'Tassa di campeggio',
    'ruaha_fees_note' => 'Quando viaggi con noi, tutte le tasse del parco sono calcolate e incluse nel prezzo preventivato — nessun pagamento separato necessario all\'ingresso.',

    'ruaha_gallery_badge' => 'Ruaha in immagini',
    'ruaha_gallery_title' => 'Cosa vedrai',
    'ruaha_gallery_caption_1' => 'Branco di leoni nella pianura',
    'ruaha_gallery_caption_2' => 'Mandria di elefanti sulla riva del fiume',
    'ruaha_gallery_caption_3' => 'Leopardo che riposa su un albero',
    'ruaha_gallery_caption_4' => 'Zebre che attraversano la prateria',
