    'ruaha_back_to_parks' => 'Confronta tutti i nove parchi',

    'ruaha_faq_badge' => 'FAQ',
    'ruaha_faq_title' => 'Domande comuni',
    'ruaha_faq_q1' => 'Come si arriva a Ruaha?',
    'ruaha_faq_a1' => 'In aereo leggero da Dar es Salaam — non esiste un percorso stradale pratico da Arusha. I voli richiedono tipicamente circa due ore.',
    'ruaha_faq_q2' => 'Ruaha vale il costo del volo aggiuntivo?',
    'ruaha_faq_a2' => 'Per i viaggiatori che hanno già visto il circuito del nord, sì — la densità della fauna selvatica rivaleggia con il Serengeti con una frazione dei veicoli, il che è un\'esperienza genuinamente diversa.',
    'ruaha_faq_q3' => 'Quanti giorni mi servono?',
    'ruaha_faq_a3' => 'Tre o quattro giorni ti permettono di esplorare adeguatamente le aree fluviali e boschive senza sentirti di fretta, date le distanze di guida coinvolte.',
    'ruaha_faq_q4' => 'Posso combinare Ruaha con altri parchi del sud?',
    'ruaha_faq_a4' => 'Sì — Ruaha si abbina naturalmente con Nyerere (Selous) per un safari sul circuito del sud, entrambi raggiungibili da Dar es Salaam.',
    'ruaha_faq_q5' => 'Vedrò i licaoni?',
    'ruaha_faq_a5' => 'Ruaha è uno dei posti migliori in Tanzania per il licaone africano, anche se gli avvistamenti non sono mai garantiti per nessun animale selvatico — un soggiorno di più giorni migliora considerevolmente le tue probabilità.',
    'ruaha_faq_q6' => 'Ruaha è adatto alla fotografia?',
    'ruaha_faq_a6' => 'Molto — la bassa densità di veicoli significa avvistamenti ininterrotti e il paesaggio di baobab offre sfondi drammatici raramente disponibili nei parchi del nord più affollati.',
    'ruaha_faq_q7' => 'Qual è il periodo migliore per vedere i leoni?',
    'ruaha_faq_a7' => 'Tutto l\'anno, ma la stagione secca (giugno–ottobre) li concentra più prevedibilmente lungo il fiume, dove si radunano anche gli animali preda.',
    'ruaha_faq_q8' => 'Ruaha è adatto per un primo safari?',
    'ruaha_faq_a8' => 'Può esserlo, ma la maggior parte dei visitatori alla prima esperienza è meglio servita iniziando con il circuito del nord per i trasferimenti più brevi e l\'infrastruttura più sviluppata — Ruaha ripaga i viaggiatori che già sanno cosa vogliono da un safari.',

    'ruaha_cta_title' => 'Pronto a visitare Ruaha?',
    'ruaha_cta_intro' => 'Inviaci le tue date e la dimensione del gruppo. Ti rispondiamo con un itinerario scritto e il prezzo completo — senza impegno.',
    'ruaha_cta_whatsapp' => 'Scrivici su WhatsApp',
