    'mikumi_meta_title' => 'Guida al Parco Nazionale di Mikumi (2026) | Serengeti Budget Safari',
    'mikumi_meta_description' => 'Guida al Parco Nazionale di Mikumi: il safari vero più economico della Tanzania, a quattro ore da Dar es Salaam su strada, senza bisogno di volo. Tasse 2026, fauna e quando andare.',
    'mikumi_hero_badge' => 'Parco Nazionale di Mikumi',
    'mikumi_hero_title' => 'Parco Nazionale di Mikumi',
    'mikumi_hero_sub' => 'Il safari vero più economico della Tanzania — quattro ore da Dar es Salaam su strada, nessun volo interno richiesto.',
    'mikumi_hero_cta_quote' => 'Richiedi un preventivo',

    'mikumi_intro_badge' => 'Panoramica',
    'mikumi_intro_title' => 'Un vero safari senza il volo',
    'mikumi_intro_p1' => 'Mikumi è il più accessibile dei parchi del sud della Tanzania — un semplice viaggio di quattro ore da Dar es Salaam su strada asfaltata, senza bisogno di volo interno. Questa accessibilità, unita a tasse del parco più basse rispetto al circuito del nord, lo rende il safari vero più economico del paese.',
    'mikumi_intro_p2' => 'Il suo fulcro è la pianura alluvionale di Mkata, una prateria aperta spesso paragonata a un Serengeti in miniatura — orizzonti ampi, osservazione della fauna facile, e nessuna delle logistiche di volo di Ruaha o Nyerere.',
    'mikumi_intro_p3' => 'Funziona bene come safari del weekend da Dar es Salaam, come tappa sulla strada verso Ruaha o Nyerere, o come introduzione economica alla fauna selvatica tanzaniana.',
    'mikumi_fact_area' => 'Superficie',
    'mikumi_fact_established' => 'Istituito nel',
    'mikumi_fact_status' => 'Accesso',
