    'mikumi_regions_badge' => 'Il paesaggio',
    'mikumi_regions_title' => 'Cosa vedere',
    'mikumi_regions_intro' => 'Mikumi è incentrato su due habitat contrastanti.',
    'mikumi_region_mkata_name' => 'Pianura Alluvionale di Mkata',
    'mikumi_region_mkata_desc' => 'Il cuore del parco — prateria aperta fiancheggiata dalle montagne Uluguru e Lumango, con le più alte concentrazioni di fauna selvatica e l\'osservazione più facile del parco.',
    'mikumi_region_miombo_name' => 'Foresta di miombo',
    'mikumi_region_miombo_desc' => 'Foresta di miombo sulle colline circonda la pianura alluvionale, casa di specie meno comunemente viste come l\'eland e l\'antilope sable per i visitatori che esplorano oltre la pianura.',

    'mikumi_wildlife_badge' => 'Chi vive qui',
    'mikumi_wildlife_title' => 'Fauna selvatica',
    'mikumi_wildlife_intro' => 'Mikumi ospita un vero spaccato della fauna dell\'Africa orientale, concentrata sulla pianura aperta di Mkata.',
    'mikumi_animal_lion' => 'Leone',
    'mikumi_animal_elephant' => 'Elefante',
    'mikumi_animal_leopard' => 'Leopardo',
    'mikumi_animal_wilddog' => 'Licaone africano',
    'mikumi_animal_buffalo' => 'Bufalo',
    'mikumi_animal_giraffe' => 'Giraffa',
    'mikumi_animal_zebra' => 'Zebra',
    'mikumi_animal_wildebeest' => 'Gnu',
    'mikumi_animal_hippo' => 'Ippopotamo',
    'mikumi_wildlife_p1' => 'La pianura alluvionale ospita grandi mandrie di bufali, zebre e gnu tutto l\'anno, con elefanti comunemente visti lungo i corsi d\'acqua stagionali che attraversano la prateria.',
    'mikumi_wildlife_p2' => 'Leoni e leopardi sono entrambi presenti e regolarmente avvistati, e Mikumi è uno dei pochi parchi dove il licaone africano passa occasionalmente — mai garantito, ma una possibilità reale.',

    'mikumi_when_badge' => 'Pianificazione',
    'mikumi_when_title' => 'Quando andare',
    'mikumi_when_intro' => 'Mikumi è una destinazione visitabile tutto l\'anno data la sua bassa altitudine e il facile accesso stradale.',
    'mikumi_when_p1' => 'Da giugno a ottobre (stagione secca) offre la migliore osservazione della fauna, poiché gli animali si concentrano intorno alle fonti d\'acqua rimaste sulla pianura.',
    'mikumi_when_p2' => 'Da novembre a maggio è più verde e tranquillo, con tariffe più basse nella maggior parte dei campi — una buona opzione per una visita più breve ed economica se l\'osservazione della fauna in alta stagione non è la priorità.',

    'mikumi_stay_badge' => 'Dove alloggiare',
    'mikumi_stay_title' => 'Alloggio',
    'mikumi_stay_intro' => 'Il facile accesso di Mikumi da Dar es Salaam ha attirato una buona distribuzione di alloggi in ogni fascia di budget.',
    'mikumi_stay_budget_title' => 'Campi economici',
    'mikumi_stay_budget_price' => 'Campeggio / tenda base',
    'mikumi_stay_budget_desc' => 'Semplici campeggi e opzioni tendate di base vicino all\'ingresso del parco, il modo più economico per basarsi per una visita in stile escursione giornaliera.',
    'mikumi_stay_mid_title' => 'Lodge fascia media',
    'mikumi_stay_mid_price' => 'Lodge, con bagno privato',
    'mikumi_stay_mid_desc' => 'Confortevoli lodge affacciati sulla pianura alluvionale, che offrono un buon equilibrio tra comfort e rapporto qualità-prezzo per un soggiorno di una o due notti.',
    'mikumi_stay_luxury_title' => 'Lodge di lusso',
    'mikumi_stay_luxury_price' => 'Lodge premium',
    'mikumi_stay_luxury_desc' => 'Un numero minore di strutture di fascia alta offre verande private e viste rialzate sulla pianura, per viaggiatori che desiderano comfort extra vicino a Dar.',
    'mikumi_stay_note' => 'Possiamo organizzare l\'alloggio a qualsiasi livello come parte del tuo itinerario a Mikumi, incluso il trasporto da Dar es Salaam.',

    'mikumi_access_badge' => 'Come arrivare',
    'mikumi_access_title' => 'Accesso da Dar es Salaam',
    'mikumi_access_intro' => 'Il più grande vantaggio di Mikumi rispetto a Ruaha e Nyerere è che non richiede alcun volo interno.',
    'mikumi_access_p1' => 'Una strada asfaltata collega Dar es Salaam a Mikumi in circa quattro ore, rendendolo realistico come gita del weekend o come tappa in un itinerario più lungo sul circuito del sud verso Ruaha.',
    'mikumi_access_p2' => 'Questo accesso stradale è il motivo principale per cui Mikumi è il safari vero più economico della Tanzania — nessun costo di volo charter da considerare nel tuo viaggio.',

    'mikumi_fees_badge' => 'Tasse 2026',
    'mikumi_fees_title' => 'Tasse di ingresso al parco',
    'mikumi_fees_intro' => 'Le tasse sono per persona per periodo di 24 ore e includono il 18% di IVA — tra le più basse di qualsiasi parco nazionale tanzaniano. Pagabili con carta o tessera parco prepagata — il contante non è accettato all\'ingresso.',
