    'mikumi_faq_badge' => 'FAQ',
    'mikumi_faq_title' => 'Domande comuni',
    'mikumi_faq_q1' => 'Devo volare per andare a Mikumi?',
    'mikumi_faq_a1' => 'No — Mikumi si raggiunge con quattro ore di viaggio su strada asfaltata da Dar es Salaam, ed è esattamente questo che lo rende l\'opzione safari più economica in Tanzania.',
    'mikumi_faq_q2' => 'Mikumi va bene per un weekend?',
    'mikumi_faq_a2' => 'Sì — il breve viaggio da Dar es Salaam lo rende realistico come safari di due giorni nel weekend, cosa che nessuno degli altri parchi del sud o del nord può facilmente offrire.',
    'mikumi_faq_q3' => 'Vedrò i Big Five?',
    'mikumi_faq_a3' => 'Leone, elefante e bufalo si vedono regolarmente. Il leopardo è presente ma elusivo, e il rinoceronte non si trova a Mikumi — per una possibilità realistica di vedere i Big Five, Ngorongoro rimane la scelta migliore.',
    'mikumi_faq_q4' => 'Come si confronta Mikumi con Ruaha o Nyerere?',
    'mikumi_faq_a4' => 'Mikumi è più piccolo e più facile da raggiungere, con tasse più basse, ma Ruaha e Nyerere offrono una maggiore densità di fauna selvatica e una sensazione più remota — Mikumi è la scelta economica e conveniente dei tre.',
    'mikumi_faq_q5' => 'Posso combinare Mikumi con Ruaha?',
    'mikumi_faq_a5' => 'Sì — Mikumi si trova sul percorso stradale verso Ruaha, rendendolo una tappa naturale in un itinerario più lungo sul circuito del sud.',
    'mikumi_faq_q6' => 'Qual è il periodo migliore per visitarlo?',
    'mikumi_faq_a6' => 'Da giugno a ottobre per la migliore osservazione della fauna, anche se il parco è accessibile e vale la pena tutto l\'anno data la sua bassa altitudine e il facile accesso stradale.',
    'mikumi_faq_q7' => 'Mikumi è adatto per un primo safari?',
    'mikumi_faq_a7' => 'Sì — la sua accessibilità e il costo più basso lo rendono un\'introduzione sensata alla fauna tanzaniana, specialmente per i viaggiatori basati o in arrivo via Dar es Salaam.',
    'mikumi_faq_q8' => 'È necessario un veicolo 4x4?',
    'mikumi_faq_a8' => 'Sì, come per qualsiasi parco nazionale tanzaniano — forniamo un 4x4 privato con autista-guida come standard in ogni itinerario a Mikumi.',

    'mikumi_cta_title' => 'Pronto a visitare Mikumi?',
    'mikumi_cta_intro' => 'Inviaci le tue date e la dimensione del gruppo. Ti rispondiamo con un itinerario scritto e il prezzo completo — senza impegno.',
