    'ngorongoro_meta_title' => 'Cratere di Ngorongoro: la Guida Completa (2026) | Serengeti Budget Safari',
    'ngorongoro_meta_description' => 'Tutto sul Cratere di Ngorongoro: probabilità di vedere il rinoceronte nero, la tassa di discesa 2026 di $295, quando andare, dove alloggiare e i Maasai che vi abitano.',
    'ngorongoro_hero_badge' => 'Guida del parco',
    'ngorongoro_hero_title' => 'Cratere di Ngorongoro',
    'ngorongoro_hero_sub' => 'La più grande caldera intatta sulla terra, 25.000 animali dentro una conca di 260 km², e la migliore possibilità di vedere il rinoceronte nero in Tanzania — tutto in un solo giorno.',
    'ngorongoro_hero_cta_quote' => 'Richiedi un preventivo',
    'ngorongoro_intro_badge' => 'Introduzione',
    'ngorongoro_intro_title' => 'Cos\'è il Cratere di Ngorongoro?',
    'ngorongoro_intro_p1' => 'Il Cratere di Ngorongoro è la più grande caldera vulcanica intatta sulla terra: una conca larga 19 km, profonda 610 m e di 260 km² di superficie, con pareti che si innalzano quasi verticalmente dal fondo. Circa 25.000 grandi animali vi vivono permanentemente, conferendogli la più alta densità di grande fauna di tutta l\'Africa.',
    'ngorongoro_intro_p2' => 'Il cratere si trova all\'interno della ben più vasta Area di Conservazione di Ngorongoro, 8.292 km² di altopiani, foresta e pianure che contiene anche la Gola di Olduvai, i crateri di Empakaai e Olmoti, e le pianure di Ndutu dove la Grande Migrazione partorisce. È un Patrimonio Mondiale dell\'UNESCO ed è insolita in Africa perché è un\'area a uso multiplo: circa 100.000 Maasai vivono qui con il loro bestiame accanto alla fauna selvatica.',
    'ngorongoro_intro_p3' => 'Per la maggior parte dei visitatori un fatto risolve tutto — questo è il posto più affidabile in Tanzania per vedere il rinoceronte nero, e quindi il posto dove completare i Big Five in un solo giorno è genuinamente possibile.',
    'ngorongoro_fact_crater_area' => 'Fondo del cratere',
    'ngorongoro_fact_nca_area' => 'Area di Conservazione',
    'ngorongoro_fact_status' => 'Stato',
    'ngorongoro_fact_rhino' => 'Rinoceronte nero',
    'ngorongoro_fact_animals' => 'Animali nel cratere',
    'ngorongoro_fact_stay' => 'Soggiorno consigliato',
    'ngorongoro_fact_day' => 'giorno',
    'ngorongoro_fact_from_arusha' => 'Da Arusha',
    'ngorongoro_fact_descent_limit' => 'Limite di discesa nel cratere',
    'ngorongoro_areas_badge' => 'Capire l\'area',
    'ngorongoro_areas_title' => 'Il cratere vs. la più ampia Area di Conservazione',
    'ngorongoro_areas_intro' => 'Spesso si dice "Ngorongoro" per intendere due cose diverse. Ecco la distinzione, e perché è importante per il tuo itinerario.',
    'ngorongoro_area_floor_name' => 'Il fondo del cratere',
    'ngorongoro_area_floor_desc' => 'La caldera di 260 km² stessa — una conca autonoma dove la maggior parte degli animali vive tutto l\'anno perché le pareti li trattengono. Questo è ciò che quasi tutti intendono quando dicono "Cratere di Ngorongoro", ed è dove passi la tua giornata di game drive.',
    'ngorongoro_area_wider_name' => 'L\'Area di Conservazione',
    'ngorongoro_area_wider_desc' => 'L\'intera regione di 8.292 km² che circonda il cratere — altopiani, foresta, le pianure di Ndutu e altri due crateri, Empakaai e Olmoti. È un\'area a uso multiplo classificata UNESCO dove circa 100.000 Maasai vivono accanto alla fauna selvatica, a differenza di un parco nazionale dove le persone sono escluse.',
    'ngorongoro_area_olduvai_name' => 'Gola di Olduvai',
    'ngorongoro_area_olduvai_desc' => 'A mezz\'ora dal cratere, sulla strada per il Serengeti, la Gola di Olduvai taglia 90 m attraverso due milioni di anni di sedimenti vulcanici. Louis e Mary Leakey vi lavorarono a partire dagli anni \'30 e trovarono resti di ominidi che ridefinirono ciò che si sapeva sulle origini umane, incluso il Paranthropus boisei nel 1959. C\'è un piccolo museo, e si inserisce facilmente nel tragitto tra Ngorongoro e il Serengeti.',
    'ngorongoro_maasai_badge' => 'Persone',
    'ngorongoro_maasai_title' => 'I Maasai che vivono qui',
    'ngorongoro_maasai_intro' => 'Ngorongoro non è un parco nazionale, e la distinzione è deliberata.',
    'ngorongoro_maasai_p1' => 'Quando il Serengeti fu istituito nel 1959, i Maasai che vi abitavano furono trasferiti altrove; Ngorongoro fu creata come area di conservazione a uso multiplo dove persone, bestiame e fauna selvatica condividono la terra. Circa 100.000 Maasai vivono oggi nell\'Area di Conservazione con circa un milione di capi di bestiame, pascolando sul fondo del cratere di giorno e tornando sul bordo di notte.',
    'ngorongoro_maasai_p2' => 'Visitare un boma Maasai è possibile e viene organizzato tramite l\'autorità di conservazione. La qualità varia — alcune visite sono molto artificiose. Lavoriamo con comunità con cui abbiamo relazioni di lunga data, dove il compenso arriva al villaggio e puoi genuinamente fare domande.',
    'ngorongoro_wildlife_badge' => 'Fauna selvatica',
    'ngorongoro_wildlife_title' => 'Fauna selvatica: cosa vedrai davvero',
    'ngorongoro_wildlife_intro' => 'Probabilità di avvistamento per un\'intera giornata sul fondo del cratere — insolitamente alte, perché gli animali non possono disperdersi.',
    'ngorongoro_animal_lion' => 'Leone — circa 95% di probabilità',
    'ngorongoro_animal_rhino' => 'Rinoceronte nero — circa 60% di probabilità',
    'ngorongoro_animal_buffalo' => 'Bufalo — quasi certo',
    'ngorongoro_animal_zebra' => 'Zebra — quasi certo',
    'ngorongoro_animal_elephant' => 'Elefante — maschi della Foresta di Lerai',
    'ngorongoro_animal_hippo' => 'Ippopotamo — Palude di Gorigor',
    'ngorongoro_animal_hyena' => 'Iena macchiata',
    'ngorongoro_animal_flamingo' => 'Fenicottero — Lago Magadi',
    'ngorongoro_animal_leopard' => 'Leopardo — raro, solo nella foresta del bordo',
    'ngorongoro_wildlife_p1' => 'Leone, bufalo, elefante e rinoceronte nero sono tutti realistici in una singola giornata nel cratere — una vera possibilità di vedere i Big Five in 24 ore, cosa insolita in qualsiasi parte dell\'Africa. Solo il leopardo è una vera scommessa: vive nella foresta del bordo e viene raramente visto dal fondo. Non ci sono giraffe — le strade di discesa sono troppo ripide per loro.',
    'ngorongoro_wildlife_p2' => 'I leoni del cratere sono tra i più studiati al mondo e illustrano il costo dell\'isolamento: la popolazione è effettivamente chiusa, la diversità genetica è bassa, e un\'epidemia nel 1962 li ridusse a una manciata di animali. Oggi il numero è di circa 60, e sono altamente abituati ai veicoli. Circa 30 rinoceronti neri vivono nel cratere sotto protezione dei ranger 24 ore su 24 — solitamente visti a distanza attraverso l\'erba aperta, quindi porta un binocolo.',
    'ngorongoro_when_badge' => 'Periodo migliore',
    'ngorongoro_when_title' => 'Quando visitare',
    'ngorongoro_when_intro' => 'Il cratere funziona in ogni mese — gli animali non migrano fuori, quindi a differenza del Serengeti non c\'è una stagione sbagliata per l\'osservazione della fauna.',
    'ngorongoro_when_p1' => 'Da giugno a ottobre è il periodo più secco, più freddo all\'alba e più affollato — aspettati altri veicoli a ogni avvistamento. Da marzo a maggio arrivano le piogge lunghe: strade di discesa scivolose e nebbia che può restare sul bordo fino a metà mattina, ma anche il cratere più verde e le tariffe più economiche.',
    'ngorongoro_when_p2' => 'Più importante del mese è essere sul fondo alle 06:30. I predatori sono attivi nelle prime due ore, la luce è morbida, e sei in anticipo rispetto ai veicoli che scendono alle nove. Questa singola decisione cambia la qualità della giornata più di quanto faccia la stagione.',
    'ngorongoro_stay_badge' => 'Alloggio',
    'ngorongoro_stay_title' => 'Dove alloggiare',
    'ngorongoro_stay_intro' => 'Tre scelte principali, e la decisione riguarda soprattutto quanto presto puoi essere al cancello di discesa.',
    'ngorongoro_stay_budget_title' => 'Economico',
    'ngorongoro_stay_budget_price' => 'da $35,40/notte tassa di campeggio',
    'ngorongoro_stay_budget_desc' => 'Campeggio pubblico Simba, proprio sul bordo: la tua tenda, servizi condivisi essenziali, e a volte bufali o zebre che vagano nel campo di notte. Freddo a 2.400 m — un vero sacco a pelo non è opzionale.',
    'ngorongoro_stay_mid_title' => 'Karatu',
    'ngorongoro_stay_mid_price' => '$60–200/notte',
    'ngorongoro_stay_mid_desc' => 'Una vera cittadina a 30–45 minuti dal cancello: rapporto qualità-prezzo molto migliore, più caldo, più scelta di ristoranti. Il compromesso è una partenza anticipata, verso le 05:30, per essere primi sulla strada di discesa.',
    'ngorongoro_stay_luxury_title' => 'Lodge sul bordo del cratere',
    'ngorongoro_stay_luxury_price' => '$250–800+/notte',
    'ngorongoro_stay_luxury_desc' => 'La vista diretta nel cratere dalla tua camera, e dieci minuti dalla strada di discesa così puoi essere primo sul fondo. Costoso, freddo di notte, e spesso prenotato con mesi di anticipo.',
    'ngorongoro_stay_note' => 'Se visiti per un solo giorno e il costo non è il fattore decisivo, resta sul bordo — essere primi sul fondo vale molto. Se hai diversi giorni nell\'area, Karatu è la base sensata e i soldi risparmiati possono pagare una notte extra nel Serengeti.',
    'ngorongoro_fees_badge' => 'Costi',
    'ngorongoro_fees_title' => 'Tasse del parco (2026)',
    'ngorongoro_fees_intro' => 'Ngorongoro è amministrata dalla NCAA, non dalla TANAPA, e ha una tassa che coglie di sorpresa: una tassa separata semplicemente per scendere nel cratere, addebitata per veicolo anziché per persona.',
    'ngorongoro_table_category' => 'Categoria',
    'ngorongoro_table_adult' => 'Adulto (16+)',
    'ngorongoro_table_child' => 'Bambino (5–15)',
    'ngorongoro_fee_entry' => 'Ingresso Area di Conservazione, per 24 ore',
    'ngorongoro_fee_descent' => 'Tassa di servizio cratere (discesa, per veicolo)',
    'ngorongoro_fee_descent_value' => '$295,00 per veicolo',
    'ngorongoro_fee_concession' => 'Concessione, pernottamento nella NCA (a notte)',
    'ngorongoro_fee_campsite' => 'Campeggio pubblico (a notte)',
    'ngorongoro_fees_note' => 'Tutte le cifre includono il 18% di IVA. I bambini sotto i 5 anni entrano gratis. La tassa di discesa nel cratere è per veicolo, non per persona, quindi il costo a persona scende notevolmente con la dimensione del gruppo — circa $148 a testa per due persone, meno di $50 a testa per sei. Si applica ogni volta che scendi, quindi un secondo giorno nel cratere significa pagarla due volte. Le tasse possono cambiare senza preavviso; il tuo preventivo scritto indica sempre l\'importo esatto per le tue date.',
    'ngorongoro_gallery_badge' => 'Galleria',
    'ngorongoro_gallery_title' => 'Ngorongoro in immagini',
    'ngorongoro_gallery_caption_1' => 'Il cratere dal bordo',
    'ngorongoro_gallery_caption_2' => 'Rinoceronte nella prateria',
    'ngorongoro_gallery_caption_3' => 'Elefante sotto un\'acacia',
    'ngorongoro_gallery_caption_4' => 'Leone maschio sul fondo del cratere',
    'ngorongoro_gallery_caption_5' => 'Iena macchiata nella pianura',
    'ngorongoro_gallery_caption_6' => 'Famiglia di elefanti al tramonto',
    'ngorongoro_back_to_parks' => 'Confronta tutti i parchi',
    'ngorongoro_faq_badge' => 'FAQ',
    'ngorongoro_faq_title' => 'Cratere di Ngorongoro — domande frequenti',
    'ngorongoro_faq_q1' => 'Quanto costa visitare il Cratere di Ngorongoro?',
    'ngorongoro_faq_a1' => 'Nel 2026, $82,60 per adulto ogni 24 ore per entrare nell\'Area di Conservazione, più una tassa di servizio cratere di $295,00 per veicolo per la discesa. I bambini 5–15 pagano $23,60; sotto i cinque anni gratis. Tutte le cifre includono il 18% di IVA.',
    'ngorongoro_faq_q2' => 'Perché la tassa di discesa nel cratere è così alta?',
    'ngorongoro_faq_a2' => 'Viene addebitata per veicolo anziché per persona e finanzia la conservazione e il programma di protezione dei rinoceronti. Poiché è per veicolo, il costo a persona scende notevolmente con la dimensione del gruppo — circa $148 a testa per due persone, meno di $50 a testa per sei.',
    'ngorongoro_faq_q3' => 'Vedrò il rinoceronte nero nel cratere?',
    'ngorongoro_faq_a3' => 'Circa 30 vivono nel cratere e le probabilità in un\'intera giornata sono circa il 60%, ma solitamente a distanza attraverso l\'erba aperta. Porta un binocolo. Il mattino presto offre le migliori possibilità, prima che si ritirino verso i margini della palude.',
    'ngorongoro_faq_q4' => 'Posso vedere i Big Five in un giorno?',
    'ngorongoro_faq_a4' => 'A Ngorongoro questo è genuinamente possibile, il che è insolito. Leone, bufalo ed elefante sono quasi certi, il rinoceronte è probabile, e solo il leopardo è una vera scommessa — vivono nella foresta del bordo e vengono raramente visti dal fondo.',
    'ngorongoro_faq_q5' => 'Quanto tempo posso restare nel cratere?',
    'ngorongoro_faq_a5' => 'Sei ore dal momento in cui scendi. Il limite viene applicato al cancello di uscita ed esiste per controllare il numero di veicoli su un fondo piccolo.',
    'ngorongoro_faq_q6' => 'Quanto dista Ngorongoro da Arusha, e posso farlo come gita giornaliera?',
    'ngorongoro_faq_a6' => 'Circa 180 km, tre o quattro ore su strada. Sì, una gita giornaliera è possibile — partendo verso le 05:30 e tornando dopo il buio — e rimane uno dei nostri safari di un giorno più richiesti, poiché si trova direttamente sul percorso verso il Serengeti.',
    'ngorongoro_faq_q7' => 'Qual è la differenza tra il cratere e l\'Area di Conservazione?',
    'ngorongoro_faq_a7' => 'Il cratere è il fondo della caldera di 260 km². L\'Area di Conservazione è la regione di 8.292 km² che lo circonda, che include anche la Gola di Olduvai, i crateri di Empakaai e Olmoti, le pianure di Ndutu e circa 100.000 residenti Maasai.',
    'ngorongoro_faq_q8' => 'Dovrei alloggiare sul bordo o a Karatu?',
    'ngorongoro_faq_a8' => 'I lodge sul bordo costano $250–800 e ti permettono di essere primo sul fondo. Karatu costa $60–200 e aggiunge un tragitto pre-alba di 30–45 minuti. Per una singola giornata nel cratere il bordo ne vale la pena; per soggiorni più lunghi Karatu offre un rapporto qualità-prezzo migliore.',
    'ngorongoro_cta_title' => 'Pronto a pianificare il tuo safari a Ngorongoro?',
    'ngorongoro_cta_intro' => 'Inviaci le tue date, la dimensione del gruppo e il budget. Ti rispondiamo con un itinerario scritto e un preventivo dettagliato — senza impegno.',
    'ngorongoro_cta_whatsapp' => 'Scrivici su WhatsApp',
    'ngorongoro_cta_safaris' => 'Vedi gli itinerari safari',

    'nyerere_meta_title' => 'Parco Nazionale di Nyerere (Selous): la Guida Completa (2026) | Serengeti Budget Safari',
    'nyerere_meta_description' => 'Parco Nazionale di Nyerere, ex Selous: il parco più grande d\'Africa, safari in barca sul fiume Rufiji, safari a piedi e licaoni africani. Tasse 2026, quando andare e come arrivare da Dar.',
    'nyerere_hero_badge' => 'Guida del parco',
    'nyerere_hero_title' => 'Parco Nazionale di Nyerere',
    'nyerere_hero_sub' => 'Ex Selous — il parco nazionale più grande d\'Africa, dove puoi fare un safari in barca, un safari a piedi e un game drive nello stesso giorno.',
    'nyerere_hero_cta_quote' => 'Richiedi un preventivo',
    'nyerere_intro_badge' => 'Introduzione',
    'nyerere_intro_title' => 'Cos\'è il Parco Nazionale di Nyerere?',
    'nyerere_intro_p1' => 'Il Parco Nazionale di Nyerere è stato creato nel 2019 dalla sezione settentrionale dell\'antica Riserva di Caccia di Selous, e con oltre 30.893 km² è il più grande parco nazionale d\'Africa — più grande del Belgio, e circa il doppio del Serengeti. Si trova nella Tanzania sud-orientale, raggiungibile da Dar es Salaam piuttosto che da Arusha, il che lo rende la porta naturale del circuito safari del sud.',
    'nyerere_intro_p2' => 'La maggior parte dei viaggiatori lo conosce ancora come Selous. La restante porzione meridionale mantiene quel nome come riserva di caccia; l\'area che si visita come turisti è ora Nyerere, dal nome del primo presidente della Tanzania.',
    'nyerere_intro_p3' => 'Ciò che lo distingue è l\'acqua. Il fiume Rufiji lo attraversa, espandendosi in una rete di laghi, canali e banchi di sabbia, e questo cambia cosa significhi un safari qui: puoi fare un safari in barca, un safari a piedi e un game drive nello stesso giorno — una combinazione semplicemente impossibile nel Serengeti.',
    'nyerere_fact_area' => 'Superficie',
    'nyerere_fact_rank' => 'Classifica',
    'nyerere_fact_rank_value' => 'Il parco più grande d\'Africa',
    'nyerere_fact_established' => 'Istituito nel',
    'nyerere_fact_status' => 'Stato',
    'nyerere_fact_boat' => 'Safari in barca',
    'nyerere_fact_boat_value' => 'Sì — Fiume Rufiji',
    'nyerere_fact_wilddog' => 'Licaone',
    'nyerere_fact_wilddog_value' => 'Roccaforte principale',
    'nyerere_fact_stay' => 'Soggiorno consigliato',
    'nyerere_fact_nights' => 'notti',
    'nyerere_fact_from_dar' => 'Da Dar es Salaam',
    'nyerere_fact_minutes' => 'min in aereo',
    'nyerere_regions_badge' => 'Dove andare',
    'nyerere_regions_title' => 'Le aree di Nyerere',
    'nyerere_regions_intro' => 'Il parco è vasto, e quasi tutto il turismo è concentrato in una piccola sezione settentrionale intorno al fiume e ai laghi. Queste sono le aree principali, e cosa offre ciascuna.',
    'nyerere_region_rufiji_name' => 'Il fiume Rufiji e il sistema dei laghi',
    'nyerere_region_rufiji_desc' => 'Il fiume più grande dell\'Africa orientale per volume rallenta, si espande e si divide in una rete di canali, laghi a ferro di cavallo e banchi di sabbia attraversando il parco. Cinque laghi principali — Tagalala, Manze, Nzerakera, Siwandu e Mzizimia — si trovano qui, nella sezione dove si basano la maggior parte dei campi, ognuno con i propri gruppi di ippopotami e uccelli residenti. È qui che avvengono i safari in barca, e non c\'è nulla di simile nel circuito del nord.',
    'nyerere_region_stieglers_name' => 'La Gola di Stiegler e la zona turistica settentrionale',
    'nyerere_region_stieglers_desc' => 'L\'area principale per i visitatori, facilmente raggiungibile dalle piste di atterraggio vicine ai campi del Rufiji. La Gola di Stiegler, profonda 100 m e larga 100 m, taglia il nord del parco. Questa zona combina game drive, safari a piedi e gite in barca a breve distanza da ogni lodge, ed è per questo che quasi tutti i visitatori alloggiano qui.',
    'nyerere_region_south_name' => 'La natura selvaggia del sud',
    'nyerere_region_south_desc' => 'La grande maggioranza dei 30.893 km² di Nyerere si trova a sud della zona turistica, ed è genuinamente remota — poche strade, pochi campi, e raramente visitata anche per gli standard tanzaniani. Non fa parte di un itinerario tipico, ma sottolinea ciò che rende questo parco diverso dal circuito del nord: spazio, e un\'assenza quasi totale di altri veicoli.',
    'nyerere_activities_badge' => 'Cosa lo rende diverso',
    'nyerere_activities_title' => 'Safari in barca, safari a piedi e altro',
    'nyerere_activities_intro' => 'Ecco perché vieni a Nyerere invece di aggiungere un altro parco del nord.',
    'nyerere_table_activity' => 'Attività',
    'nyerere_table_duration' => 'Durata',
    'nyerere_table_highlight' => 'Cosa ti offre',
    'nyerere_act_boat_name' => 'Safari in barca sul Rufiji',
    'nyerere_act_boat_desc' => 'Scivolando sul fiume e sui suoi laghi a livello degli occhi con gruppi di ippopotami e coccodrilli sui banchi di sabbia, osservando gli elefanti scendere a bere e le aquile pescatrici lavorare i canali. Il miglior safari in barca della Tanzania.',
    'nyerere_act_walking_name' => 'Safari a piedi',
    'nyerere_act_walking_desc' => 'Con un ranger armato, generalmente alle prime luci. Nyerere è stato uno dei primi posti in Tanzania a offrire safari a piedi e rimane uno dei migliori — tracci a piedi e incontri gli animali a livello del terreno.',
    'nyerere_act_flycamp_name' => 'Fly-camping',
    'nyerere_act_flycamp_unit' => 'notte',
    'nyerere_act_flycamp_desc' => 'Una notte sotto tela lontano dal campo principale, con una guida e un ranger. Semplice, e spesso la notte più memorabile di tutto il viaggio.',
    'nyerere_act_drive_name' => 'Game drive',
    'nyerere_act_drive_desc' => 'Classico safari in veicolo attraverso la foresta di miombo e la prateria aperta, solitamente combinato con una gita in barca o una camminata nello stesso giorno.',
    'nyerere_activities_note' => 'I safari in barca, i safari a piedi e il fly-camping sono addebitati separatamente dai campi — dicci in anticipo cosa vuoi, poiché sono la ragione principale per cui si viene qui.',
    'nyerere_wildlife_badge' => 'Fauna selvatica',
    'nyerere_wildlife_title' => 'Fauna selvatica: cosa vedrai davvero',
    'nyerere_wildlife_intro' => 'Su una visita di tre giorni che combina game drive e safari in barca nella stagione secca, basato sui registri di avvistamento delle nostre guide.',
    'nyerere_animal_hippo' => 'Ippopotamo — enormi gruppi sul Rufiji',
    'nyerere_animal_crocodile' => 'Coccodrillo',
    'nyerere_animal_elephant' => 'Elefante',
    'nyerere_animal_lion' => 'Leone',
    'nyerere_animal_buffalo' => 'Bufalo',
    'nyerere_animal_wilddog' => 'Licaone africano — roccaforte globale',
    'nyerere_animal_leopard' => 'Leopardo',
    'nyerere_animal_zebra' => 'Zebra',
    'nyerere_animal_rhino' => 'Rinoceronte nero — quasi nessuno rimasto',
    'nyerere_wildlife_p1' => 'Ippopotamo e coccodrillo sono quasi una certezza sul fiume, ed elefante, leone e bufalo sono tutti realistici in un soggiorno di tre giorni. Nyerere ospita una delle più grandi popolazioni rimaste di licaone africano nel continente — circa il 35% di probabilità di avvistamento in una visita di tre giorni, il che è eccezionale per una specie con meno di 7.000 individui rimasti allo stato selvatico.',
    'nyerere_wildlife_p2' => 'Il rinoceronte nero è effettivamente assente: un numero minuscolo sopravvive nell\'ecosistema più ampio, ma per scopi pratici non dovresti pianificare un viaggio qui aspettandoti di vederne uno. Per i rinoceronti in Tanzania, il Cratere di Ngorongoro è l\'opzione realistica. A differenza del Serengeti, Nyerere non ha migrazione — ha invece grandi popolazioni residenti presenti tutto l\'anno.',
    'nyerere_when_badge' => 'Periodo migliore',
    'nyerere_when_title' => 'Quando visitare',
    'nyerere_when_intro' => 'Nyerere chiude effettivamente durante le piogge lunghe, una vera differenza rispetto ai parchi del nord, che operano tutto l\'anno.',
    'nyerere_when_p1' => 'Da giugno a ottobre è il periodo migliore: la stagione secca concentra la fauna lungo il Rufiji, i safari in barca sono al loro meglio e le temperature sono confortevoli. Novembre e dicembre portano le piogge brevi — paesaggi verdi, buon birdwatching e meno visitatori, ancora molto praticabile.',
    'nyerere_when_p2' => 'Gennaio e febbraio sono caldi e umidi ma ancora buoni per la fauna ed eccellenti per gli uccelli. Da marzo a maggio, le piogge lunghe, è quando la maggior parte dei campi chiude e le strade si allagano — non raccomandiamo di viaggiare in quel periodo.',
    'nyerere_stay_badge' => 'Alloggio',
    'nyerere_stay_title' => 'Dove alloggiare',
    'nyerere_stay_intro' => 'Verifica attentamente cosa è incluso. Nella fascia di lusso, safari in barca, safari a piedi e tasse del parco sono spesso inclusi; nella fascia media di solito no, e aggiungerli cambia considerevolmente il prezzo reale. Dettagliamo tutto per iscritto.',
    'nyerere_stay_budget_title' => 'Economico',
    'nyerere_stay_budget_price' => 'da $35,40/notte tassa parco + campeggio',
    'nyerere_stay_budget_desc' => 'Campeggio pubblico o semplici bande vicino al cancello di Mtemere, spesso usato da viaggi su strada da Dar. Servizi essenziali; serve la tua attrezzatura o la nostra.',
    'nyerere_stay_mid_title' => 'Fascia media',
    'nyerere_stay_mid_price' => '$200–400/notte',
    'nyerere_stay_mid_desc' => 'Confortevole tented camp vicino ai laghi. Attività come safari in barca e camminate sono solitamente addebitate separatamente dalla tariffa della camera.',
    'nyerere_stay_luxury_title' => 'Lusso',
    'nyerere_stay_luxury_price' => '$450–1.000+/notte',
    'nyerere_stay_luxury_desc' => 'Piccoli campi sul Lago Manze o Siwandu, completamente inclusivi con safari in barca e a piedi integrati. Ippopotami che chiamano fuori dalla tenda di notte.',
    'nyerere_stay_note' => 'Dove basarsi: la sezione settentrionale dei laghi intorno a Manze e Siwandu è dove avvengono i safari in barca e la maggior parte dell\'osservazione della fauna. I campi più a sud sono più economici ma passi più tempo della giornata guidando verso l\'acqua.',
    'nyerere_fees_badge' => 'Costi',
    'nyerere_fees_title' => 'Tasse del parco (2026)',
    'nyerere_fees_intro' => 'Le tasse sono stabilite dalla TANAPA, l\'Autorità dei Parchi Nazionali della Tanzania, e sono identiche per ogni operatore.',
    'nyerere_table_category' => 'Categoria',
    'nyerere_table_adult' => 'Adulto (16+)',
    'nyerere_table_child' => 'Bambino (5–15)',
    'nyerere_fee_entry' => 'Ingresso, per 24 ore',
    'nyerere_fee_concession' => 'Concessione, pernottamento nel parco (a notte)',
    'nyerere_fee_campsite' => 'Campeggio pubblico (a notte)',
    'nyerere_fees_note' => 'Tutte le cifre includono il 18% di IVA. I bambini sotto i 5 anni entrano gratis. I safari in barca, i safari a piedi e il fly-camping sono addebitati separatamente dai campi. Le tasse vengono riviste dal governo e possono cambiare senza preavviso — il nostro preventivo scritto indica sempre l\'importo esatto per le tue date.',
    'nyerere_gallery_badge' => 'Galleria',
    'nyerere_gallery_title' => 'Nyerere in immagini',
    'nyerere_gallery_caption_1' => 'Osservando gli ippopotami dalla barca',
    'nyerere_gallery_caption_2' => 'Rinoceronte al pascolo al crepuscolo',
    'nyerere_gallery_caption_3' => 'Famiglia di elefanti al tramonto',
    'nyerere_gallery_caption_4' => 'Leone che riposa vicino all\'acqua',
    'nyerere_gallery_caption_5' => 'Iena macchiata nella savana',
    'nyerere_gallery_caption_6' => 'Elefante sotto un\'acacia',
    'nyerere_back_to_parks' => 'Confronta tutti i parchi',
    'nyerere_faq_badge' => 'FAQ',
    'nyerere_faq_title' => 'Parco Nazionale di Nyerere — domande frequenti',
    'nyerere_faq_q1' => 'Nyerere è lo stesso di Selous?',
    'nyerere_faq_a1' => 'Il Parco Nazionale di Nyerere è stato creato nel 2019 dalla sezione settentrionale della Riserva di Caccia di Selous. La restante porzione meridionale si chiama ancora Selous. L\'area che i turisti visitano è ora Nyerere, anche se molti operatori usano ancora il vecchio nome.',
    'nyerere_faq_q2' => 'Quanto costa entrare a Nyerere?',
    'nyerere_faq_a2' => 'La tassa 2026 per non residenti è $59,00 per adulto e $17,70 per bambino di 5–15 anni, ogni 24 ore, IVA del 18% inclusa. I safari in barca, i safari a piedi e il fly-camping sono addebitati separatamente dai campi.',
    'nyerere_faq_q3' => 'Come arrivo a Nyerere?',
    'nyerere_faq_a3' => 'Circa 45 minuti in aereo leggero da Dar es Salaam, con voli giornalieri programmati, o cinque-sei ore su strada. Nyerere si raggiunge da Dar, non da Arusha, il che cambia la logistica di un viaggio rispetto ai parchi del nord.',
    'nyerere_faq_q4' => 'Posso fare un safari in barca a Nyerere?',
    'nyerere_faq_a4' => 'Sì, ed è la ragione principale per venire. Due o tre ore sul fiume Rufiji e i suoi laghi ti portano al livello di gruppi di ippopotami e coccodrilli, con elefanti che scendono a bere. È il miglior safari in barca della Tanzania.',
    'nyerere_faq_q5' => 'Posso camminare a Nyerere?',
    'nyerere_faq_a5' => 'Sì, con un ranger armato, solitamente alle prime luci per due o tre ore. Nyerere è stato tra i primi posti in Tanzania a offrire safari a piedi e rimane uno dei migliori per questo.',
    'nyerere_faq_q6' => 'Vedrò i licaoni?',
    'nyerere_faq_a6' => 'Circa il 35% di probabilità in una visita di tre giorni — eccezionale per una specie con meno di 7.000 individui rimasti allo stato selvatico. Nyerere ospita una delle più grandi popolazioni rimaste in Africa.',
    'nyerere_faq_q7' => 'Quanti giorni mi servono a Nyerere?',
    'nyerere_faq_a7' => 'Tre o quattro giorni. Questo ti dà un safari in barca, un safari a piedi e diversi game drive senza fretta — che è tutto il senso di venire qui invece di aggiungere un altro parco del nord.',
    'nyerere_faq_q8' => 'Ci sono rinoceronti a Nyerere?',
    'nyerere_faq_a8' => 'Un numero molto piccolo di rinoceronti neri sopravvive nell\'ecosistema più ampio, ma dovresti supporre di non vederne uno. Per i rinoceronti in Tanzania, il Cratere di Ngorongoro è l\'opzione realistica.',
    'nyerere_cta_title' => 'Pronto a pianificare il tuo safari a Nyerere?',
    'nyerere_cta_intro' => 'Inviaci le tue date, la dimensione del gruppo e il budget. Ti rispondiamo con un itinerario scritto e un preventivo dettagliato — senza impegno.',
    'nyerere_cta_whatsapp' => 'Scrivici su WhatsApp',
    'nyerere_cta_safaris' => 'Vedi gli itinerari safari',

