    'pkg5d_faq_title' => 'Domande frequenti',
    'pkg5d_faq_q1' => 'Questo safari è privato?',
    'pkg5d_faq_a1' => 'Sì, il veicolo e la guida sono privati per il tuo gruppo a meno che tu non prenoti specificamente una partenza di gruppo. Decidi tu il ritmo e le soste.',
    'pkg5d_faq_q2' => 'Posso personalizzare il safari?',
    'pkg5d_faq_a2' => 'Sì — è possibile aggiungere giorni extra, parchi diversi o un\'estensione a Zanzibar. Dicci cosa hai in mente e adatteremo itinerario e prezzo.',
    'pkg5d_faq_q3' => 'Posso partire in qualsiasi data?',
    'pkg5d_faq_a3' => 'Sì, i safari privati partono nella data che preferisci, salvo disponibilità dei lodge in alta stagione (giugno-ottobre).',
    'pkg5d_faq_q4' => 'Il pickup dall\'aeroporto è incluso?',
    'pkg5d_faq_a4' => 'Sì, il pickup dall\'Aeroporto Internazionale del Kilimanjaro o dal tuo hotel ad Arusha è incluso nel prezzo.',
    'pkg5d_faq_q5' => 'Cosa dovrei portare?',
    'pkg5d_faq_a5' => 'Abbigliamento dai colori neutri, uno strato caldo per le mattine presto, protezione solare, un cappello, binocolo e macchina fotografica. Inviamo una lista completa una volta confermato il viaggio.',
    'pkg5d_faq_q6' => 'Questo safari è adatto ai bambini?',
    'pkg5d_faq_a6' => 'Sì — la maggior parte dei lodge su questo percorso accoglie bambini di tutte le età, anche se alcuni hanno un\'età minima per i game drive. Comunicaci le età dei partecipanti e confermeremo.',

