    'safari_meta_title' => 'Safari in Tanzania | Serengeti, Ngorongoro & Tarangire | Serengeti Budget Safari',
    'safari_meta_description' => 'Pacchetti safari in Tanzania da €200 a persona al giorno: Serengeti, Cratere di Ngorongoro, Tarangire e Lago Manyara. Safari economici, familiari, di lusso, luna di miele e fly-in gestiti da un operatore locale ad Arusha.',
