    'safari_park_serengeti_desc' => 'La Grande Migrazione, la più alta densità di predatori in Africa e 14.763 km² di pianure.',
    'safari_park_ngorongoro_desc' => '25.000 animali in una caldera di 260 km², e l\'unica reale possibilità di vedere il rinoceronte nero in Tanzania.',
    'safari_park_tarangire_desc' => 'Baobab, 3.000 elefanti e 550 specie di uccelli — due ore da Arusha e raramente affollato.',
    'safari_park_manyara_desc' => 'Foresta, fenicotteri, babbuini, e l\'unico night drive del circuito del nord.',
    'safari_park_nyerere_desc' => 'Il parco più grande d\'Africa. Safari in barca sul Rufiji, safari a piedi e licaoni.',
    'safari_park_ruaha_desc' => 'Il parco più grande della Tanzania, ~10% dei leoni del mondo, e quasi nessun altro veicolo.',
    'safari_park_mikumi_desc' => 'Quattro ore da Dar es Salaam via terra, nessun volo necessario — il safari vero più economico della Tanzania.',

    'safari_included_title' => 'Cosa include un safari con noi',
    'safari_included_subtitle' => 'Salvo diversa indicazione nel preventivo, ogni prezzo in questa pagina copre quanto segue.',
    'safari_included_heading' => 'Incluso',
    'safari_included_1' => 'Land Cruiser 4x4 con tetto apribile e posto finestrino garantito per tutti',
    'safari_included_2' => 'Autista-guida in inglese (italiano su richiesta)',
    'safari_included_3' => 'Tutte le tasse di ingresso ai parchi e di conservazione incluse nell\'itinerario',
    'safari_included_4' => 'Alloggio e pasti come descritto nel programma',
    'safari_included_5' => 'Acqua potabile durante i game drive',
    'safari_included_6' => 'Trasferimento da/per Arusha o l\'aeroporto del Kilimanjaro',
    'safari_excluded_heading' => 'Non incluso',
    'safari_excluded_1' => 'Voli internazionali e visto per la Tanzania',
    'safari_excluded_2' => 'Assicurazione di viaggio (obbligatoria)',
    'safari_excluded_3' => 'Bevande diverse dall\'acqua e spese personali',
    'safari_excluded_4' => 'Mance per guida e staff del lodge',
    'safari_excluded_5' => 'Extra opzionali: volo in mongolfiera, visite culturali, voli interni',

    'safari_parks_title' => 'Leggi prima dei parchi',
    'safari_parks_subtitle' => 'Prima di scegliere un itinerario, è utile sapere cosa offre davvero ogni parco. Queste guide sono scritte dalle nostre guide e coprono fauna, tariffe 2026, quando andare e dove alloggiare.',
    'safari_parks_beyond_title' => 'Oltre il circuito del nord',
    'safari_parks_beyond_desc' => 'Altri tre parchi si raggiungono da Dar es Salaam invece che da Arusha — più grandi, più vuoti e più economici da visitare, con safari in barca e a piedi che i parchi del nord non offrono.',
    'safari_parks_full_guide' => 'Guida completa',
    'safari_parks_compare_all' => 'Confronta tutti e nove i parchi',

    'safari_faq_title' => 'Domande comuni',
    'safari_faq_q1' => 'Quanto costa realmente un safari in Tanzania?',
    'safari_faq_a1' => 'Economico da circa €200 a persona al giorno, fascia media €250–350, e lusso da €600. Le variabili maggiori sono il livello dell\'alloggio e la dimensione del gruppo: le tasse del parco e il veicolo sono costi fissi, quindi in quattro condividendo si paga notevolmente meno a testa rispetto a in due.',
    'safari_faq_q2' => 'Qual è il periodo migliore per venire?',
    'safari_faq_a2' => 'Da giugno a ottobre è la classica stagione secca con l\'avvistamento più facile. Gennaio e febbraio portano la stagione dei parti a Ndutu. Da novembre a maggio è più verde, più tranquillo ed economico, con qualche pioggia pomeridiana.',
    'safari_faq_q3' => 'Vedremo i Big Five?',
    'safari_faq_a3' => 'Leone, elefante, bufalo e leopardo si vedono regolarmente in un safari di quattro giorni sul circuito del nord. Il rinoceronte nero è il più difficile: il Cratere di Ngorongoro è la miglior possibilità in Tanzania, ma nessun operatore può garantire l\'avvistamento di un animale selvatico.',
    'safari_faq_q4' => 'Quanti giorni servono?',
    'safari_faq_a4' => 'Tre giorni è il minimo pratico per raggiungere il Serengeti senza passare tutto il viaggio in auto. Quattro o cinque giorni è la scelta ideale. Per periodi più brevi conviene concentrarsi su Tarangire, Manyara e il Cratere di Ngorongoro, molto più vicini ad Arusha.',

    'safari_cta_title' => 'Pianifica il tuo viaggio con noi',
    'safari_cta_intro' => 'Inviaci le tue date, la dimensione del gruppo e il budget. Ti rispondiamo con un itinerario scritto e un preventivo dettagliato — senza impegno.',
    'safari_cta_whatsapp' => 'Scrivici su WhatsApp',
    'safari_cta_contact_form' => 'Modulo di contatto',

