    'parks_meta_title' => 'Parchi Nazionali della Tanzania: Tutti i 9 Parchi a Confronto (2026) | Serengeti Budget Safari',
    'parks_meta_description' => 'Confronta i parchi nazionali della Tanzania fianco a fianco: Serengeti, Ngorongoro, Tarangire, Manyara, Arusha, Kilimanjaro, Nyerere, Ruaha e Mikumi. Tariffe 2026, fauna e giorni necessari.',

    'parks_hero_badge' => 'Guide ai parchi',
    'parks_hero_title' => 'I parchi nazionali della Tanzania',
    'parks_hero_sub' => 'Nove parchi a confronto — fauna, tariffe 2026, giorni necessari e quale si adatta al tuo viaggio. Poi leggi la guida completa di quelli che ti interessano.',

    'parks_northern_badge' => 'Parchi del nord',
    'parks_northern_title' => 'Il circuito del nord',
    'parks_northern_intro' => 'Cinque parchi a un giorno di viaggio da Arusha, meta della grande maggioranza dei safari tanzaniani.',

    'parks_southern_badge' => 'Parchi del sud',
    'parks_southern_title' => 'Il circuito del sud',
    'parks_southern_intro' => 'Raggiunti da Dar es Salaam anziché da Arusha. Più grandi, più vuoti, più economici da entrare e più costosi da raggiungere — dove si va in un secondo viaggio.',

    'parks_full_guide' => 'Guida completa',

    'parks_serengeti_name' => 'Serengeti',
    'parks_serengeti_desc' => '14.763 km² di pianure, la Grande Migrazione e la più alta densità di grandi predatori in Africa. Servono almeno tre giorni.',
    'parks_ngorongoro_name' => 'Ngorongoro',
    'parks_ngorongoro_desc' => 'La più grande caldera intatta della terra con 25.000 animali al suo interno, e l\'unica possibilità realistica di vedere il rinoceronte nero in Tanzania.',
    'parks_tarangire_name' => 'Tarangire',
    'parks_tarangire_desc' => 'Baobab e 2.500–3.000 elefanti, a due ore da Arusha, il più tranquillo dei quattro parchi principali.',
    'parks_manyara_name' => 'Lago Manyara',
    'parks_manyara_desc' => 'Foresta di falda, fenicotteri, grandi gruppi di babbuini, e l\'unico game drive notturno e passerella sospesa del circuito.',
    'parks_arusha_name' => 'Parco Nazionale di Arusha',
    'parks_arusha_desc' => 'A quaranta minuti dalla città, l\'unico posto del circuito dove si può camminare, fare canoa e scalare. Niente leoni.',
    'parks_kilimanjaro_name' => 'Kilimanjaro',
    'parks_kilimanjaro_desc' => 'La montagna più alta d\'Africa a 5.895 m, scalata in cinque-nove giorni su sette percorsi ufficiali.',
    'parks_nyerere_name' => 'Nyerere (Selous)',
    'parks_nyerere_desc' => 'Il più grande parco nazionale d\'Africa, dove puoi fare un safari in barca, un safari a piedi e un game drive nello stesso giorno.',
    'parks_ruaha_name' => 'Ruaha',
    'parks_ruaha_desc' => 'Il parco più grande della Tanzania, con circa il 10% dei leoni del mondo e 12.000 elefanti, con quasi nessun altro veicolo.',
    'parks_mikumi_name' => 'Mikumi',
    'parks_mikumi_desc' => 'L\'unico grande parco raggiungibile da una città su strada in mattinata. Pianure aperte, leoni residenti, il safari più economico della Tanzania.',

