    'parks_want_migration' => 'La Grande Migrazione',
    'parks_why_migration' => 'L\'unico posto dove avviene. Scegli la zona in base al mese.',
    'parks_want_bigfive' => 'I Big Five in un giorno',
    'parks_why_bigfive' => 'Unico parco dove il rinoceronte è realisticamente probabile.',
    'parks_want_elephants' => 'Elefanti',
    'parks_why_elephants' => 'Mandrie di cinquanta o più esemplari nella stagione secca.',
    'parks_want_walking' => 'Camminare, non guidare',
    'parks_why_walking' => 'Tutti e tre permettono veri safari a piedi.',
    'parks_want_oneday' => 'Solo un giorno',
    'parks_why_oneday' => 'Entrambi raggiungibili e gratificanti in un giorno da Arusha.',
    'parks_want_budget' => 'Nessun volo, budget ridotto',
    'parks_why_budget' => 'Quattro ore da Dar su strada, la tariffa d\'ingresso più bassa.',

    'parks_see_safaris' => 'Guarda i nostri itinerari safari',

    'parks_faq_badge' => 'FAQ',
    'parks_faq_title' => 'Parchi nazionali della Tanzania — domande frequenti',
    'parks_faq_q1' => 'Qual è il miglior parco nazionale della Tanzania?',
    'parks_faq_a1' => 'Dipende da cosa cerchi. Il Serengeti per la migrazione e i predatori, Ngorongoro per la densità e il rinoceronte, Tarangire per gli elefanti, Ruaha per i leoni e la solitudine, Nyerere per i safari in barca. I migliori itinerari ne combinano due o tre invece di sceglierne uno solo.',
    'parks_faq_q2' => 'Quanto costano le tariffe dei parchi tanzaniani nel 2026?',
    'parks_faq_a2' => 'Serengeti, Ngorongoro e Kilimanjaro sono $82,60 a adulto al giorno; Tarangire, Lago Manyara, Arusha NP e Nyerere sono $59,00; Ruaha e Mikumi sono $35,40. Tutte includono il 18% di IVA. Ngorongoro aggiunge $295 a veicolo per scendere nel cratere.',
    'parks_faq_q3' => 'Qual è la differenza tra il circuito del nord e del sud?',
    'parks_faq_a3' => 'Il circuito del nord parte da Arusha e include Serengeti, Ngorongoro, Tarangire, Manyara, Arusha NP e Kilimanjaro. Il circuito del sud parte da Dar es Salaam e copre Nyerere, Ruaha e Mikumi — più grandi, più vuoti, più economici da entrare e più costosi da raggiungere.',
    'parks_faq_q4' => 'Quali parchi posso visitare in un giorno da Arusha?',
    'parks_faq_a4' => 'Il Parco Nazionale di Arusha a 40 minuti, Tarangire e Lago Manyara a due ore, e Ngorongoro a tre-quattro ore. Il Serengeti è a 7–8 ore e non è realistico come gita di un giorno.',
    'parks_faq_q5' => 'Qual è il parco più economico?',
    'parks_faq_a5' => 'Ruaha e Mikumi a $35,40 per adulto. Ma l\'ingresso è solo parte del costo: Mikumi non richiede volo ed è davvero il safari più economico della Tanzania, mentre Ruaha richiede un volo di due ore da Dar.',
    'parks_faq_q6' => 'Qual è il miglior parco per i Big Five?',
    'parks_faq_a6' => 'Ngorongoro, perché è l\'unico dove il rinoceronte nero è realisticamente raggiungibile. Il Serengeti offre facilmente quattro dei cinque ma quasi nessun rinoceronte. Combinare i due è la soluzione standard.',
    'parks_faq_q7' => 'Qual è il periodo migliore per visitare i parchi tanzaniani?',
    'parks_faq_a7' => 'Da giugno a ottobre è la stagione secca ed è la più facile ovunque. Gennaio e febbraio sono adatti alla stagione dei parti del Serengeti. Da marzo a maggio è la stagione delle piogge: i parchi del nord restano aperti, ma molti campi a Ruaha e Nyerere chiudono completamente.',
    'parks_faq_q8' => 'Quanti giorni servono per un safari in Tanzania?',
    'parks_faq_a8' => 'Due giorni coprono bene Tarangire e Ngorongoro. Quattro o cinque aggiungono adeguatamente il Serengeti. Sei-otto permettono di seguire la migrazione o fare il circuito del sud.',
    'parks_faq_q9' => 'Posso pagare le tariffe dei parchi in contanti?',
    'parks_faq_a9' => 'No. I cancelli di TANAPA e NCAA non accettano contanti — le tariffe si pagano con carta o tessere prepagate. Quando viaggi con noi, questo è gestito per te e incluso nel prezzo quotato.',
    'parks_faq_q10' => 'Devo visitare tutti i parchi?',
    'parks_faq_a10' => 'No, e in un viaggio breve non dovresti provarci. Due parchi fatti bene battono quattro fatti di fretta. Un errore comune è stipare il Serengeti in un viaggio di quattro giorni e passarne la maggior parte in auto.',

    'parks_cta_title' => 'Non sai quali parchi scegliere?',
    'parks_cta_intro' => 'Dicci quanti giorni hai e cosa vuoi vedere di più. Ti diremo onestamente quali parchi valgono la pena per le tue date — anche quando la risposta è "salta quello".',
    'parks_cta_whatsapp' => 'Scrivici su WhatsApp',
    'parks_cta_contact_form' => 'Modulo di contatto',

    // ---------- Pagina Parco Nazionale del Serengeti ----------
    'serengeti_meta_title' => 'Parco Nazionale del Serengeti: La Guida Completa (2026) | Serengeti Budget Safari',
    'serengeti_meta_description' => 'Tutto sul Parco Nazionale del Serengeti: la Grande Migrazione mese per mese, le cinque regioni, la fauna, le tariffe 2026, dove alloggiare e quando andare.',

    'serengeti_hero_badge' => 'Guida al parco',
    'serengeti_hero_title' => 'Parco Nazionale del Serengeti',
    'serengeti_hero_sub' => 'La guida completa al parco più famoso della Tanzania — la Grande Migrazione mese per mese, dove alloggiare, quanto costa e quando venire.',
    'serengeti_hero_cta_quote' => 'Richiedi un preventivo',

    'serengeti_intro_badge' => 'Introduzione',
    'serengeti_intro_title' => 'Cos\'è il Serengeti?',
    'serengeti_intro_p1' => 'Il Parco Nazionale del Serengeti copre 14.763 km² della Tanzania settentrionale — all\'incirca la dimensione dell\'Irlanda del Nord — ed è il parco nazionale più antico del paese, istituito nel 1951. Il suo nome deriva dalla parola maasai siringet, "il luogo dove la terra corre all\'infinito".',
    'serengeti_intro_p2' => 'È famoso soprattutto per una cosa: la Grande Migrazione, il movimento continuo di circa 1,3 milioni di gnu, 250.000 zebre e centinaia di migliaia di gazzelle che seguono le piogge in un percorso circolare tra le pianure meridionali e il Masai Mara in Kenya. È il più grande movimento terrestre di animali rimasto sulla terra, e avviene continuamente — non c\'è mese in cui si ferma.',
    'serengeti_intro_p3' => 'Il Serengeti ospita anche una delle popolazioni di leoni più dense d\'Africa (circa 3.000 esemplari) e più di 500 specie di uccelli registrate. Insieme all\'Area di Conservazione di Ngorongoro forma un unico ecosistema di circa 30.000 km², ed è Patrimonio dell\'Umanità UNESCO dal 1981.',

    'serengeti_fact_area' => 'Superficie',
    'serengeti_fact_established' => 'Istituito',
    'serengeti_fact_status' => 'Status',
    'serengeti_fact_lions' => 'Leoni',
    'serengeti_fact_wildebeest' => 'Gnu',
    'serengeti_fact_stay' => 'Soggiorno consigliato',
    'serengeti_fact_nights' => 'notti',
    'serengeti_fact_from_arusha' => 'Da Arusha',
    'serengeti_fact_by_air' => 'In aereo',

    'serengeti_regions_badge' => 'Dove andare',
    'serengeti_regions_title' => 'Le cinque regioni del Serengeti',
    'serengeti_regions_intro' => 'Il parco è più grande di alcuni paesi, e dove alloggi determina cosa vedi. Queste sono le zone principali, e quando ognuna è al suo meglio.',
    'serengeti_region_seronera_name' => 'Seronera (Serengeti Centrale)',
    'serengeti_region_seronera_desc' => 'Il cuore del parco e la scelta più sicura per una prima visita. La valle del fiume ha acqua tutto l\'anno, quindi la fauna residente non se ne va mai: leoni, leopardi, elefanti, bufali e ghepardi sono qui ogni mese. Ottimo tutto l\'anno, ideale per soggiorni di 2–3 notti per chi visita per la prima volta.',
    'serengeti_region_ndutu_name' => 'Ndutu e le pianure meridionali',
    'serengeti_region_ndutu_desc' => 'Da dicembre a marzo le mandrie della migrazione si concentrano qui per partorire, e la densità di predatori che le segue è straordinaria — il momento e il luogo migliori in Tanzania per assistere a una caccia. Fuori da questi mesi le pianure si svuotano quasi completamente.',
    'serengeti_region_western_name' => 'Corridoio Occidentale e il fiume Grumeti',
    'serengeti_region_western_desc' => 'Un lungo braccio del parco che si estende verso il Lago Vittoria. Le mandrie passano di qui tra maggio e luglio, e qui avvengono gli attraversamenti del Grumeti — più piccoli di quelli del Mara, ma con alcuni dei coccodrilli più grandi d\'Africa in agguato nelle pozze.',
    'serengeti_region_kogatende_name' => 'Kogatende e il Serengeti Settentrionale',
    'serengeti_region_kogatende_desc' => 'Colline ondulate e boscaglia fitta lungo il fiume Mara, al confine con il Kenya. Da luglio a ottobre è qui che avvengono gli attraversamenti del fiume. Fuori dalla stagione degli attraversamenti è una delle zone più tranquille e belle del parco.',

    'serengeti_migration_badge' => 'Grande Migrazione',
    'serengeti_migration_title' => 'La Grande Migrazione, mese per mese',
    'serengeti_migration_intro' => 'La migrazione non è un evento con una data. È un circuito continuo guidato dalle piogge, e le mandrie si trovano da qualche parte nell\'ecosistema in ogni mese dell\'anno.',
    'serengeti_table_months' => 'Mesi',
    'serengeti_table_where' => 'Dove si trovano le mandrie',
    'serengeti_table_what_happens' => 'Cosa succede',
    'serengeti_mig_ndutu' => 'Ndutu e pianure meridionali',
    'serengeti_mig_calving' => 'Stagione dei parti. Circa 400.000 cuccioli nati, con l\'attività dei predatori al suo massimo dell\'anno.',
    'serengeti_mig_moving_nw' => 'Spostamento a nord-ovest',
    'serengeti_mig_rains' => 'Grandi piogge. Le colonne si formano e si spostano attraverso il Serengeti centrale verso il Corridoio Occidentale.',
    'serengeti_mig_western' => 'Corridoio Occidentale',
    'serengeti_mig_grumeti' => 'Attraversamenti del fiume Grumeti. Più piccoli di quelli del Mara ma con coccodrilli enormi e una frazione dei veicoli.',
    'serengeti_mig_northern' => 'Serengeti Settentrionale e Masai Mara',
    'serengeti_mig_mara' => 'Attraversamenti del fiume Mara — l\'immagine classica. Agosto e settembre sono i mesi di picco.',
    'serengeti_mig_returning' => 'Ritorno a sud',
    'serengeti_mig_south' => 'Le piccole piogge riportano le mandrie verso sud attraverso il Serengeti orientale verso le zone di parto.',
    'serengeti_migration_note' => 'La pioggia sposta questo schema di due o tre settimane in entrambe le direzioni — nessun operatore può promettere un attraversamento in una data fissa.',

    'serengeti_wildlife_badge' => 'Fauna',
    'serengeti_wildlife_title' => 'Fauna: cosa vedrai davvero',
    'serengeti_wildlife_intro' => 'Su un safari di tre giorni nel Serengeti centrale, basato sui dati di avvistamento delle nostre guide.',
    'serengeti_animal_lion' => 'Leone — densità più alta d\'Africa',
    'serengeti_animal_leopard' => 'Leopardo — valle di Seronera',
    'serengeti_animal_elephant' => 'Elefante',
    'serengeti_animal_buffalo' => 'Bufalo',
    'serengeti_animal_cheetah' => 'Ghepardo — pianure meridionali',
    'serengeti_animal_zebra' => 'Zebra',
    'serengeti_animal_giraffe' => 'Giraffa',
    'serengeti_animal_hyena' => 'Iena maculata',
    'serengeti_animal_rhino' => 'Rinoceronte nero — molto raro, solo Moru Kopjes',
    'serengeti_wildlife_p1' => 'Leone, leopardo, elefante e bufalo sono tutti realistici in un safari di tre giorni nel Serengeti. Il rinoceronte nero no: una piccola popolazione protetta sopravvive intorno ai Moru Kopjes, ma gli avvistamenti sono rari e di solito distanti. Se vedere il rinoceronte ti interessa, aggiungi il Cratere di Ngorongoro al tuo itinerario.',
    'serengeti_wildlife_p2' => 'La popolazione di leoni del Serengeti, circa 3.000, è la più grande d\'Africa, organizzata in branchi che mantengono il territorio per generazioni. I ghepardi preferiscono le pianure meridionali aperte dove possono correre; i leopardi preferiscono le acacie lungo i fiumi. Le iene maculate sono molto più numerose di quanto la maggior parte dei visitatori si aspetti e sono cacciatrici abili a pieno titolo.',

    'serengeti_when_badge' => 'Periodo migliore',
    'serengeti_when_title' => 'Quando visitare',
    'serengeti_when_intro' => 'Non c\'è stagione di chiusura. Ciò che cambia è cosa vedi, quanti altri veicoli ci sono all\'avvistamento, e quanto paghi.',
    'serengeti_when_p1' => 'Primo safari, vuoi che sia facile: da giugno a ottobre. Vegetazione rada, animali concentrati vicino all\'acqua, meteo affidabile. Vuoi il massimo dramma naturale: fine gennaio-febbraio a Ndutu.',
    'serengeti_when_p2' => 'Vuoi rapporto qualità-prezzo e spazio: marzo, aprile, maggio o novembre. Avrai pioggia, ma avrai anche il parco quasi tutto per te a una frazione del prezzo.',

    'serengeti_stay_badge' => 'Alloggio',
    'serengeti_stay_title' => 'Dove alloggiare',
    'serengeti_stay_intro' => 'L\'alloggio è la variabile singola più grande nel costo di un safari nel Serengeti. Le distanze sono così grandi che dove dormi determina quanta parte della giornata passi a guidare invece che a osservare.',
    'serengeti_stay_budget_title' => 'Economico',
    'serengeti_stay_budget_price' => 'da $35,40/notte tariffa parco + campeggio',
    'serengeti_stay_budget_desc' => 'Campeggio pubblico: tenda propria, bagni alla turca condivisi e docce fredde, il cuoco prepara i pasti sul posto. All\'interno del parco, per gli avventurosi.',
    'serengeti_stay_mid_title' => 'Fascia media',
    'serengeti_stay_mid_price' => '$150–400/notte',
    'serengeti_stay_mid_desc' => 'Lodge o tented camp all\'interno del parco: edificio permanente o tenda in tela con letti veri e bagno privato. Ti svegli nel cuore dell\'ecosistema.',
    'serengeti_stay_luxury_title' => 'Lusso',
    'serengeti_stay_luxury_price' => '$300–700+/notte',
    'serengeti_stay_luxury_desc' => 'Campi mobili che si spostano per seguire la migrazione, o tented camp di fascia alta. Piccoli, remoti, pochi veicoli nelle vicinanze.',
    'serengeti_stay_note' => 'Dormire all\'interno del parco costa di più — una tariffa di concessione di $59,00 per adulto a notte oltre alla tariffa della camera — ma sei già nel mezzo dell\'azione all\'alba e al tramonto, quando i predatori sono più attivi.',

    'serengeti_fees_badge' => 'Costi',
    'serengeti_fees_title' => 'Tariffe del parco (2026)',
    'serengeti_fees_intro' => 'Le tariffe sono fissate da TANAPA, l\'ente dei parchi nazionali della Tanzania, e sono identiche per ogni operatore.',
    'serengeti_table_category' => 'Categoria',
    'serengeti_table_adult' => 'Adulto (16+)',
    'serengeti_table_child' => 'Bambino (5–15)',
    'serengeti_fee_entry' => 'Ingresso, per 24 ore',
    'serengeti_fee_concession' => 'Concessione, pernottamento nel parco (a notte)',
    'serengeti_fee_campsite' => 'Campeggio pubblico (a notte)',
    'serengeti_fees_note' => 'Tutte le cifre includono il 18% di IVA. I bambini sotto i 5 anni entrano gratis. Le tariffe sono riviste dal governo e possono cambiare senza preavviso — il tuo preventivo scritto da noi indica sempre l\'importo esatto per le tue date.',

    'serengeti_gallery_badge' => 'Galleria',
    'serengeti_gallery_title' => 'Il Serengeti in immagini',
    'serengeti_gallery_caption_1' => 'Branco di leoni con una preda',
    'serengeti_gallery_caption_2' => 'Leopardo riposa su un albero',
    'serengeti_gallery_caption_3' => 'Mandria di zebre nella pianura',
    'serengeti_gallery_caption_4' => 'Ghepardi all\'ombra',
    'serengeti_gallery_caption_5' => 'Leoni in agguato su una zebra',
    'serengeti_gallery_caption_6' => 'Leopardo, veduta ampia',

    'serengeti_back_to_parks' => 'Confronta tutti i parchi',

    'serengeti_faq_badge' => 'FAQ',
    'serengeti_faq_title' => 'Parco Nazionale del Serengeti — domande frequenti',
    'serengeti_faq_q1' => 'Quanto costa entrare nel Serengeti?',
    'serengeti_faq_a1' => 'La tariffa d\'ingresso 2026 per i non residenti è $82,60 per adulto e $23,60 per bambino tra 5 e 15 anni, per 24 ore, IVA del 18% inclusa. I bambini sotto i 5 anni entrano gratis. Se dormi all\'interno del parco c\'è anche una tariffa di concessione di $59,00 per adulto a notte, o $35,40 per un campeggio pubblico.',
    'serengeti_faq_q2' => 'Quanti giorni servono nel Serengeti?',
    'serengeti_faq_a2' => 'Tre giorni è il minimo realistico, e quattro-cinque è la soluzione ideale. Con meno di tre giorni il lungo viaggio da Arusha consuma gran parte del tuo viaggio — vedresti più fauna visitando Tarangire, Lago Manyara e il Cratere di Ngorongoro invece.',
    'serengeti_faq_q3' => 'Qual è il periodo migliore per visitare il Serengeti?',
    'serengeti_faq_a3' => 'Da giugno a ottobre per l\'osservazione più facile e gli attraversamenti del fiume Mara. Fine gennaio e febbraio per la stagione dei parti a Ndutu, che è probabilmente lo spettacolo naturale migliore. Da marzo a maggio è piovoso, vuoto ed economico.',
    'serengeti_faq_q4' => 'Vedrò sicuramente un attraversamento del fiume?',
    'serengeti_faq_a4' => 'No, e diffida di chi te lo promette. Gli attraversamenti sono imprevedibili: le mandrie possono aspettare sulla riva per un giorno intero e poi allontanarsi. Tre notti a Kogatende tra luglio e ottobre ti danno una buona possibilità, non una garanzia.',
    'serengeti_faq_q5' => 'Posso vedere i Big Five nel Serengeti?',
    'serengeti_faq_a5' => 'Quattro in modo affidabile — leone, leopardo, elefante e bufalo. Il rinoceronte nero sopravvive solo in piccoli numeri intorno ai Moru Kopjes ed è raramente visto. Per il rinoceronte, aggiungi il Cratere di Ngorongoro al tuo itinerario.',
    'serengeti_faq_q6' => 'Come si arriva da Arusha al Serengeti?',
    'serengeti_faq_a6' => 'Su strada sono circa 325 km e 7–8 ore fino a Seronera, di solito con una sosta a Ngorongoro o Karatu. In aereo leggero sono circa 1 ora e 15 minuti. Molti itinerari vanno in un modo e tornano nell\'altro.',
    'serengeti_faq_q7' => 'Posso fare un safari nel Serengeti con un budget limitato?',
    'serengeti_faq_a7' => 'Sì — i safari in campeggio partono da circa €200 a persona al giorno. Hai la stessa guida, lo stesso veicolo e gli stessi animali; risparmi su dove dormi. Viaggiare in un gruppo di quattro invece di due riduce notevolmente il costo a persona.',
    'serengeti_faq_q8' => 'Il Serengeti è meglio del Masai Mara?',
    'serengeti_faq_a8' => 'Sono lo stesso ecosistema diviso da un confine. Il Serengeti è circa quindici volte più grande, ha habitat più vari e molto più spazio tra i veicoli; il Mara è più compatto, quindi gli avvistamenti arrivano più rapidamente ma con più affollamento.',

    'serengeti_cta_title' => 'Pronto a pianificare il tuo safari nel Serengeti?',
    'serengeti_cta_intro' => 'Inviaci le tue date, la dimensione del gruppo e il budget. Ti rispondiamo con un itinerario scritto e un preventivo dettagliato — senza impegno.',
    'serengeti_cta_whatsapp' => 'Scrivici su WhatsApp',
    'serengeti_cta_safaris' => 'Guarda gli itinerari safari',

    'tarangire_meta_title' => 'Parco Nazionale del Tarangire: La Guida Completa (2026) | Serengeti Budget Safari',
    'tarangire_meta_description' => 'Tutto sul Parco Nazionale del Tarangire: elefanti, baobab millenari, 550 specie di uccelli, tariffe 2026, dove alloggiare e quando andare.',

    'tarangire_hero_badge' => 'Guida al parco',
    'tarangire_hero_title' => 'Parco Nazionale del Tarangire',
    'tarangire_hero_sub' => 'Baobab millenari, i più grandi branchi di elefanti della Tanzania settentrionale e più specie di uccelli di qualsiasi altro parco del paese — a due ore da Arusha, e molto più tranquillo dei suoi vicini.',
    'tarangire_hero_cta_quote' => 'Richiedi un preventivo',

    'tarangire_intro_badge' => 'Introduzione',
    'tarangire_intro_title' => 'Cos\'è il Tarangire?',
    'tarangire_intro_p1' => 'Il Parco Nazionale del Tarangire copre 2.850 km² di boscaglia di acacie e territorio di baobab, a due ore a sud di Arusha. È il sesto parco più grande della Tanzania e, per motivi difficili da giustificare, il più costantemente trascurato del circuito settentrionale.',
    'tarangire_intro_p2' => 'Prende il nome dal fiume Tarangire, che attraversa il parco per tutta la sua lunghezza ed è l\'unica fonte d\'acqua permanente per chilometri in ogni direzione. Nella stagione secca questo unico fatto trasforma il luogo: animali provenienti da un ecosistema molto più ampio convergono sul fiume, e la concentrazione di fauna tra giugno e ottobre rivaleggia con qualsiasi cosa nel Serengeti.',
    'tarangire_intro_p3' => 'Il Tarangire è famoso soprattutto per due cose — gli elefanti, con una popolazione residente di 2.500-3.000 esemplari e branchi di cinquanta o più capi che qui non fanno notizia, e i baobab, gli enormi alberi dal tronco rigonfio che danno al paesaggio un carattere che non si trova altrove nel circuito. Ospita anche oltre 550 specie di uccelli registrate, il numero più alto di qualsiasi parco tanzaniano.',

    'tarangire_fact_area' => 'Superficie',
    'tarangire_fact_established' => 'Istituito',
    'tarangire_fact_elephants' => 'Elefanti',
    'tarangire_fact_baobabs' => 'Baobab',
    'tarangire_fact_baobabs_value' => 'Migliaia',
    'tarangire_fact_birds' => 'Specie di uccelli',
    'tarangire_fact_stay' => 'Soggiorno consigliato',
    'tarangire_fact_days' => 'giorni',
    'tarangire_fact_from_arusha' => 'Da Arusha',
    'tarangire_fact_river' => 'Fiume Tarangire',
    'tarangire_fact_river_value' => 'Acqua permanente',

    'tarangire_zones_badge' => 'Dove andare',
    'tarangire_zones_title' => 'Le zone del Tarangire',
    'tarangire_zones_intro' => 'Il parco è più piccolo del Serengeti, ma dove vai cambia comunque cosa vedi. Queste sono le zone principali, e per cosa è nota ciascuna.',
    'tarangire_zone_river_name' => 'Il circuito del fiume Tarangire',
    'tarangire_zone_river_desc' => 'Il cuore del parco e la prima visita classica. Il fiume ha acqua tutto l\'anno, e nella stagione secca attira elefanti, bufali, zebre e leoni che scendono a bere e a scavare pozzi nel letto sabbioso. La maggior parte dei lodge e la rete principale dei game drive si trovano lungo questo tratto.',
    'tarangire_zone_silale_name' => 'La palude di Silale',
    'tarangire_zone_silale_desc' => 'Una vasta palude stagionale al centro del parco che trattiene acqua fino alla stagione secca. Attira elefanti, bufali e un numero eccezionale di uccelli e rapaci, e vale la deviazione dal circuito principale del fiume.',
    'tarangire_zone_south_name' => 'Le zone meridionali',
    'tarangire_zone_south_desc' => 'Più aride, più selvagge e raramente visitate dai turisti di un solo giorno. Qui vivono le antilopi delle zone aride — orice fringe-eared, kudu minore e gerenuk — e chi si ferma due giorni viene premiato con l\'osservazione della fauna più tranquilla del parco.',
    'tarangire_zone_north_name' => 'La zona del cancello settentrionale',
    'tarangire_zone_north_desc' => 'Intorno al cancello d\'ingresso di Kwa Kuchinja, la parte del parco più vicina ad Arusha. Colline ondulate punteggiate di baobab e praterie aperte rendono questo tratto il più semplice per una gita di un giorno, con una buona osservazione della fauna vicino al cancello stesso.',

    'tarangire_wildlife_badge' => 'Fauna',
    'tarangire_wildlife_title' => 'Fauna: cosa vedrai davvero',
    'tarangire_wildlife_intro' => 'Probabilità di avvistamento per una giornata intera nella stagione secca (giugno–ottobre), basate sui dati delle nostre guide. Nella stagione delle piogge gli animali si disperdono e ogni valore scende notevolmente.',
    'tarangire_animal_elephant' => 'Elefante — grandi branchi, 99%',
    'tarangire_animal_zebra' => 'Zebra',
    'tarangire_animal_buffalo' => 'Bufalo',
    'tarangire_animal_giraffe' => 'Giraffa',
    'tarangire_animal_wildebeest' => 'Gnu',
    'tarangire_animal_lion' => 'Leone — a volte sugli alberi',
    'tarangire_animal_leopard' => 'Leopardo — circa il 25%',
    'tarangire_animal_hyena' => 'Iena maculata',
    'tarangire_animal_oryx' => 'Orice fringe-eared — zone meridionali',
    'tarangire_wildlife_p1' => 'Elefante, bufalo e leone sono tutti realistici in un safari nel Tarangire, e l\'elefante è quasi una certezza nella stagione secca. Il leopardo è possibile ma non comune, circa il 25%, il ghepardo è pura fortuna, e qui non c\'è alcun rinoceronte — per i Big Five completi, abbina il Tarangire al Cratere di Ngorongoro.',
    'tarangire_wildlife_p2' => 'Ciò che rende il Tarangire degno di essere osservato, e non solo contato, è il comportamento degli elefanti: nei mesi secchi puoi vedere le matriarche scavare pozzi profondi un metro nella sabbia del letto del fiume, mentre zebre, impala e babbuini aspettano a rispettosa distanza per bere una volta che gli elefanti si sono allontanati. Le zone meridionali aride del Tarangire ospitano anche tre antilopi difficili da trovare nel resto del circuito settentrionale — l\'orice fringe-eared, il kudu minore e il gerenuk, che si alza sulle zampe posteriori per brucare.',

    'tarangire_when_badge' => 'Periodo migliore',
    'tarangire_when_title' => 'Quando visitare',
    'tarangire_when_intro' => 'Il Tarangire è il parco più fortemente stagionale del circuito settentrionale. La differenza tra agosto e aprile non è una questione di grado — è un parco diverso.',
    'tarangire_when_p1' => 'Da luglio a ottobre è eccezionale: il fiume è l\'unica acqua per chilometri e tutto converge verso di esso, con i branchi di elefanti al loro massimo. Giugno è molto buono e ancora più tranquillo. Novembre e dicembre portano le piccole piogge — gli animali iniziano a disperdersi, ma è un periodo eccellente per il birdwatching e per i paesaggi verdi e fotogenici.',
    'tarangire_when_p2' => 'Da marzo a maggio, le grandi piogge, è il periodo più debole per la fauna — gli animali si disperdono su un\'area vastissima — ma è il momento migliore per il birdwatching e per avere il parco quasi tutto per te. Se la grande fauna è la tua priorità e puoi visitare solo durante le grandi piogge, considera di passare quella giornata a Ngorongoro, dove gli animali del cratere non si disperdono.',

    'tarangire_stay_badge' => 'Alloggio',
    'tarangire_stay_title' => 'Dove alloggiare',
    'tarangire_stay_intro' => 'Poiché il Tarangire è a sole due ore da Arusha, pernottare è una scelta e non una necessità — ma cambia cosa vedi. La migliore attività degli elefanti è all\'alba e al tramonto, e i visitatori di un solo giorno perdono entrambi i momenti.',
    'tarangire_stay_budget_title' => 'Economico',
    'tarangire_stay_budget_price' => 'da $35,40/notte tariffa parco + campeggio',
    'tarangire_stay_budget_desc' => 'Campeggio pubblico all\'interno del parco: tenda propria, bagni alla turca di base e docce fredde, il cuoco prepara i pasti sul posto. Il modo più economico per dormire dentro il Tarangire.',
    'tarangire_stay_mid_title' => 'Fascia media',
    'tarangire_stay_mid_price' => '$150–400/notte',
    'tarangire_stay_mid_desc' => 'Lodge o tented camp all\'interno del parco, alcuni situati sull\'altopiano con vista sul fiume — puoi osservare gli elefanti dalla terrazza e sei il primo sulle piste al mattino.',
    'tarangire_stay_luxury_title' => 'Fuori dal cancello',
    'tarangire_stay_luxury_price' => '$60–150/notte',
    'tarangire_stay_luxury_desc' => 'Lodge appena fuori dal confine del parco, a soli 15-30 minuti dal cancello — l\'opzione fuori dal parco più competitiva di tutto il circuito, ed è dove consigliamo di risparmiare senza perdere l\'esperienza.',
    'tarangire_stay_note' => 'Dormire all\'interno del parco costa di più — una tariffa di concessione di $47,20 per adulto a notte oltre alla tariffa della camera — ma sei già nel mezzo dell\'azione all\'alba e al tramonto, quando l\'attività degli elefanti è al suo massimo.',

    'tarangire_fees_badge' => 'Costi',
    'tarangire_fees_title' => 'Tariffe del parco (2026)',
    'tarangire_fees_intro' => 'Il Tarangire è un parco "select" secondo la tariffa TANAPA, il che lo rende notevolmente più economico del Serengeti o di Ngorongoro — uno dei motivi per cui offre un ottimo rapporto qualità-prezzo.',
    'tarangire_table_category' => 'Categoria',
    'tarangire_table_adult' => 'Adulto (16+)',
    'tarangire_table_child' => 'Bambino (5–15)',
    'tarangire_fee_entry' => 'Ingresso, per 24 ore',
    'tarangire_fee_concession' => 'Concessione, pernottamento nel parco (a notte)',
    'tarangire_fee_campsite' => 'Campeggio pubblico (a notte)',
    'tarangire_fees_note' => 'Tutte le cifre includono il 18% di IVA. I bambini sotto i 5 anni entrano gratis. Le tariffe sono riviste dal governo e possono cambiare senza preavviso — il tuo preventivo scritto da noi indica sempre l\'importo esatto per le tue date.',

    'tarangire_gallery_badge' => 'Galleria',
    'tarangire_gallery_title' => 'Il Tarangire in immagini',
    'tarangire_gallery_caption_1' => 'Famiglia di elefanti al tramonto',
    'tarangire_gallery_caption_2' => 'Ritratto ravvicinato di un elefante',
    'tarangire_gallery_caption_3' => 'Alba sulla savana tra le acacie',
    'tarangire_gallery_caption_4' => 'Elefante al riparo sotto un\'acacia',
    'tarangire_gallery_caption_5' => 'Mandria di zebre nella pianura',
    'tarangire_gallery_caption_6' => 'Leone che riposa nell\'erba',

    'tarangire_back_to_parks' => 'Confronta tutti i parchi',

    'tarangire_faq_badge' => 'FAQ',
    'tarangire_faq_title' => 'Parco Nazionale del Tarangire — domande frequenti',
    'tarangire_faq_q1' => 'Quanto costa entrare nel Tarangire?',
    'tarangire_faq_a1' => 'La tariffa 2026 per i non residenti è $59,00 per adulto e $17,70 per bambino tra 5 e 15 anni, per 24 ore, IVA del 18% inclusa. I bambini sotto i 5 anni entrano gratis. Se dormi all\'interno del parco si aggiunge una tariffa di concessione di $47,20 per adulto a notte, o $35,40 per un campeggio pubblico.',
    'tarangire_faq_q2' => 'Vale la pena visitare il Tarangire?',
    'tarangire_faq_a2' => 'Nella stagione secca, senza dubbio — le concentrazioni di elefanti lungo il fiume rivaleggiano con qualsiasi cosa in Tanzania, con una frazione dei veicoli e una tariffa d\'ingresso più bassa del Serengeti. Tra marzo e maggio la fauna si disperde ed è il più debole dei parchi settentrionali.',
    'tarangire_faq_q3' => 'Qual è il periodo migliore per visitare il Tarangire?',
    'tarangire_faq_a3' => 'Da luglio a ottobre. Il fiume Tarangire è l\'unica acqua permanente per un lungo tratto in ogni direzione, quindi nei mesi secchi l\'intero ecosistema converge su di esso. Giugno è molto buono e ancora più tranquillo.',
    'tarangire_faq_q4' => 'Quanti elefanti ci sono nel Tarangire?',
    'tarangire_faq_a4' => 'Tra 2.500 e 3.000 esemplari residenti. Branchi di cinquanta o più capi sono la norma nella stagione secca, e vedere diverse centinaia di elefanti in un solo giorno è normale.',
    'tarangire_faq_q5' => 'Posso visitare il Tarangire in giornata?',
    'tarangire_faq_a5' => 'Sì, ed è uno dei nostri safari di un giorno più richiesti. Si parte da Arusha verso le 06:00, si trascorre la giornata nel parco e si torna in serata. Pernottare è meglio, perché la migliore attività degli elefanti è all\'alba e al tramonto.',
    'tarangire_faq_q6' => 'Posso vedere i Big Five nel Tarangire?',
    'tarangire_faq_a6' => 'Tre di loro: elefante, bufalo e leone. Il leopardo è possibile ma non comune, circa il 25%. Non ci sono rinoceronti. Per i Big Five completi, abbina il Tarangire al Cratere di Ngorongoro.',
    'tarangire_faq_q7' => 'Come si arriva da Arusha al Tarangire?',
    'tarangire_faq_a7' => 'Circa 118 km, circa due ore su asfalto in buone condizioni con un breve tratto sterrato fino al cancello principale di Kwa Kuchinja. È il più vicino tra i grandi parchi del circuito settentrionale, il che lo rende una gita di un giorno intero pratica o una comoda prima notte di un safari più lungo.',
    'tarangire_faq_q8' => 'Perché ci sono così tanti baobab qui?',
    'tarangire_faq_a8' => 'Il suolo e le precipitazioni sono adatti a loro, e il parco li protegge da oltre cinquant\'anni. Alcuni hanno più di mille anni. Le profonde cicatrici verticali sui tronchi sono segni di zanne lasciati dagli elefanti che strappano la fibra per la sua umidità.',

    'tarangire_cta_title' => 'Pronto a pianificare il tuo safari nel Tarangire?',
    'tarangire_cta_intro' => 'Inviaci le tue date, la dimensione del gruppo e il budget. Ti rispondiamo con un itinerario scritto e un preventivo dettagliato — senza impegno.',
    'tarangire_cta_whatsapp' => 'Scrivici su WhatsApp',
    'tarangire_cta_safaris' => 'Guarda gli itinerari safari',

    // ===== Day Trips listing =====
    'daytrips_meta_title' => 'Escursioni di un Giorno da Arusha | Tarangire, Ngorongoro e Altro | Serengeti Budget Safari',
    'daytrips_meta_description' => 'Escursioni di un giorno da Arusha: Tarangire, Cratere di Ngorongoro, Lago Manyara, Parco Nazionale di Arusha, cascate di Materuni, sorgenti termali di Chemka, un villaggio Maasai e altro.',
    'daytrips_hero_badge' => 'Escursioni di un giorno',
    'daytrips_hero_title' => 'Escursioni di un giorno da Arusha',
    'daytrips_hero_sub' => 'Escursioni di un giorno per i giorni prima del tuo safari, dopo la scalata del Kilimanjaro, o ogni volta che hai una giornata libera in città.',
    'daytrips_hero_quote' => 'Richiedi un preventivo',
    'daytrips_hero_whatsapp' => 'WhatsApp',
    'daytrips_grid_badge' => 'Scegli la tua giornata',
    'daytrips_grid_title' => 'Escursioni e gite di un giorno',
    'daytrips_grid_intro' => 'Si parte da Arusha presto e si torna la sera o il pomeriggio stesso. Prezzi a persona, due persone in condivisione, park fee incluse (dove applicabile), veicolo, guida e pranzo.',
    'daytrips_1day' => 'Giornata intera',
    'daytrips_halfday' => 'Mezza giornata',
    'daytrips_from_pp' => 'da · a persona',
    'daytrips_ask_price' => 'Chiedi il prezzo',
    'daytrips_know_badge' => 'Da sapere',
    'daytrips_know_title' => 'Pianificare la tua escursione',
    'daytrips_pickup_title' => 'Ritiro',
    'daytrips_pickup_desc' => 'Ti veniamo a prendere in qualsiasi hotel ad Arusha o Moshi. La partenza è solitamente tra le 06:00 e le 08:00 a seconda della destinazione.',
    'daytrips_bring_title' => 'Cosa portare',
    'daytrips_bring_desc' => 'Scarpe chiuse, una giacca leggera per la mattina presto, crema solare, un cappello e un costume da bagno per Chemka o Materuni.',
    'daytrips_combine_title' => 'Combinare le escursioni',
    'daytrips_combine_desc' => 'Materuni e Chemka si combinano comodamente in un solo giorno. Lo stesso vale per il Lago Duluti e un tour della città di Arusha. Chiedici e costruiremo la giornata intorno ai tuoi orari di volo.',
    'daytrips_booking_title' => 'Prenotazione',
    'daytrips_booking_desc' => 'La maggior parte delle escursioni si può organizzare con 24 ore di preavviso. I safari nei parchi è meglio prenotarli qualche giorno prima in alta stagione.',
    'daytrips_final_title' => 'Pianifica la tua escursione con noi',
    'daytrips_final_intro' => 'Inviaci le tue date, la dimensione del gruppo e il budget. Ti rispondiamo con un itinerario scritto e un preventivo dettagliato — senza impegno.',
    'daytrips_final_whatsapp' => 'Scrivici su WhatsApp',
    'daytrips_final_contact' => 'Modulo di contatto',

    'daytrip_tarangire_title' => 'Tarangire',
    'daytrip_tarangire_desc' => 'A due ore da Arusha. Baobab e le più grandi mandrie di elefanti della Tanzania settentrionale, specialmente da luglio a ottobre.',
    'daytrip_ngorongoro_title' => 'Cratere di Ngorongoro',
    'daytrip_ngorongoro_desc' => 'Una giornata lunga, ma la più alta concentrazione di fauna selvatica in Africa — e la migliore possibilità di vedere il rinoceronte nero in tutto il paese.',
    'daytrip_manyara_title' => 'Lago Manyara',
    'daytrip_manyara_desc' => 'Fenicotteri sul lago sodico, leoni che si arrampicano sugli alberi e foresta fitta ai piedi della scarpata della Rift Valley.',
    'daytrip_arushanp_title' => 'Parco Nazionale di Arusha',
    'daytrip_arushanp_desc' => 'Il più vicino alla città, con giraffe, colobo e i laghi Momella. Qui sono consentiti i safari a piedi, cosa rara in Tanzania.',
    'daytrip_materuni_title' => 'Cascate di Materuni e Caffè',
    'daytrip_materuni_desc' => 'Una camminata tra piantagioni di banane e caffè sulle pendici del Kilimanjaro fino a una cascata di 90 metri, seguita dalla tostatura e macinatura del caffè con una famiglia Chagga.',
    'daytrip_chemka_title' => 'Sorgenti Termali di Chemka',
    'daytrip_chemka_desc' => 'Una piscina naturale turchese in mezzo alla boscaglia secca, calda tutto l\'anno e ombreggiata dalle radici di fico. Il miglior bagno pomeridiano della regione.',
    'daytrip_maasai_title' => 'Villaggio Maasai',
    'daytrip_maasai_desc' => 'Una visita a un boma attivo con la nostra guida Maasai Elius: le case, la pastorizia, le danze, e il tempo per fare domande vere. Non uno spettacolo messo in scena.',
    'daytrip_duluti_title' => 'Lago Duluti',
    'daytrip_duluti_desc' => 'Un lago craterico a venti minuti da Arusha: canoa tra cormorani e varani, e una camminata lungo il bordo boscoso.',
    'daytrip_arushacity_title' => 'Tour della Città di Arusha',
    'daytrip_arushacity_desc' => 'Il mercato centrale, i commercianti di tanzanite, il mercato artigianale Maasai e la torre dell\'orologio che si dice segni il punto medio tra Il Cairo e Città del Capo.',
    'daytrip_kiliday_title' => 'Trekking di un Giorno sul Kilimanjaro',
    'daytrip_kiliday_desc' => 'Fino al rifugio Mandara a 2.700 m attraverso la foresta pluviale e ritorno lo stesso giorno — la montagna senza la settimana.',

