    'blogcost_t4_r3_a' => 'Lodge dentro il parco',
    'blogcost_plus_concession' => '+ tassa di concessione',
    'blogcost_t4_r4_a' => 'Tented camp dentro il parco',
    'blogcost_t4_r5_a' => 'Campo mobile della migrazione',
    'blogcost_t4_r6_a' => 'Ultra-lusso',
    'blogcost_s3_p2' => 'Nota la tassa di concessione: dormire <em>dentro</em> un parco aggiunge $47–59 per adulto a notte oltre alla tariffa della camera. Ti dà accesso all\'alba e al tramonto dentro l\'ecosistema, quando i predatori sono attivi — davvero utile in un viaggio breve, meno in uno lungo.',
    'blogcost_s3_link' => 'Parla con noi delle opzioni di alloggio',
    'blogcost_s4_badge' => 'Veicolo',
    'blogcost_s4_title' => '3. Veicolo e guida — perché la dimensione del gruppo conta così tanto',
    'blogcost_s4_p1' => 'Un Land Cruiser con autista-guida costa lo stesso che siate in due o in sei. Carburante, veicolo, stipendio della guida e tassa di discesa nel cratere sono tutti <strong>per veicolo</strong>, non per persona.',
    'blogcost_s4_p2' => 'Questo è il modo più efficace per ridurre il prezzo a persona, e la maggior parte dei viaggiatori non se ne rende conto.',
    'blogcost_t5_h1' => 'Dimensione gruppo',
    'blogcost_t5_h2' => 'Quota costo veicolo',
    'blogcost_t5_h3' => 'Effetto sul prezzo a persona',
    'blogcost_people' => 'persone',
    'blogcost_each' => 'ciascuno',
    'blogcost_t5_r1_c' => 'Base',
    'blogcost_t5_r2_c' => 'Notevolmente più economico a testa',
    'blogcost_t5_r3_c' => 'Sostanzialmente più economico a testa',
    'blogcost_s4_p3' => 'Se siete in due con un budget limitato, unirvi a una <strong>partenza di gruppo condivisa</strong> ottiene lo stesso risparmio. Rinuncerete a un po\' di flessibilità su tempi e soste.',
    'blogcost_s5_badge' => 'Extra',
    'blogcost_s5_title' => '4. Cosa non è mai incluso',
    'blogcost_s5_i1_t' => 'Voli internazionali',
    'blogcost_s5_i1_d' => 'il costo singolo più alto per la maggior parte dei viaggiatori',
    'blogcost_s5_i2_t' => 'Visto per la Tanzania',
    'blogcost_s5_i2_d' => '$50 per la maggior parte delle nazionalità',
    'blogcost_s5_i3_t' => 'Assicurazione di viaggio',
    'blogcost_s5_i3_d' => 'obbligatoria nei nostri viaggi, e deve coprire l\'evacuazione',
    'blogcost_s5_i4_t' => 'Mance',
    'blogcost_s5_i4_d' => 'circa $20–25 al giorno per la guida dal gruppo, più lo staff del campo',
    'blogcost_s5_i5' => 'Bevande diverse dall\'acqua, e spese personali',
    'blogcost_s5_i6_t' => 'Extra opzionali',
    'blogcost_s5_i6_d' => 'volo in mongolfiera (~$599), game drive notturni, visite culturali',
    'blogcost_s5_p1' => 'Preventiva un extra di <strong>$300–500 a persona</strong> per visto, mance e imprevisti su un viaggio di una settimana, oltre al prezzo del safari.',
    'blogcost_s6_badge' => 'Risparmiare',
    'blogcost_s6_title' => 'Come spendere meno senza rovinare il viaggio',
    'blogcost_s6_sub1' => 'Cose che fanno risparmiare davvero',
    'blogcost_s6_save1_t' => 'Viaggia in bassa stagione.',
    'blogcost_s6_save1_d' => 'Aprile, maggio e novembre sono notevolmente più economici, e la fauna selvatica c\'è comunque.',
    'blogcost_s6_save2_t' => 'Siate in quattro invece che in due.',
    'blogcost_s6_save2_d' => 'Il costo del veicolo si divide.',
    'blogcost_s6_save3_t' => 'Dormite fuori dai parchi.',
    'blogcost_s6_save3_d' => 'Risparmia la tassa di concessione e la tariffa della camera; costa un\'ora di guida in più ogni mattina.',
    'blogcost_s6_save4_t' => 'Scegli parchi più economici.',
    'blogcost_s6_save4_d' => 'Tarangire e Manyara costano $59,00 contro i $82,60 del Serengeti, e sono a due ore da Arusha invece di otto.',
    'blogcost_s6_save5_t' => 'Fai campeggio.',
    'blogcost_s6_save5_d' => 'Stessa guida, stesso veicolo, stessi animali — risparmi solo sul letto.',
    'blogcost_s6_save6_t' => 'Accorcia il Serengeti, non il viaggio.',
    'blogcost_s6_save6_d' => 'Due notti nel Serengeti più due nel Tarangire costano molto meno di quattro notti nel Serengeti.',
    'blogcost_s6_sub2' => 'Cose che sono false economie',
    'blogcost_s6_false1_t' => 'Ridurre il viaggio a due giorni includendo il Serengeti.',
    'blogcost_s6_false1_d' => 'Paghi le park fee complete per passare la maggior parte del tempo a guidare.',
    'blogcost_s6_false2_t' => 'Prenotare il preventivo più economico che trovi.',
    'blogcost_s6_false2_d' => 'Le park fee sono fisse, quindi un prezzo molto sotto il mercato è finanziato da qualcos\'altro — di solito l\'equipaggio, il cibo o il veicolo.',
    'blogcost_s6_false3_t' => 'Saltare l\'assicurazione di viaggio.',
    'blogcost_s6_false3_d' => 'L\'evacuazione medica dal Serengeti costa molte migliaia di dollari.',
    'blogcost_s6_warn_t' => 'Una nota sui preventivi sospettosamente economici:',
    'blogcost_s6_warn_d' => 'le park fee su questa pagina sono pubbliche e identiche per tutti. Se un preventivo di quattro giorni nel Serengeti è appena sopra il totale delle tasse, chiedi all\'operatore di dettagliarlo. Un\'azienda seria lo farà senza esitazione.',
    'blogcost_s7_badge' => 'Esempi',
    'blogcost_s7_title' => 'Quanto costano gli itinerari reali',
    'blogcost_s7_intro' => 'Prezzi indicativi a persona, due persone in condivisione, park fee, veicolo, guida, alloggio e pasti inclusi. Il tuo preventivo scritto dettaglia ogni voce.',
    'blogcost_t6_h1' => 'Itinerario',
    'blogcost_days_tarangire_ngoro' => 'giorni — Tarangire e Ngorongoro',
    'blogcost_days_serengeti_ngoro' => 'giorni — Serengeti e Ngorongoro',
    'blogcost_days_bigfive' => 'giorni — Circuito Big Five',
    'blogcost_days_migration' => 'giorni — Safari della migrazione',
    'blogcost_days_zanzibar' => 'giorni — Safari + Zanzibar',
    'blogcost_s7_note' => 'Solo indicativo. I prezzi variano in base a stagione, dimensione del gruppo e disponibilità.',
    'blogcost_faq_badge' => 'FAQ',
    'blogcost_faq_title' => 'Costi del safari — domande frequenti',
    'blogcost_faq_q1' => 'Quanto costa un safari in Tanzania al giorno?',
    'blogcost_faq_a1' => 'Circa €200–250 a persona al giorno per il campeggio budget, €250–350 fascia media, €400+ per fly-in e €600+ per il lusso. Solo le park fee rappresentano una grande parte di questo, e sono identiche per ogni operatore.',
    'blogcost_faq_q2' => 'Cosa è incluso nel prezzo di un safari?',
    'blogcost_faq_a2' => 'Normalmente: veicolo 4x4 con autista-guida, carburante, tutte le park fee dell\'itinerario, alloggio e pasti come descritto, e acqua potabile. Non incluso: voli internazionali, visto, assicurazione, bevande, mance ed extra opzionali.',
    'blogcost_faq_q3' => 'Come posso rendere un safari più economico?',
    'blogcost_faq_a3' => 'Viaggia in bassa stagione, sii in quattro invece che in due così il costo del veicolo si divide, dormi fuori dai parchi, scegli Tarangire e Manyara invece del Serengeti, e considera il campeggio.',
    'blogcost_faq_q4' => 'La dimensione del gruppo cambia davvero il prezzo?',
    'blogcost_faq_a4' => 'Sostanzialmente. Il veicolo, la guida, il carburante e la tassa di discesa nel cratere sono tutti addebitati per veicolo, non per persona. Quattro persone in condivisione pagano notevolmente meno a testa di due, e sei ancora meno.',
    'blogcost_faq_q5' => 'Dovrei essere sospettoso di preventivi molto economici?',
    'blogcost_faq_a5' => 'Sì. Le park fee sono pubbliche e fisse per tutti, quindi un prezzo appena sopra il totale delle tasse è finanziato da qualcos\'altro. Chiedi a qualsiasi operatore di dettagliare il preventivo.',
    'blogcost_faq_q6' => 'Quanto dovrei preventivare per le mance?',
    'blogcost_faq_a6' => 'Circa $20–25 al giorno per l\'autista-guida, dal gruppo nel suo insieme, più $10–15 al giorno per lo staff del campo. Su un viaggio di una settimana per due persone, preventiva circa $200–300 in totale.',
    'blogcost_faq_q7' => 'Quanto costa il visto per la Tanzania?',
    'blogcost_faq_a7' => 'US$50 per la maggior parte delle nazionalità, ottenuto online su visa.immigration.go.tz prima di viaggiare, o all\'arrivo. Attenzione ai siti non ufficiali che addebitano costi aggiuntivi per la stessa cosa.',
    'blogcost_faq_q8' => 'Posso pagare a rate?',
    'blogcost_faq_a8' => 'I nostri termini standard prevedono un acconto del 30% per confermare e il saldo 30 giorni prima dell\'arrivo. Se prenoti con largo anticipo, di solito possiamo essere flessibili sui tempi — chiedi pure.',
    'blogcost_related_badge' => 'Continua a leggere',
    'blogcost_related_title' => 'Continua a esplorare la Tanzania',
    'blogcost_related_itineraries' => 'I nostri itinerari safari',
    'blogcost_final_title' => 'Vuoi un numero reale per il tuo viaggio?',
    'blogcost_final_intro' => 'Inviaci le tue date e la dimensione del gruppo e ti rispondiamo con un preventivo dettagliato — park fee, letti, veicolo e guida elencati separatamente, così vedi esattamente dove va il denaro.',
    'blogcost_final_whatsapp' => 'Scrivici su WhatsApp',
    'blogcost_final_contact' => 'Modulo di contatto',

    // ===== Blog article: La Grande Migrazione Mese per Mese =====
    'blogmig_meta_title' => 'La Grande Migrazione Mese per Mese (Guida 2026) | Serengeti Budget Safari',
    'blogmig_meta_description' => 'Dove si trovano le mandrie della Grande Migrazione in ogni mese dell\'anno, quando avvengono la stagione dei parti e gli attraversamenti del fiume Mara, dove alloggiare per ogni fase, e un resoconto onesto di ciò che può e non può essere garantito.',
    'blogmig_h1' => 'La Grande Migrazione, mese per mese',
    'blogmig_hero_sub' => 'Dove si trovano le mandrie in ogni mese, quando avvengono i parti e gli attraversamenti del fiume, e cosa nessun operatore può onestamente promettervi.',
    'blogmig_updated' => 'Aggiornato 2026',
    'blogmig_quick_badge' => 'Risposte rapide',
    'blogmig_quick_title' => 'La migrazione in breve',
    'blogmig_quick_intro' => 'Le sei domande che ci vengono fatte più spesso.',
    'blogmig_qq1_q' => 'Quando avviene?',
    'blogmig_qq1_a' => 'Tutto l\'anno — non si ferma mai. Cambia solo la posizione.',
    'blogmig_qq2_q' => 'Stagione dei parti?',
    'blogmig_qq2_a' => 'Da fine gennaio a febbraio, a Ndutu.',
    'blogmig_qq3_q' => 'Attraversamenti del fiume?',
    'blogmig_qq3_a' => 'Da luglio a ottobre al Mara, nel nord.',
    'blogmig_qq4_q' => 'Dove alloggio?',
    'blogmig_qq4_a' => 'Ndutu dic–mar, Kogatende lug–ott. Conta enormemente.',
    'blogmig_qq5_q' => 'Quante notti?',
    'blogmig_qq5_a' => 'Tre minimo nell\'area della migrazione.',
    'blogmig_qq6_q' => 'Attraversamento garantito?',
    'blogmig_qq6_a' => 'No. Chiunque lo prometta sta esagerando.',
    'blogmig_toc_title' => 'Indice',
    'blogmig_toc_1' => 'Cosa è realmente',
    'blogmig_toc_2' => 'Mese per mese',
    'blogmig_toc_3' => 'La stagione dei parti',
    'blogmig_toc_4' => 'Gli attraversamenti del fiume',
    'blogmig_toc_5' => 'Dove alloggiare per mese',
    'blogmig_toc_6' => 'Come pianificarla',
    'blogmig_toc_7' => 'Cinque miti comuni',
    'blogmig_toc_8' => 'FAQ',
    'blogmig_s1_badge' => 'Le basi',
    'blogmig_s1_title' => 'Cosa è realmente la Grande Migrazione',
    'blogmig_s1_p1' => 'La Grande Migrazione è il movimento continuo di circa <strong>1,3 milioni di gnu</strong>, <strong>250.000 zebre</strong> e diverse centinaia di migliaia di gazzelle di Thomson e Grant nell\'ecosistema Serengeti–Masai Mara. È il più grande movimento terrestre di animali rimasto sulla terra.',
    'blogmig_s1_p2' => 'La cosa più utile da capire è questa: <strong>non è un evento con una data.</strong> Le mandrie si trovano da qualche parte nell\'ecosistema in ogni mese dell\'anno, muovendosi in un percorso circolare guidato dalle piogge e dalla crescita di erba nuova. Non c\'è un inizio né una fine. Ciò che cambia mese per mese è <em>dove</em> si trovano, e quindi dove dovete essere voi.',
    'blogmig_s1_p3' => 'Una seconda cosa utile da sapere: gli gnu non viaggiano come un\'unica enorme mandria. Si muovono in lunghe colonne e gruppi sparsi su decine di chilometri, a volte convergendo nelle masse dense che appaiono nei documentari, a volte disperse su pianure aperte. Entrambe sono la migrazione.',
    'blogmig_fact_wildebeest' => 'Gnu',
    'blogmig_fact_zebra' => 'Zebre',
    'blogmig_fact_gazelle' => 'Gazzelle',
    'blogmig_fact_distance' => 'Distanza annuale',
    'blogmig_fact_calves' => 'Cuccioli nati',
    'blogmig_fact_year' => 'anno',
    'blogmig_fact_ecosystem' => 'Ecosistema',
    'blogmig_s2_badge' => 'Il calendario',
    'blogmig_s2_title' => 'Mese per mese: dove si trovano le mandrie',
    'blogmig_s2_intro' => 'Lo schema seguente si ripete ogni anno, ma le piogge lo spostano di due o tre settimane in un senso o nell\'altro. Consideratelo una forte probabilità, mai un orario preciso.',
    'blogmig_t1_h1' => 'Mese',
    'blogmig_t1_h2' => 'Dove si trovano le mandrie',
    'blogmig_t1_h3' => 'Cosa succede',
    'blogmig_t1_h4' => 'Alloggiare a',
    'blogmig_m1_name' => 'Gennaio', 'blogmig_m1_where' => 'Pianure meridionali e Ndutu', 'blogmig_m1_what' => 'Le mandrie si stabiliscono sulle pianure a erba corta. I parti iniziano a fine mese.', 'blogmig_m1_stay' => 'Ndutu',
    'blogmig_m2_name' => 'Febbraio', 'blogmig_m2_where' => 'Ndutu e Serengeti meridionale', 'blogmig_m2_what' => '<strong>Picco dei parti.</strong> Fino a 8.000 nascite al giorno in una finestra di tre settimane. Attività dei predatori al massimo dell\'anno.', 'blogmig_m2_stay' => 'Ndutu',
    'blogmig_m3_name' => 'Marzo', 'blogmig_m3_where' => 'Pianure meridionali, in movimento', 'blogmig_m3_what' => 'I cuccioli si rinforzano. Iniziano le grandi piogge; le mandrie iniziano a spostarsi a nord-ovest.', 'blogmig_m3_stay' => 'Ndutu / Seronera',
    'blogmig_m4_name' => 'Aprile', 'blogmig_m4_where' => 'Serengeti centrale e occidentale', 'blogmig_m4_what' => 'Grandi piogge. Si formano colonne in movimento. Verde, drammatico, quasi senza turisti.', 'blogmig_m4_stay' => 'Seronera / Moru',
    'blogmig_m5_name' => 'Maggio', 'blogmig_m5_where' => 'Corridoio Occidentale', 'blogmig_m5_what' => 'Accoppiamento — i maschi combattono per il diritto di riprodursi. Lunghe colonne verso ovest.', 'blogmig_m5_stay' => 'Corridoio Occidentale',
    'blogmig_m6_name' => 'Giugno', 'blogmig_m6_where' => 'Corridoio Occidentale e fiume Grumeti', 'blogmig_m6_what' => '<strong>Attraversamenti del Grumeti.</strong> Più piccoli del Mara ma con coccodrilli enormi e pochissimi veicoli.', 'blogmig_m6_stay' => 'Corridoio Occidentale / Grumeti',
    'blogmig_m7_name' => 'Luglio', 'blogmig_m7_where' => 'Serengeti settentrionale', 'blogmig_m7_what' => 'Le mandrie raggiungono il fiume Mara. Primi attraversamenti, spesso esitanti.', 'blogmig_m7_stay' => 'Kogatende',
    'blogmig_m8_name' => 'Agosto', 'blogmig_m8_where' => 'Serengeti settentrionale e Masai Mara', 'blogmig_m8_what' => '<strong>Picco degli attraversamenti del Mara.</strong> I più frequenti e drammatici dell\'anno.', 'blogmig_m8_stay' => 'Kogatende',
    'blogmig_m9_name' => 'Settembre', 'blogmig_m9_where' => 'Serengeti settentrionale e Mara', 'blogmig_m9_what' => 'Gli attraversamenti continuano in entrambe le direzioni mentre le mandrie vanno avanti e indietro sul fiume.', 'blogmig_m9_stay' => 'Kogatende',
    'blogmig_m10_name' => 'Ottobre', 'blogmig_m10_where' => 'Serengeti settentrionale, verso sud', 'blogmig_m10_what' => 'Ultimi attraversamenti. Le mandrie iniziano il viaggio di ritorno lungo il Serengeti orientale.', 'blogmig_m10_stay' => 'Kogatende / Lobo',
    'blogmig_m11_name' => 'Novembre', 'blogmig_m11_where' => 'Serengeti orientale e centrale', 'blogmig_m11_what' => 'Le piccole piogge spingono le mandrie a sud. Lunghe colonne attraverso Lobo e Seronera.', 'blogmig_m11_stay' => 'Lobo / Seronera',
    'blogmig_m12_name' => 'Dicembre', 'blogmig_m12_where' => 'Pianure meridionali', 'blogmig_m12_what' => 'Arrivo sulle pianure a erba corta. Il ciclo ricomincia.', 'blogmig_m12_stay' => 'Ndutu / Seronera',
    'blogmig_s3_badge' => 'Parti',
    'blogmig_s3_title' => 'La stagione dei parti — la parte che quasi tutti si perdono',
    'blogmig_s3_p1' => 'Tra fine gennaio e febbraio, circa <strong>400.000 cuccioli di gnu</strong> nascono sulle pianure a erba corta intorno a <strong>Ndutu</strong>, con un picco di fino a <strong>8.000 nascite in un solo giorno</strong>. Circa l\'80% delle femmine partorisce nella stessa finestra di tre settimane.',
    'blogmig_s3_sub1' => 'Perché partoriscono tutte insieme',
    'blogmig_s3_p2' => 'È una strategia di sopravvivenza chiamata "predator swamping" (saturazione dei predatori). Inondando le pianure di nuovi nati in un\'esplosione concentrata, la mandria garantisce che i predatori non possano prenderli tutti — leoni, iene e ghepardi sono semplicemente sopraffatti. Un cucciolo nato fuori da quella finestra ha molte più probabilità di essere ucciso.',
    'blogmig_s3_sub2' => 'Perché proprio Ndutu',
    'blogmig_s3_p3' => 'Le pianure meridionali poggiano su cenere vulcanica soffiata dagli altopiani di Ngorongoro, che ha creato uno strato duro vicino alla superficie. Gli alberi non possono radicarsi attraverso di esso, quindi le pianure restano aperte — buona visibilità contro i predatori — e l\'erba corta che vi cresce è insolitamente ricca di calcio e fosforo. È esattamente ciò di cui una madre che allatta ha bisogno per costruire le ossa di un cucciolo.',
    'blogmig_s3_sub3' => 'Cosa si vede realmente',
    'blogmig_s3_p4' => 'Cuccioli in piedi pochi minuti dopo la nascita e che corrono entro un\'ora. Gruppi di centinaia di cuccioli. E, inevitabilmente, predazione: questo è il mese in cui leoni, ghepardi e iene cacciano con più successo, e vedrete uccisioni. Alcuni viaggiatori trovano questo difficile — vale la pena saperlo in anticipo.',
    'blogmig_s3_note_t' => 'Un\'opinione onesta delle nostre guide:',
    'blogmig_s3_note_d' => 'la maggior parte delle persone viene ad agosto per gli attraversamenti del fiume. Se chiedete alle guide quale stagione sceglierebbero per sé stesse, una chiara maggioranza dice febbraio a Ndutu. L\'attività della fauna è più costante, più varia, e ci sono molti meno veicoli.',
    'blogmig_s4_badge' => 'Attraversamenti',
    'blogmig_s4_title' => 'Gli attraversamenti del fiume — e la verità su di essi',
    'blogmig_s4_p1' => 'L\'immagine che tutti hanno della migrazione — migliaia di gnu che si tuffano in un fiume mentre i coccodrilli aspettano — è reale, e avviene al <strong>fiume Mara</strong> nel Serengeti settentrionale tra luglio e ottobre, e al <strong>fiume Grumeti</strong> a ovest intorno a giugno.',
    'blogmig_s4_sub1' => 'Cosa succede realmente',
    'blogmig_s4_p2' => 'Le mandrie si radunano sulla riva, spesso a migliaia. Aspettano. A volte per venti minuti, a volte per sei ore, a volte tutto il giorno. Poi un animale si decide e gli altri seguono in pochi minuti frenetici — oppure l\'intera mandria si gira e se ne va senza attraversare affatto.',
    'blogmig_s4_p3' => 'Nessuno controlla questo e nessuno può prevederlo. Si sono viste mandrie attraversare, pascolare sulla riva opposta per un\'ora, e attraversare di nuovo subito indietro.',
    'blogmig_s4_sub2' => 'Le probabilità reali',
    'blogmig_s4_p4' => 'Con <strong>tre notti a Kogatende tra fine luglio e settembre</strong>, avete buone probabilità di assistere ad almeno un attraversamento. Con una notte, state scommettendo. Qualsiasi operatore che garantisce un attraversamento in una data specifica è male informato o vi sta vendendo qualcosa che non può mantenere.',
    'blogmig_s4_note_t' => 'Quello che diciamo ai nostri clienti:',
    'blogmig_s4_note_d' => 'prenotate almeno tre notti al nord se un attraversamento è il motivo del vostro viaggio, andate ad agosto o inizio settembre, e accettate che le mattine passate ad aspettare su una riva senza che accada nulla fanno parte dell\'esperienza.',
    'blogmig_s4_sub3' => 'Grumeti vs Mara',
    'blogmig_s4_mara' => 'Fiume Mara',
    'blogmig_s4_grumeti' => 'Fiume Grumeti',
    'blogmig_s4_row_months' => 'Mesi',
    'blogmig_s4_mara_months' => 'Luglio – Ottobre',
    'blogmig_s4_grumeti_months' => 'Maggio – Luglio',
    'blogmig_s4_row_scale' => 'Scala',
    'blogmig_s4_mara_scale' => 'Grande, drammatico',
    'blogmig_s4_grumeti_scale' => 'Più piccolo, più disperso',
    'blogmig_s4_row_croc' => 'Coccodrilli',
    'blogmig_s4_mara_croc' => 'Molti',
    'blogmig_s4_grumeti_croc' => 'Meno ma enormi',
    'blogmig_s4_row_vehicles' => 'Veicoli',
    'blogmig_s4_mara_vehicles' => 'Molti in alta stagione',
    'blogmig_s4_grumeti_vehicles' => 'Pochissimi',
    'blogmig_s4_row_stay' => 'Dove alloggiare',
    'blogmig_s4_mara_stay' => 'Kogatende',
    'blogmig_s4_grumeti_stay' => 'Corridoio Occidentale',
    'blogmig_s5_badge' => 'Alloggio',
    'blogmig_s5_title' => 'Dove alloggiare per ogni fase',
    'blogmig_s5_p1' => 'È qui che la maggior parte dei viaggi per la migrazione va storta. Prenotare "un lodge nel Serengeti" non basta — il parco è di 14.763 km², e un lodge al centro è a cinque ore di guida dalle mandrie se si trovano a nord.',
    'blogmig_t2_h1' => 'Se viaggi in…',
    'blogmig_t2_h2' => 'Alloggia a…',
    'blogmig_t2_h3' => 'Perché',
    'blogmig_t2_r1_a' => 'Dicembre – Marzo', 'blogmig_t2_r1_b' => 'Ndutu', 'blogmig_t2_r1_c' => 'Stagione dei parti sulle pianure meridionali',
    'blogmig_t2_r2_a' => 'Aprile – Maggio', 'blogmig_t2_r2_b' => 'Seronera / Moru', 'blogmig_t2_r2_c' => 'Mandrie in movimento attraverso il centro e l\'ovest',
    'blogmig_t2_r3_a' => 'Maggio – Luglio', 'blogmig_t2_r3_b' => 'Corridoio Occidentale', 'blogmig_t2_r3_c' => 'Attraversamenti del fiume Grumeti',
    'blogmig_t2_r4_a' => 'Luglio – Ottobre', 'blogmig_t2_r4_b' => 'Kogatende', 'blogmig_t2_r4_c' => 'Attraversamenti del fiume Mara al nord',
    'blogmig_t2_r5_a' => 'Novembre', 'blogmig_t2_r5_b' => 'Lobo / Seronera', 'blogmig_t2_r5_c' => 'Viaggio di ritorno attraverso l\'est',
    'blogmig_s5_sub1' => 'Campi mobili',
    'blogmig_s5_p2' => 'Diversi operatori gestiscono campi tendati mobili che si spostano fisicamente due o tre volte l\'anno per seguire le mandrie. Sono il modo più affidabile per restare vicini alla migrazione, sono solitamente piccoli e remoti, e costano circa $300–700 a persona a notte. Se la migrazione è l\'intero scopo del vostro viaggio, è questo che volete.',
    'blogmig_s5_link' => 'Parla con noi delle opzioni di alloggio',
    'blogmig_s6_badge' => 'Pianificazione',
    'blogmig_s6_title' => 'Come pianificare un safari della migrazione',
    'blogmig_s6_step1_t' => 'Passo 1 — decidi quale fase vuoi',
    'blogmig_s6_step1_d' => 'Parti a Ndutu, o attraversamenti del fiume al nord. Queste sono le due esperienze principali e avvengono agli estremi opposti sia del parco che del calendario. Non potete fare entrambe in un solo viaggio.',
    'blogmig_s6_step2_t' => 'Passo 2 — prenota in anticipo',
    'blogmig_s6_step2_d' => 'I campi a Kogatende per agosto e settembre, e a Ndutu per febbraio, si esauriscono <strong>da sei a dodici mesi prima</strong>. Non è una tattica di vendita — quelle aree hanno posti letto limitati, e i buoni campi piccoli vanno esauriti per primi.',
    'blogmig_s6_step3_t' => 'Passo 3 — dedica abbastanza notti',
    'blogmig_s6_step3_d' => 'Tre notti minimo nell\'area della migrazione. Due è una scommessa, una è un biglietto della lotteria.',
    'blogmig_s6_step4_t' => 'Passo 4 — considera di volare',
    'blogmig_s6_step4_d' => 'Kogatende è a due giorni di guida da Arusha. Un volo di 1 ora e 15 minuti trasforma quattro giorni di guida in quattro giorni in più di osservazione della fauna. Per un viaggio nel Serengeti settentrionale, volare è quasi sempre la scelta giusta.',
    'blogmig_s6_step5_t' => 'Passo 5 — includi il resto dell\'ecosistema',
    'blogmig_s6_step5_d' => 'La migrazione non è l\'unica cosa che vale la pena vedere. I predatori residenti, il Cratere di Ngorongoro e gli elefanti del Tarangire sono tutti lì indipendentemente da dove si trovano le mandrie, e un buon itinerario li usa per riempire i giorni intorno alle notti della migrazione.',
    'blogmig_t3_h1' => 'Durata del viaggio',
    'blogmig_t3_h2' => 'Struttura suggerita',
    'blogmig_days' => 'giorni',
    'blogmig_t3_r1_b' => 'Volo diretto verso l\'area della migrazione per 3 notti, Ngorongoro al ritorno',
    'blogmig_t3_r2_b' => 'Tarangire, Serengeti centrale 2 notti, area della migrazione 3 notti, Ngorongoro',
    'blogmig_t3_r3_b' => 'Circuito settentrionale completo con 4 notti nell\'area della migrazione, poi Zanzibar',
    'blogmig_s7_badge' => 'Miti',
    'blogmig_s7_title' => 'Cinque cose che le persone sbagliano',
    'blogmig_s7_myth1_t' => 'La migrazione avviene ad agosto',
    'blogmig_s7_myth1_d' => 'Gli <em>attraversamenti del fiume Mara</em> avvengono intorno ad agosto. La migrazione stessa è continua — le mandrie sono sempre da qualche parte, e non c\'è mese in cui non succede nulla.',
    'blogmig_s7_myth2_t' => 'Devo andare in Kenya per vederla',
    'blogmig_s7_myth2_d' => 'Circa l\'80% del ciclo annuale della migrazione è all\'interno della Tanzania. Le mandrie trascorrono circa due o tre mesi nel Masai Mara e il resto dell\'anno nell\'ecosistema del Serengeti.',
    'blogmig_s7_myth3_t' => 'Un attraversamento è garantito se vado nel momento giusto',
    'blogmig_s7_myth3_d' => 'Non lo è. Essere nel posto giusto nel mese giusto vi dà buone probabilità in più giorni. Non garantisce nulla a nessuno in una singola mattinata.',
    'blogmig_s7_myth4_t' => 'La migrazione è un\'unica mandria gigante',
    'blogmig_s7_myth4_d' => 'Sono colonne e gruppi sparsi su decine di chilometri, a volte convergenti e a volte dispersi. L\'immagine del documentario con una massa compatta è un momento, non lo stato normale.',
    'blogmig_s7_myth5_t' => 'La stagione delle piogge è un brutto momento',
    'blogmig_s7_myth5_d' => 'Aprile e maggio sono verdi, drammatici, quasi senza altri veicoli e considerevolmente più economici — e le mandrie si muovono attraverso il centro e l\'ovest, il che è un\'ottima osservazione. Se la vostra priorità è il valore e la solitudine piuttosto che gli attraversamenti del fiume, i mesi delle piogge sono sottovalutati.',
    'blogmig_faq_title' => 'La Grande Migrazione — domande frequenti',
    'blogmig_faq_q1' => 'Qual è il momento migliore per vedere la Grande Migrazione?',
    'blogmig_faq_a1' => 'Dipende da quale fase volete. Da fine gennaio a febbraio per la stagione dei parti a Ndutu; da luglio a ottobre per gli attraversamenti del fiume Mara nel Serengeti settentrionale. Entrambe sono eccezionali, e avvengono agli estremi opposti del parco e del calendario.',
    'blogmig_faq_q2' => 'Posso vedere la migrazione tutto l\'anno?',
    'blogmig_faq_a2' => 'Sì. Le mandrie non lasciano mai l\'ecosistema — si muovono in un ciclo continuo. Ciò che cambia è dove si trovano, quindi la regione in cui alloggiate deve corrispondere al vostro mese.',
    'blogmig_faq_q3' => 'Vedrò sicuramente un attraversamento del fiume?',
    'blogmig_faq_a3' => 'No, e siate scettici verso chiunque lo prometta. Le mandrie possono aspettare sulla riva per un giorno intero e poi andarsene. Tre notti a Kogatende tra fine luglio e settembre vi danno buone probabilità, non una garanzia.',
    'blogmig_faq_q4' => 'Dovrei andare in Tanzania o in Kenya per la migrazione?',
    'blogmig_faq_a4' => 'Circa l\'80% del ciclo annuale è in Tanzania — le mandrie trascorrono solo due o tre mesi nel Masai Mara. La Tanzania offre anche la stagione dei parti, che il Kenya non ha.',
    'blogmig_faq_q5' => 'Dove devo alloggiare per la stagione dei parti?',
    'blogmig_faq_a5' => 'Ndutu, sulle pianure meridionali a erba corta, tra dicembre e marzo. Nota che Ndutu si trova tecnicamente all\'interno dell\'Area di Conservazione di Ngorongoro piuttosto che nel Serengeti, anche se ecologicamente è la stessa pianura.',
    'blogmig_faq_q6' => 'Quanti giorni servono per un safari della migrazione?',
    'blogmig_faq_a6' => 'Tre notti minimo nell\'area della migrazione stessa, più i giorni di viaggio. Due notti sono una scommessa e una è un biglietto della lotteria. Cinque-sette giorni totali fanno un viaggio comodo.',
    'blogmig_faq_q7' => 'Quanti gnu ci sono?',
    'blogmig_faq_a7' => 'Circa 1,3 milioni di gnu, più circa 250.000 zebre e diverse centinaia di migliaia di gazzelle. È il più grande movimento terrestre di animali rimasto sulla terra.',
    'blogmig_faq_q8' => 'Cos\'è un campo mobile?',
    'blogmig_faq_a8' => 'Un campo tendato che si sposta fisicamente due o tre volte l\'anno per seguire le mandrie. È il modo più affidabile per restare vicini alla migrazione, tipicamente $300–700 a persona a notte, e solitamente piccolo e remoto.',
    'blogmig_final_title' => 'Pronto a pianificare il tuo safari della migrazione?',
    'blogmig_final_intro' => 'Diteci le vostre date e vi diremo onestamente se è stagione dei parti, stagione degli attraversamenti, o qualcosa nel mezzo — e costruiremo l\'itinerario di conseguenza.',

    // Blog article: Best time to visit Tanzania
    'blogbest_meta_title' => 'Periodo Migliore per Visitare la Tanzania: Mese per Mese (2026) | Serengeti Budget Safari',
    'blogbest_meta_description' => 'Quando visitare la Tanzania, mese per mese: stagione secca, le due stagioni delle piogge, la stagione dei parti e gli attraversamenti del fiume Mara, temperature per altitudine, e i mesi migliori per safari, Kilimangiaro e Zanzibar.',
    'blogbest_h1' => 'Periodo migliore per visitare la Tanzania',
    'blogbest_hero_sub' => 'Mese per mese — cosa vedrai, con quanti altri veicoli condividerai la scena, e quanto spenderai. Non esiste una stagione chiusa, solo compromessi.',
