    'blogbest_s1_badge' => 'In breve',
    'blogbest_s1_title' => 'La risposta breve',
    'blogbest_s1_p1' => 'Da <strong>giugno a ottobre</strong> è la stagione secca ed è il periodo più semplice per osservare la fauna selvatica quasi ovunque in Tanzania. <strong>Fine gennaio e febbraio</strong> portano la stagione dei parti nel Serengeti meridionale, che molte guide considerano lo spettacolo migliore. <strong>Da marzo a maggio</strong> sono le grandi piogge: verde, tranquillo e decisamente più economico.',
    'blogbest_s1_p2' => 'Non esiste una stagione chiusa. Ciò che cambia è cosa vedi, con quanti altri veicoli condividi la scena e quanto spendi.',
    'blogbest_t1_h1' => 'Stagione',
