    'blogbest_s2_badge' => 'Stagioni',
    'blogbest_s2_title' => 'La Tanzania ha due stagioni delle piogge, non una',
    'blogbest_s2_p1' => 'Confonderle è l\'errore di pianificazione più comune, e sono davvero molto diverse tra loro.',
    'blogbest_s2_sub1_title' => 'Le grandi piogge — marzo-maggio',
    'blogbest_s2_sub1_p' => 'Pioggia vera, spesso per diverse ore al giorno, più intensa ad aprile. Alcune piste diventano impraticabili, il terreno di cotone nero del Corridoio Occidentale si trasforma in fango appiccicoso, e diversi campi stagionali chiudono completamente — in particolare a Ruaha e Nyerere. È anche il periodo più economico dell\'anno, il paesaggio è spettacolare, e puoi avere i parchi quasi tutti per te.',
    'blogbest_s2_sub2_title' => 'Le piccole piogge — novembre-dicembre',
    'blogbest_s2_sub2_p' => 'Piogge brevi e intense nel tardo pomeriggio, con il resto della giornata solitamente soleggiato. Niente chiude, niente si allaga, il paese diventa verde e i prezzi restano moderati. Per molti viaggiatori è il miglior compromesso dell\'anno, ed è decisamente sottovalutato.',
    'blogbest_s2_note_t' => 'Da sapere:',
    'blogbest_s2_note_d' => 'la pioggia in Tanzania raramente significa una giornata rovinata. Di solito significa un\'ora intensa e poi aria limpida, luce drammatica e un paesaggio che si fotografa molto meglio dell\'agosto polveroso.',
