    'blogbest_w9_why' => 'Secco, mare calmo, buona visibilità per le immersioni',
    'blogbest_w10_want' => 'Circuito meridionale',
    'blogbest_w10_why' => 'Ruaha e Nyerere chiudono in gran parte da marzo a maggio',
    'blogbest_s5_badge' => 'Clima',
    'blogbest_s5_title' => 'Com\'è davvero il clima',
    'blogbest_s5_p1' => 'La Tanzania si trova sull\'equatore, ma l\'altitudine conta molto più della latitudine. I parchi del nord sono tra i 1.000 m e i 2.400 m, motivo per cui le mattine sono davvero fredde.',
    'blogbest_t4_h1' => 'Luogo',
    'blogbest_t4_h2' => 'Altitudine',
    'blogbest_t4_h3' => 'Giorno',
    'blogbest_t4_h4' => 'Alba',
    'blogbest_c1_place' => 'Bordo del cratere di Ngorongoro',
    'blogbest_c2_place' => 'Serengeti',
    'blogbest_c3_place' => 'Arusha',
    'blogbest_c4_place' => 'Tarangire',
    'blogbest_c5_place' => 'Zanzibar',
    'blogbest_c6_place' => 'Vetta del Kilimangiaro',
    'blogbest_sea_level' => 'Livello del mare',
    'blogbest_colder' => 'Più freddo',
    'blogbest_s5_p2' => 'Il dato che sorprende di più è il bordo del cratere di Ngorongoro all\'alba: circa 5 °C, su un veicolo aperto, in movimento. Ogni visitatore che ha fatto i bagagli pensando solo all\'"Africa" se ne pente. I capi a strati non sono opzionali.',
    'blogbest_faq_badge' => 'FAQ',
    'blogbest_faq_title' => 'Quando visitare la Tanzania — domande frequenti',
    'blogbest_faq_q1' => 'Qual è il periodo migliore per visitare la Tanzania?',
    'blogbest_faq_a1' => 'Da giugno a ottobre per gli avvistamenti più facili ovunque, e da fine gennaio a febbraio per la stagione dei parti nel Serengeti. Da marzo a maggio sono le grandi piogge — verde, tranquillo e di gran lunga il periodo più economico.',
    'blogbest_faq_q2' => 'Qual è il periodo peggiore per visitare la Tanzania?',
    'blogbest_faq_a2' => 'Aprile è il mese più piovoso ed è quello che la maggior parte delle persone evita. Le piste diventano difficili, alcuni campi del sud chiudono completamente, e le visuali sono spesso ostacolate. È anche il mese più economico e i parchi sono quasi vuoti, quindi si adatta molto bene ad alcuni viaggiatori.',
    'blogbest_faq_q3' => 'Posso fare un safari nella stagione delle piogge?',
    'blogbest_faq_a3' => 'Sì. I parchi del nord operano tutto l\'anno e la pioggia solitamente arriva in intensi rovesci piuttosto che per l\'intera giornata. Ruaha e Nyerere nel sud sono diversi — la maggior parte dei campi lì chiude tra marzo e maggio.',
    'blogbest_faq_q4' => 'Quando avvengono gli attraversamenti del fiume Mara?',
    'blogbest_faq_a4' => 'Da luglio a ottobre nel Serengeti settentrionale, con agosto e settembre come mesi di picco per la frequenza. Essere lì nel mese giusto ti dà buone probabilità in più giorni, mai una garanzia in una mattina specifica.',
    'blogbest_faq_q5' => 'Quando è la stagione dei parti?',
    'blogbest_faq_a5' => 'Fine gennaio e febbraio, sulle pianure a erba corta attorno a Ndutu. Circa 400.000 cuccioli nascono in una finestra di tre settimane, e l\'attività dei predatori è al massimo dell\'anno.',
    'blogbest_faq_q6' => 'Fa freddo in Tanzania?',
    'blogbest_faq_a6' => 'In altitudine sì, e questo sorprende la maggior parte dei visitatori. Il bordo del cratere di Ngorongoro scende a circa 5 °C prima dell\'alba, e il Serengeti a 13–15 °C. Di giorno fa caldo, quindi la risposta sono gli strati, non un unico giaccone pesante.',
    'blogbest_faq_q7' => 'Qual è il periodo più economico per fare un safari?',
    'blogbest_faq_a7' => 'Aprile e maggio, durante le grandi piogge, quando i campi applicano forti sconti e i parchi sono quasi vuoti. Novembre è il secondo periodo più economico ed è decisamente più asciutto — brevi rovesci pomeridiani invece di pioggia per tutto il giorno.',
    'blogbest_faq_q8' => 'Qual è il periodo migliore per scalare il Kilimangiaro?',
    'blogbest_faq_a8' => 'Da gennaio a inizio marzo e da giugno a ottobre. Gennaio e febbraio hanno le notti in vetta più calde; da giugno a ottobre è il periodo più secco e affollato. Aprile e maggio sono le grandi piogge ed è meglio evitarli sulla montagna.',
    'blogbest_faq_q9' => 'Qual è il periodo migliore per Zanzibar?',
    'blogbest_faq_a9' => 'Da giugno a ottobre è secco e meno umido; da dicembre a febbraio fa caldo con mare calmo ed eccellente visibilità per le immersioni. Da marzo a maggio sono le grandi piogge, quando alcuni hotel chiudono.',
    'blogbest_faq_q10' => 'Quanto è affollato agosto?',
    'blogbest_faq_a10' => 'È il mese di punta. I campi nel Serengeti settentrionale si esauriscono da sei a dodici mesi prima, i prezzi sono ai massimi, e condividerai gli avvistamenti. La fauna selvatica è superba — semplicemente non sarai solo ad ammirarla.',
    'blogbest_faq_q11' => 'Novembre è un buon mese?',
    'blogbest_faq_a11' => 'È uno dei mesi più sottovalutati. Le piccole piogge portano brevi rovesci pomeridiani, il paesaggio diventa verde, arrivano i migratori per i birdwatcher, i prezzi sono moderati e i parchi sono tranquilli. Niente chiude.',
    'blogbest_faq_q12' => 'La migrazione si ferma nella stagione delle piogge?',
    'blogbest_faq_a12' => 'No. Le mandrie sono nell\'ecosistema tutti i mesi dell\'anno — le piogge sono proprio ciò che le muove. Ad aprile e maggio si spostano attraverso il Serengeti centrale e occidentale.',
    'blogbest_faq_q13' => 'E per Natale e Capodanno?',
    'blogbest_faq_a13' => 'Affollato e costoso. Molti campi applicano un supplemento di alta stagione da circa il 20 dicembre al 3 gennaio e richiedono soggiorni minimi. Gli avvistamenti sono buoni, ma si paga per le date.',
    'blogbest_faq_q14' => 'Posso combinare safari e Zanzibar in qualsiasi periodo dell\'anno?',
    'blogbest_faq_a14' => 'Le stagioni si allineano bene: da giugno a ottobre e da dicembre a febbraio sono buoni per entrambi. Da marzo a maggio combineresti un safari bagnato con una costa bagnata, motivo per cui quel periodo è il più economico.',
    'blogbest_related_badge' => 'Continua a leggere',
    'blogbest_related_title' => 'Continua a esplorare la Tanzania',
    'blogbest_related_kili' => 'Guida al Kilimangiaro',
    'blogbest_final_title' => 'Dicci le tue date',
    'blogbest_final_intro' => 'Inviaci le settimane in cui puoi viaggiare e ti diremo onestamente cosa vedrai in quel periodo, dove dovrebbero trovarsi le mandrie, e se spostarsi di due settimane varrebbe la pena.',
    'blogbest_final_whatsapp' => 'Scrivici su WhatsApp',
    'blogbest_final_contact' => 'Modulo di contatto',

    // ===== Blog article: Le Mance in Safari e sul Kilimanjaro =====
    'blogtip_meta_title' => 'Le Mance in Safari e sul Kilimanjaro: Quanto Lasciare? (2026) | Serengeti Budget Safari',
    'blogtip_meta_description' => 'Quanto lasciare di mancia in Tanzania: cifre indicative per guide safari, staff del campo e cuochi, oltre alle cifre ben più alte per l\'equipaggio del Kilimanjaro, con esempi pratici e consigli sul contante.',
    'blogtip_h1' => 'Le mance in safari e sul Kilimanjaro',
    'blogtip_hero_sub' => 'Cos\'è consuetudine, a quanto ammonta in totale, e perché la cifra del Kilimanjaro sorprende molti — te lo diciamo prima che tu prenoti, non sulla montagna.',
    'blogtip_updated' => 'Aggiornato 2026',
