    'blogtip_qq4_q' => 'Contanti o carta?',
    'blogtip_qq4_a' => 'Solo contanti. Niente bancomat nei parchi.',
    'blogtip_qq5_q' => 'Quando?',
    'blogtip_qq5_a' => 'Alla fine, non ogni giorno.',
    'blogtip_qq6_q' => 'Condizione delle banconote?',
    'blogtip_qq6_a' => 'Le banconote USA devono essere emesse dopo il 2009.',
    'blogtip_see_faq' => 'Vedi tutte le FAQ',
    'blogtip_toc_title' => 'Indice – Le mance in safari e sul Kilimanjaro',
    'blogtip_toc_1' => 'Perché è importante',
    'blogtip_toc_2' => 'Mance in safari',
    'blogtip_toc_3' => 'Mance sul Kilimanjaro',
    'blogtip_toc_4' => 'Punti pratici',
    'blogtip_toc_5' => 'FAQ',
    'blogtip_s1_badge' => 'Contesto',
    'blogtip_s1_title' => 'Perché le mance contano qui',
    'blogtip_s1_p1' => 'Le mance in Tanzania sono consuetudine e rappresentano una parte significativa di ciò che guadagnano guide, cuochi, portatori e staff del campo. Sono genuinamente facoltative — nessuno te le richiederà — ma sono attese, e chi le riceve ci fa affidamento nel proprio bilancio.',
    'blogtip_s1_p2' => 'Le cifre qui sotto sono le linee guida che diamo ai nostri clienti. Non sono regole, e puoi adattarle in base al servizio, alla dimensione del gruppo e al tuo budget senza sensi di colpa.',
    'blogtip_s2_badge' => 'Safari',
    'blogtip_s2_title' => 'Linee guida per le mance in safari',
    'blogtip_t1_h1' => 'Chi',
    'blogtip_t1_h2' => 'Importo',
    'blogtip_t1_h3' => 'Base',
    'blogtip_t1_r1_a' => 'Autista-guida',
    'blogtip_t1_r1_c' => 'Dal gruppo nel suo insieme, non a persona',
    'blogtip_t1_r2_a' => 'Staff del campo / lodge',
    'blogtip_t1_r2_c' => 'Nella cassa comune per le mance, dal gruppo',
    'blogtip_t1_r3_a' => 'Cuoco (safari in campeggio)',
    'blogtip_t1_r3_c' => 'Dal gruppo',
    'blogtip_t1_r4_a' => 'Autista del trasferimento aeroportuale',
    'blogtip_t1_r4_c' => 'Per trasferimento',
    'blogtip_t1_r5_a' => 'Ristorante',
    'blogtip_t1_r5_c' => 'Se il servizio non è incluso',
    'blogtip_per_day' => 'al giorno',
    'blogtip_s2_example_title' => 'Un esempio pratico',
    'blogtip_s2_example_intro' => 'Due persone, safari di quattro giorni, un autista-guida, alloggio in lodge:',
    'blogtip_s2_ex_li1' => 'Guida: $22 × 4 giorni = <strong>$88</strong>',
    'blogtip_s2_ex_li2' => 'Staff del lodge: $12 × 4 giorni = <strong>$48</strong>',
    'blogtip_s2_ex_li3' => '<strong>Totale per il gruppo: circa $136</strong>, ovvero $68 a testa',
    'blogtip_s3_badge' => 'Kilimanjaro',
    'blogtip_s3_title' => 'Mance sul Kilimanjaro',
    'blogtip_s3_p1' => 'Una scalata coinvolge un equipaggio molto più numeroso — tipicamente da tre a quattro persone per scalatore — e le mance sono una parte sostanziale e attesa del loro reddito. Gli importi sono <strong>al giorno, dall\'intero gruppo</strong>.',
    'blogtip_t2_h1' => 'Ruolo',
    'blogtip_t2_h2' => 'Al giorno, dal gruppo',
    'blogtip_t2_r1_a' => 'Guida capo',
    'blogtip_t2_r2_a' => 'Guida assistente',
    'blogtip_t2_r3_a' => 'Cuoco',
    'blogtip_t2_r4_a' => 'Portatore (ciascuno)',
    'blogtip_s3_sub_title' => 'Quanto fa in totale',
    'blogtip_s3_p2' => 'Due scalatori su un percorso Machame di sette giorni, con un equipaggio di circa undici persone — una guida capo, un assistente, un cuoco e otto portatori — dovrebbero prevedere circa <strong>$800–1.000 in mance totali</strong>, ovvero $400–500 a testa.',
    'blogtip_s3_p3' => 'È una cifra importante e sorprende molti, ed è esattamente per questo che te lo diciamo prima che tu prenoti, non sulla montagna. Includila nel tuo budget fin dall\'inizio.',
    'blogtip_s3_note_t' => 'Come funziona in pratica:',
    'blogtip_s3_note_d' => 'le mance vengono raccolte dal gruppo e consegnate durante una cerimonia l\'ultima mattina, di solito con l\'equipaggio che canta la canzone del Kilimanjaro. Porta il contante con te — non ci sono bancomat sulla montagna.',
    'blogtip_s4_badge' => 'Pratico',
    'blogtip_s4_title' => 'Punti pratici',
    'blogtip_s4_i1_t' => 'Porta contanti.',
    'blogtip_s4_i1_d' => 'I dollari USA sono lo standard; anche gli scellini tanzaniani vanno bene. Non ci sono bancomat all\'interno dei parchi o sulla montagna.',
    'blogtip_s4_i2_t' => 'Le banconote devono essere emesse dopo il 2009.',
    'blogtip_s4_i2_d' => 'Le banconote USA più vecchie vengono rifiutate in tutta la Tanzania, anche per le mance.',
    'blogtip_s4_i3_t' => 'Porta tagli piccoli.',
    'blogtip_s4_i3_d' => 'Banconote da $1, $5 e $10 rendono pratico dividere le mance.',
    'blogtip_s4_i4_t' => 'Lascia la mancia alla fine,',
    'blogtip_s4_i4_d' => 'non ogni giorno, tranne per i trasferimenti singoli.',
    'blogtip_s4_i5_t' => 'Consegna le mance di persona',
    'blogtip_s4_i5_d' => 'quando puoi, oppure usa la cassa comune per lo staff del campo così da includere cucina e pulizie.',
    'blogtip_s4_i6_t' => 'Adatta in base al servizio.',
    'blogtip_s4_i6_d' => 'Queste sono linee guida. Una guida eccezionale merita di più; un servizio scadente merita di meno, e dovresti dire perché.',
    'blogtip_faq_badge' => 'FAQ',
    'blogtip_faq_title' => 'Mance — domande frequenti',
    'blogtip_faq_q1' => 'Quanto dovrei dare di mancia a una guida safari?',
    'blogtip_faq_a1' => 'Circa $20–25 al giorno dal gruppo nel suo insieme, non a persona. Per un safari di quattro giorni sono circa $80–100 in totale, indipendentemente da quante persone siete nel veicolo.',
    'blogtip_faq_q2' => 'Le mance sono obbligatorie in Tanzania?',
    'blogtip_faq_a2' => 'No, sono facoltative. Ma sono consuetudine e rappresentano una parte significativa di ciò che guadagnano guide, cuochi e staff del campo, e chi le riceve ci fa affidamento nel proprio bilancio.',
    'blogtip_faq_q3' => 'Quanto dovrei dare di mancia per una scalata del Kilimanjaro?',
    'blogtip_faq_a3' => 'Prevedi circa $800–1.000 in totale per due scalatori su un percorso di sette giorni con un equipaggio di circa undici persone — circa $400–500 a testa. Al giorno dal gruppo: $20–25 guida capo, $15–18 assistente, $12–15 cuoco, $8–10 per portatore.',
    'blogtip_faq_q4' => 'Perché le mance sul Kilimanjaro sono così alte?',
    'blogtip_faq_a4' => 'Perché l\'equipaggio è numeroso — tipicamente da tre a quattro persone per scalatore, che trasportano il tuo equipaggiamento, cibo e acqua in quota. Le mance sono una parte sostanziale e attesa del loro reddito, ed è per questo che ti comunichiamo la cifra prima che tu prenoti.',
    'blogtip_faq_q5' => 'In quale valuta dovrei dare la mancia?',
    'blogtip_faq_a5' => 'I dollari USA sono lo standard e anche gli scellini tanzaniani vanno bene. Le banconote devono essere emesse dopo il 2009 — le banconote USA più vecchie vengono rifiutate in tutto il paese. Porta tagli da $1, $5 e $10.',
    'blogtip_faq_q6' => 'Quando dovrei dare la mancia?',
    'blogtip_faq_a6' => 'Alla fine del safari o della scalata piuttosto che ogni giorno, tranne per i trasferimenti aeroportuali singoli. Sul Kilimanjaro c\'è di solito una cerimonia delle mance l\'ultima mattina.',
    'blogtip_faq_q7' => 'Dovrei dare la mancia a persona o per gruppo?',
    'blogtip_faq_a7' => 'Per gruppo. Le cifre indicative presuppongono che l\'intero veicolo o gruppo di scalata contribuisca insieme, motivo per cui un gruppo di quattro non paga quattro volte quanto paga una coppia.',
    'blogtip_faq_q8' => 'Do la mancia allo staff del campo separatamente?',
    'blogtip_faq_a8' => 'Sì, di solito in una cassa comune per le mance così che cucina, pulizie e servizio siano tutti inclusi — persone che magari non incontrerai mai ma che hanno fatto gran parte del lavoro.',
    'blogtip_faq_q9' => 'Posso dare la mancia con la carta?',
    'blogtip_faq_a9' => 'No. Porta contanti. Non ci sono bancomat all\'interno dei parchi nazionali o sul Kilimanjaro, e i POS dei lodge dipendono da una connessione spesso non disponibile.',
    'blogtip_faq_q10' => 'E se il servizio è stato scadente?',
    'blogtip_faq_a10' => 'Lascia meno mancia e dicci perché. Le linee guida sulle mance non sono obblighi, e un feedback onesto ci è davvero più utile di una mancia data per imbarazzo.',
    'blogtip_faq_q11' => 'Dovrei dare la mancia ai portatori singolarmente?',
    'blogtip_faq_a11' => 'Sul Kilimanjaro le mance vengono normalmente raccolte insieme e distribuite dalla guida capo durante la cerimonia, il che garantisce una divisione equa. Se vuoi dare qualcosa in più a un portatore specifico, fallo direttamente e in privato.',
    'blogtip_faq_q12' => 'Devo dare la mancia se il servizio è già incluso nel conto?',
    'blogtip_faq_a12' => 'Nei ristoranti dove il servizio compare sul conto, non è prevista una mancia aggiuntiva. Le mance per safari e scalate sono separate e non sono incluse nel prezzo del viaggio.',
    'blogtip_related_badge' => 'Continua a leggere',
    'blogtip_related_title' => 'Continua a esplorare la Tanzania',
    'blogtip_related_contact' => 'Facci una domanda',
    'blogtip_final_title' => 'Stai pianificando il budget del tuo viaggio?',
    'blogtip_final_intro' => 'Chiedici un preventivo dettagliato e includeremo una stima realistica delle mance per il tuo itinerario specifico e la dimensione del tuo gruppo, così non ci saranno sorprese.',
    'blogtip_final_whatsapp' => 'Scrivici su WhatsApp',
    'blogtip_final_contact' => 'Modulo di contatto',

    // ===== Blog article: Dove Alloggiare in Safari =====
    'blogstay_meta_title' => 'Dove Alloggiare in Safari in Tanzania: Lodge, Campo o Campeggio? | Serengeti Budget Safari',
    'blogstay_meta_description' => 'L\'alloggio safari in Tanzania spiegato: campeggi, lodge, tented camp e campi mobili confrontati con prezzi reali, e se dormire dentro o fuori dai parchi nazionali.',
    'blogstay_h1' => 'Dove alloggiare in safari',
    'blogstay_hero_sub' => 'Campeggio, lodge, tented camp o campo mobile — cosa costa davvero ognuno, com\'è realmente, e se dormire dentro il parco o fuori.',
