    'blogstay_s1_badge' => 'Le opzioni',
    'blogstay_s1_title' => 'I cinque tipi di alloggio safari',
    'blogstay_s1_p1' => 'Dove dormite è la singola variabile più grande nel costo di un safari — e, in un viaggio breve, in quanta fauna selvatica vedrete davvero. Gli animali sono gli stessi qualunque cosa scegliate; ciò che cambia è il comfort, e quanto siete lontani dall\'azione all\'alba.',
    'blogstay_t1_h1' => 'Tipo',
    'blogstay_t1_h2' => 'A persona / notte',
    'blogstay_t1_h3' => 'Cos\'è',
    'blogstay_t1_h4' => 'Ideale per',
    'blogstay_t1_r1_a' => 'Campeggio pubblico',
    'blogstay_t1_r1_b' => '$35,40 park fee<br>+ costi di campeggio',
    'blogstay_t1_r1_c' => 'La vostra tenda dentro il parco, servizi igienici condivisi, docce fredde, un cuoco che prepara i pasti sul posto.',
    'blogstay_t1_r1_d' => 'Viaggiatori budget, gruppi, gli avventurosi',
    'blogstay_t1_r2_a' => 'Lodge fuori dal parco',
    'blogstay_t1_r2_c' => 'Camere solide, acqua calda, ristorante, di solito una piscina. A Karatu o al confine di un parco.',
    'blogstay_t1_r2_d' => 'Contenere i costi',
    'blogstay_t1_r3_a' => 'Lodge dentro il parco',
    'blogstay_t1_r3_c' => 'Edificio permanente, elettricità, ristorante, spesso una piscina con vista su una pozza d\'acqua.',
    'blogstay_t1_r3_d' => 'Comfort più comodità',
    'blogstay_t1_r4_a' => 'Tented camp',
    'blogstay_t1_r4_c' => 'Tela permanente con letti veri e bagni privati. Sentite tutto di notte.',
    'blogstay_t1_r4_d' => 'L\'esperienza safari classica',
    'blogstay_t1_r5_a' => 'Campo mobile',
    'blogstay_t1_r5_c' => 'Si sposta due o tre volte l\'anno per seguire la migrazione. Piccolo, remoto, pochi altri veicoli nelle vicinanze.',
    'blogstay_t1_r5_d' => 'Viaggi incentrati sulla migrazione',
    'blogstay_s2_badge' => 'La decisione chiave',
    'blogstay_s2_title' => 'Dentro o fuori dal parco?',
    'blogstay_s2_p1' => 'Questa è la decisione che manda in confusione la maggior parte dei pianificatori alla prima esperienza, e conta più della classificazione a stelle del lodge.',
    'blogstay_s2_sub1' => 'Dormire dentro',
    'blogstay_s2_p2' => 'Pagate una <strong>tassa di concessione</strong> oltre alla tariffa della camera — $59,00 per adulto a notte nel Serengeti e a Ngorongoro, $47,20 nel Tarangire, Manyara, Arusha NP e Nyerere. In cambio siete già nel mezzo dell\'ecosistema quando la luce è migliore, all\'alba e al tramonto, che è esattamente quando i predatori sono attivi.',
    'blogstay_s2_sub2' => 'Dormire fuori',
    'blogstay_s2_p3' => 'Risparmiate la tassa di concessione e di solito una gran parte della tariffa della camera. Il costo è il tempo: il cancello più vicino può essere a 30-90 minuti, il che significa partire prima dell\'alba e tornare dopo il tramonto, perdendo le due ore migliori di ogni giorno per la guida.',
    'blogstay_t2_h1' => 'Dentro il parco',
    'blogstay_t2_h2' => 'Fuori dal parco',
    'blogstay_t2_r1_a' => 'Costo',
    'blogstay_t2_r1_b' => 'Più alto: camera + $47–59/notte concessione',
    'blogstay_t2_r1_c' => 'Più basso',
    'blogstay_t2_r2_a' => 'Game drive all\'alba',
    'blogstay_t2_r2_b' => 'Si inizia subito',
    'blogstay_t2_r2_c' => '30–90 min di guida prima',
    'blogstay_t2_r3_a' => 'Luce serale',
    'blogstay_t2_r3_b' => 'Uso completo',
    'blogstay_t2_r3_c' => 'Bisogna partire presto per raggiungere il cancello',
    'blogstay_t2_r4_a' => 'Suoni notturni',
    'blogstay_t2_r4_b' => 'Iena, leone, ippopotamo',
    'blogstay_t2_r4_c' => 'Di solito silenzioso',
    'blogstay_t2_r5_a' => 'Servizi',
    'blogstay_t2_r5_b' => 'Variano; spesso più semplici',
    'blogstay_t2_r5_c' => 'Spesso miglior rapporto qualità-comfort',
    'blogstay_tip_t' => 'Cosa consigliamo di solito:',
    'blogstay_tip_d' => 'in un viaggio di tre notti o meno, restate dentro il parco anche se significa una camera più semplice — le ore extra all\'alba valgono più del comfort extra. Su una settimana o più, mischiate: un paio di notti dentro nel momento chiave, notti più economiche fuori per il resto.',
    'blogstay_s3_badge' => 'La realtà',
    'blogstay_s3_title' => 'Com\'è realmente ogni tipo',
    'blogstay_s3_sub1' => 'Campeggio',
    'blogstay_s3_p1' => 'Una tenda a cupola per due persone in un campeggio pubblico, un blocco servizi condiviso con acqua fredda, e un cuoco che prepara cibo genuinamente buono sul fuoco. Sentirete le iene di notte — e occasionalmente i leoni. I bufali attraversano alcuni campeggi. Vi viene data una torcia e vi si dice di non lasciare la tenda dopo il tramonto, e quell\'istruzione non è decorativa.',
    'blogstay_s3_p2' => 'È essenziale, non è per tutti, e le persone che lo scelgono di solito lo descrivono come la parte migliore del viaggio.',
    'blogstay_s3_sub2' => 'Tented camp',
    'blogstay_s3_p3' => 'La parola "tenda" è fuorviante. Sono strutture permanenti in tela su piattaforme, con letti veri, bagni privati e acqua calda portata all\'alba. Ciò che le rende speciali è la tela: sentite tutto, e di notte un askari vi accompagna alla vostra tenda perché gli animali si muovono nel campo.',
    'blogstay_s3_sub3' => 'Lodge',
    'blogstay_s3_p4' => 'Un hotel in un parco nazionale. Pareti solide, elettricità, un ristorante, di solito una piscina. Comodo e affidabile, e considerevolmente meno suggestivo della tela. I migliori sono costruiti su scarpate o sopra pozze d\'acqua e la vista fa il resto.',
    'blogstay_s3_sub4' => 'Campo mobile',
    'blogstay_s3_p5' => 'Piccolo, di solito da sei a dodici tende, spostato stagionalmente per seguire le mandrie. Energia solare, docce a secchio, niente piscina, niente Wi-Fi. Remoto e silenzioso, e se la migrazione è il motivo per cui siete venuti, questo vi porta più vicini.',
    'blogstay_s4_badge' => 'Scegliere',
    'blogstay_s4_title' => 'Come scegliere per il vostro viaggio',
    'blogstay_t3_h1' => 'Se…',
    'blogstay_t3_h2' => 'Scegliete',
    'blogstay_t3_h3' => 'Perché',
    'blogstay_t3_r1_a' => 'Avete solo 2–3 notti',
    'blogstay_t3_r1_b' => 'Dentro il parco',
    'blogstay_t3_r1_c' => 'Alba e tramonto valgono più del comfort',
    'blogstay_t3_r2_a' => 'Avete una settimana o più',
    'blogstay_t3_r2_b' => 'Mischiate dentro e fuori',
    'blogstay_t3_r2_c' => 'Risparmiate sulle notti ordinarie, spendete su quelle chiave',
    'blogstay_t3_r3_a' => 'Avete un budget limitato',
    'blogstay_t3_r3_b' => 'Campeggio o lodge fuori',
    'blogstay_t3_r3_c' => 'Stessa guida, stessi animali, costo molto più basso',
    'blogstay_t3_r4_a' => 'State seguendo la migrazione',
    'blogstay_t3_r4_b' => 'Campo mobile',
    'blogstay_t3_r4_c' => 'Si muove con le mandrie',
    'blogstay_t3_r5_a' => 'Viaggiate con bambini',
    'blogstay_t3_r5_b' => 'Lodge con piscina',
    'blogstay_t3_r5_c' => 'Un posto per sfogare energia nelle ore calde',
    'blogstay_t3_r6_a' => 'Volete l\'esperienza classica',
    'blogstay_t3_r6_b' => 'Tented camp',
    'blogstay_t3_r6_c' => 'Tela, suoni notturni, un askari che vi riaccompagna',
    'blogstay_t3_r7_a' => 'Siete in luna di miele',
    'blogstay_t3_r7_b' => 'Piccolo tented camp',
    'blogstay_t3_r7_c' => 'Privato, silenzioso, e molto meglio di un grande lodge',
    'blogstay_s4_sub1' => 'Domande da fare prima di prenotare',
    'blogstay_ask1' => 'La tassa di concessione è inclusa nella tariffa quotata, o aggiunta?',
    'blogstay_ask2' => 'Quanto dista dal cancello, e quanto dura la guida fino all\'area principale della fauna?',
    'blogstay_ask3' => 'C\'è elettricità tutta la notte, o solo ore di generatore?',
    'blogstay_ask4' => 'Le bevande sono incluse, e quali?',
    'blogstay_ask5' => 'C\'è un\'età minima per i bambini?',
    'blogstay_ask6' => 'Il Wi-Fi è disponibile, e dove?',
    'blogstay_faq_badge' => 'FAQ',
    'blogstay_faq_title' => 'Alloggio safari — domande frequenti',
    'blogstay_faq_q1' => 'Dovrei stare dentro o fuori dal parco nazionale?',
    'blogstay_faq_a1' => 'Su un viaggio di tre notti o meno, dentro — siete già nell\'ecosistema all\'alba e al tramonto quando i predatori sono attivi. Su un viaggio più lungo, mischiate: notti più economiche fuori, notti chiave dentro. Dormire dentro aggiunge una tassa di concessione di $47–59 per adulto a notte.',
    'blogstay_faq_q2' => 'Cos\'è una tassa di concessione?',
    'blogstay_faq_a2' => 'Un addebito per persona, per notte, imposto dall\'autorità del parco quando dormite in un lodge o campo dentro un parco nazionale. È $59,00 per adulto nel Serengeti e a Ngorongoro e $47,20 nel Tarangire, Manyara, Arusha NP e Nyerere, oltre alla tariffa della camera.',
    'blogstay_faq_q3' => 'Il campeggio in safari è sicuro?',
    'blogstay_faq_a3' => 'Sì, nei campeggi pubblici designati, con le normali precauzioni: restare nella tenda dopo il tramonto, tenere il cibo sigillato e lontano dalla tenda, e seguire le istruzioni della guida. Gli animali attraversano davvero i campeggi, ed è esattamente per questo che esistono quelle regole.',
    'blogstay_faq_q4' => 'Qual è la differenza tra un lodge e un tented camp?',
    'blogstay_faq_a4' => 'Un lodge è un edificio permanente con pareti solide ed elettricità. Un tented camp è tela permanente su una piattaforma con letti veri e bagni privati. La tela è il punto — sentite tutto di notte, il che per la maggior parte delle persone è il ricordo che resta.',
    'blogstay_faq_q5' => 'Cos\'è un campo mobile?',
    'blogstay_faq_a5' => 'Un piccolo campo, di solito da sei a dodici tende, che si sposta fisicamente due o tre volte l\'anno per seguire la migrazione. Energia solare, docce a secchio, niente piscina. Se la migrazione è il motivo del vostro viaggio, questo vi porta più vicini.',
    'blogstay_faq_q6' => 'Quanto costa l\'alloggio safari a notte?',
    'blogstay_faq_a6' => 'I campeggi pubblici costano $35,40 di park fee più i costi di campeggio; i lodge fuori dai parchi $60–150; i lodge dentro $150–400; i tented camp $200–600; i campi mobili $300–700. L\'ultra-lusso parte da $700 in su.',
    'blogstay_faq_q7' => 'Devo prenotare l\'alloggio in anticipo?',
    'blogstay_faq_a7' => 'Sì, in particolare da giugno a ottobre e per Ndutu a febbraio. I campi nel Serengeti settentrionale e a Ndutu si esauriscono da sei a dodici mesi prima perché il numero di posti letto in quelle aree è limitato.',
    'blogstay_faq_q8' => 'C\'è elettricità e Wi-Fi?',
    'blogstay_faq_a8' => 'I lodge di solito hanno entrambi. I tented camp spesso usano generatori per ore stabilite e forniscono illuminazione solare il resto del tempo. I campi mobili tipicamente hanno energia solare e nessun Wi-Fi. Chiedete prima di prenotare se per voi è importante.',
    'blogstay_faq_q9' => 'I pasti sono inclusi?',
    'blogstay_faq_a9' => 'Quasi sempre in safari — la pensione completa è standard, e i pranzi al sacco sono forniti nei game drive di giornata intera. Le bevande diverse dall\'acqua e dal tè sono di solito a pagamento separato tranne che nella fascia di lusso, dove sono spesso incluse.',
    'blogstay_faq_q10' => 'Posso stare in un lodge con bambini?',
    'blogstay_faq_a10' => 'La maggior parte dei lodge accetta bambini di qualsiasi età. Alcuni tented camp fissano un minimo di sei o dodici anni, a causa del percorso a piedi tra le tende di notte. Diteci le età quando chiedete informazioni e filtreremo di conseguenza.',
    'blogstay_faq_q11' => 'Cosa succede di notte in un tented camp?',
    'blogstay_faq_a11' => 'Un askari — una guardia notturna — vi accompagna tra l\'area ristorante e la vostra tenda, perché gli animali si muovono nel campo dopo il tramonto. Sentirete ippopotami, iene e spesso leoni. La tenda si chiude con la cerniera ed è completamente sicura.',
    'blogstay_faq_q12' => 'Vale la pena pagare per una piscina?',
    'blogstay_faq_a12' => 'Con bambini, davvero sì — le ore calde tra i game drive sono lunghe e una piscina le risolve. Senza bambini conta molto meno, e i soldi sono di solito meglio spesi sulla posizione.',
    'blogstay_faq_q13' => 'Qual è l\'opzione con il miglior rapporto qualità-prezzo?',
    'blogstay_faq_a13' => 'Un lodge appena fuori dal confine di un parco, a $60–150 a persona. Evitate la tassa di concessione e ottenete servizi migliori per il prezzo — al costo di 30-90 minuti di guida ogni mattina e sera.',
    'blogstay_related_badge' => 'Continua a leggere',
    'blogstay_related_title' => 'Continua a esplorare la Tanzania',
    'blogstay_final_title' => 'Non sei sicuro di cosa scegliere?',
    'blogstay_final_intro' => 'Dicci il tuo budget e quante notti hai. Ti suggeriremo un mix di notti dentro e fuori che ti dà la massima fauna selvatica per il tuo budget.',
    'blogstay_final_whatsapp' => 'Scrivici su WhatsApp',
    'blogstay_final_contact' => 'Modulo di contatto',

    // ===== Blog article: I Big Five in Tanzania =====
    'blogbig5_meta_title' => 'I Big Five in Tanzania: Dove e Quando Vederli | Serengeti Budget Safari',
    'blogbig5_meta_description' => 'Dove vedere leone, leopardo, elefante, bufalo e rinoceronte nero in Tanzania, con probabilità di avvistamento oneste per ognuno, gli itinerari che danno le migliori possibilità, e perché il rinoceronte è il più difficile.',
    'blogbig5_h1' => 'I Big Five in Tanzania',
    'blogbig5_hero_sub' => 'Dove vive ognuno, quali sono le vostre probabilità realistiche, e come pianificare un itinerario che vi dia una vera possibilità di vederli tutti e cinque.',
    'blogbig5_updated' => 'Aggiornato 2026',
    'blogbig5_quick_badge' => 'Risposte rapide',
    'blogbig5_quick_title' => 'I Big Five in breve',
    'blogbig5_quick_intro' => 'Probabilità oneste, prima del dettaglio.',
    'blogbig5_qq1_q' => 'Quali sono facili?',
    'blogbig5_qq1_a' => 'Leone, elefante e bufalo — quasi certi.',
    'blogbig5_qq2_q' => 'Leopardo?',
    'blogbig5_qq2_a' => '55–60% nella valle di Seronera in tre giorni.',
    'blogbig5_qq3_q' => 'Rinoceronte nero?',
    'blogbig5_qq3_a' => '~60% in una giornata intera nel Cratere di Ngorongoro. Da nessun\'altra parte.',
    'blogbig5_qq4_q' => 'Quanti giorni?',
    'blogbig5_qq4_a' => 'Quattro-cinque per una possibilità realistica di tutti e cinque.',
    'blogbig5_qq5_q' => 'Cosa dovrei portare?',
    'blogbig5_qq5_a' => 'Il binocolo conta più di un teleobiettivo per il rinoceronte.',
    'blogbig5_qq6_q' => 'Garantiti?',
    'blogbig5_qq6_a' => 'Mai. Chiunque prometta tutti e cinque sta esagerando.',
    'blogbig5_toc_title' => 'Indice – I Big Five in Tanzania',
    'blogbig5_toc_1' => 'Cosa sono',
    'blogbig5_toc_2' => 'Dove vedere ognuno',
    'blogbig5_toc_3' => 'Migliori itinerari',
    'blogbig5_toc_4' => 'Oltre i Big Five',
    'blogbig5_toc_5' => 'FAQ',
    'blogbig5_s1_badge' => 'Le basi',
    'blogbig5_s1_title' => 'Cosa sono i Big Five — e perché',
    'blogbig5_s1_p1' => 'Leone, leopardo, elefante, bufalo e rinoceronte nero. Il termine non ha nulla a che fare con la dimensione — sia l\'ippopotamo che la giraffa sono più grandi di un leopardo. Deriva dalla caccia grossa dell\'era coloniale, e si riferiva ai <strong>cinque animali considerati più pericolosi da cacciare a piedi</strong>.',
    'blogbig5_s1_p2' => 'Il nome ha superato la sua origine ed è ora la checklist standard di un safari, il che è leggermente assurdo ma genuinamente utile: insieme i cinque coprono la maggior parte degli habitat e comportamenti che vale la pena viaggiare per vedere.',
    'blogbig5_s1_p3' => 'La posizione onesta sul completare l\'elenco: quattro dei cinque sono semplici in un safari ben pianificato nel circuito settentrionale. Il <strong>rinoceronte nero è la difficoltà</strong>, e tutto ciò che segue riguarda davvero come risolvere quel problema.',
    'blogbig5_fact_lion_label' => 'Leone',
    'blogbig5_fact_lion_value' => 'Facile — Serengeti, Ngorongoro',
    'blogbig5_fact_elephant_label' => 'Elefante',
    'blogbig5_fact_elephant_value' => 'Facile — Tarangire, Ruaha',
    'blogbig5_fact_buffalo_label' => 'Bufalo',
    'blogbig5_fact_buffalo_value' => 'Facile — ovunque',
    'blogbig5_fact_leopard_label' => 'Leopardo',
    'blogbig5_fact_leopard_value' => 'Moderato — Serengeti',
    'blogbig5_fact_rhino_label' => 'Rinoceronte nero',
    'blogbig5_fact_rhino_value' => 'Difficile — solo Ngorongoro',
    'blogbig5_fact_days_label' => 'Giorni per tutti e cinque',
    'blogbig5_fact_days_value' => '4–5 realisticamente',
    'blogbig5_s2_badge' => 'I cinque',
    'blogbig5_s2_title' => 'Dove vedere ognuno',
    'blogbig5_s2_lion_h' => 'Leone',
    'blogbig5_s2_lion_p' => 'Il più facile. Il <strong>Serengeti</strong> ne ospita circa 3.000 e ha una delle densità più alte in Africa; il <strong>Cratere di Ngorongoro</strong> ne ha circa 60 in 260 km², quindi sono quasi inevitabili. <strong>Ruaha</strong> a sud ha branchi di venti o più che cacciano bufali e persino elefanti giovani.',
    'blogbig5_s2_lion_odds' => 'Migliori probabilità: 90–95% su un safari di tre giorni nel circuito settentrionale.',
    'blogbig5_s2_elephant_h' => 'Elefante',
    'blogbig5_s2_elephant_p' => 'Il <strong>Tarangire</strong> nella stagione secca è il migliore nel circuito settentrionale — 2.500-3.000 animali residenti, con mandrie di cinquanta o più lungo il fiume. Il <strong>Ruaha</strong> ne ha circa 12.000, la popolazione più grande dell\'Africa orientale.',
    'blogbig5_s2_elephant_odds' => 'Migliori probabilità: 95%+ nel Tarangire da luglio a ottobre.',
    'blogbig5_s2_buffalo_h' => 'Bufalo',
    'blogbig5_s2_buffalo_p' => 'Comune ovunque, di solito in grandi mandrie. Sia il Cratere di Ngorongoro che il Serengeti ne ospitano migliaia. I vecchi tori solitari, chiamati dagga boys, sono quelli da trattare con rispetto.',
    'blogbig5_s2_buffalo_odds' => 'Migliori probabilità: 90%+ ovunque.',
    'blogbig5_s2_leopard_h' => 'Leopardo',
    'blogbig5_s2_leopard_p' => 'Il più elusivo, ma tutt\'altro che impossibile. La <strong>valle di Seronera</strong> nel Serengeti centrale è il singolo posto migliore in Tanzania — i leopardi riposano sulle acacie lungo il fiume durante il caldo del giorno. Anche <strong>Ndutu</strong> è eccellente.',
    'blogbig5_s2_leopard_odds' => 'Migliori probabilità: 55–60% in tre giorni nel Serengeti centrale.',
    'blogbig5_s2_rhino_h' => 'Rinoceronte nero',
    'blogbig5_s2_rhino_p1' => 'Il più difficile. La popolazione della Tanzania è piccola e sparsa, e c\'è un solo posto dove avete una vera possibilità: il <strong>Cratere di Ngorongoro</strong>, dove circa 30 vivono sotto protezione armata 24 ore su 24. Un piccolo numero sopravvive intorno ai Moru Kopjes nel Serengeti, ma gli avvistamenti lì sono rari.',
    'blogbig5_s2_rhino_p2' => 'Aspettatevi di vederli a distanza attraverso l\'erba aperta piuttosto che vicino al veicolo. Un buon binocolo conta più di un teleobiettivo qui, e la mattina presto è quando è più probabile che siano allo scoperto.',
    'blogbig5_s2_rhino_odds' => 'Migliori probabilità: circa 60% in una giornata intera nel cratere.',
    'blogbig5_s3_badge' => 'Pianificazione',
    'blogbig5_s3_title' => 'Itinerari che vi danno le migliori possibilità',
    'blogbig5_t1_h1' => 'Viaggio',
    'blogbig5_t1_h2' => 'Parchi',
    'blogbig5_t1_h3' => 'Risultato realistico',
    'blogbig5_t1_r1_a' => '2 giorni',
    'blogbig5_t1_r1_b' => 'Tarangire + Ngorongoro',
    'blogbig5_t1_r1_c' => 'Leone, elefante, bufalo quasi certi; rinoceronte probabile; leopardo improbabile. <strong>3–4 su 5.</strong>',
    'blogbig5_t1_r2_a' => '4 giorni',
    'blogbig5_t1_r2_b' => 'Tarangire, Serengeti, Ngorongoro',
    'blogbig5_t1_r2_c' => 'Tutte e quattro le specie facili, più una vera possibilità sia per leopardo che rinoceronte. <strong>4–5 su 5.</strong>',
    'blogbig5_t1_r3_a' => '6 giorni',
    'blogbig5_t1_r3_b' => 'Circuito settentrionale completo',
    'blogbig5_t1_r3_c' => 'Tempo per lavorare la valle di Seronera per il leopardo e una giornata intera nel cratere per il rinoceronte. <strong>Migliore possibilità di tutti e cinque.</strong>',
    'blogbig5_s3_warn_t' => 'Nessuno può garantire i Big Five.',
    'blogbig5_s3_warn_d' => 'Questi sono animali selvatici in aree enormi. Ciò che un buon operatore può fare è mettervi nei posti giusti nei momenti giusti della giornata ed essere onesto sulle probabilità — che è ciò che sono i numeri sopra.',
    'blogbig5_s4_badge' => 'Oltre i cinque',
    'blogbig5_s4_title' => 'Gli animali che valgono più della checklist',
    'blogbig5_s4_intro' => 'Chiedete a una guida cosa preferirebbe mostrarvi, e i Big Five raramente sono in cima alla lista.',
    'blogbig5_s4_i1_t' => 'Ghepardo',
    'blogbig5_s4_i1_d' => 'l\'animale terrestre più veloce, che caccia nelle pianure meridionali aperte. Una caccia del ghepardo è uno spettacolo migliore della maggior parte degli avvistamenti di leoni.',
    'blogbig5_s4_i2_t' => 'Licaone africano',
    'blogbig5_s4_i2_d' => 'meno di 7.000 rimasti nel mondo. Nyerere e Ruaha sono due degli ultimi baluardi, e un branco a caccia è straordinario.',
    'blogbig5_s4_i3_t' => 'La Grande Migrazione',
    'blogbig5_s4_i3_d' => '1,3 milioni di gnu. Nessun singolo animale compete.',
    'blogbig5_s4_i4_t' => 'Giraffa',
    'blogbig5_s4_i4_d' => 'l\'animale nazionale della Tanzania, e in qualche modo sempre più impressionante di persona di quanto ci si aspetti.',
    'blogbig5_s4_i5_t' => 'Ippopotamo',
    'blogbig5_s4_i5_d' => 'statisticamente l\'animale grande più pericoloso d\'Africa, e molto più divertente di quanto suggerisca la lista dei Big Five.',
    'blogbig5_s4_i6_t' => 'Serval, caracal, tasso del miele, oritteropo — gli avvistamenti per cui le guide si emozionano davvero.',
    'blogbig5_s4_outro' => 'Il nostro consiglio: usate i Big Five per definire l\'itinerario, poi dimenticate la checklist una volta sul posto. Le migliori mattine di safari non sono quasi mai quelle passate a spuntare caselle.',
    'blogbig5_tag_lion' => 'Leone',
    'blogbig5_tag_leopard' => 'Leopardo',
    'blogbig5_tag_elephant' => 'Elefante',
    'blogbig5_tag_buffalo' => 'Bufalo',
    'blogbig5_tag_rhino' => 'Rinoceronte nero',
    'blogbig5_tag_cheetah' => 'Ghepardo',
    'blogbig5_tag_wilddog' => 'Licaone',
    'blogbig5_tag_giraffe' => 'Giraffa',
    'blogbig5_tag_hippo' => 'Ippopotamo',
    'blogbig5_faq_title' => 'I Big Five — domande frequenti',
    'blogbig5_faq_q1' => 'Cosa sono i Big Five?',
    'blogbig5_faq_a1' => 'Leone, leopardo, elefante, bufalo e rinoceronte nero. Il termine deriva dalla caccia grossa coloniale e si riferiva ai cinque animali considerati più pericolosi da cacciare a piedi — non i più grandi.',
    'blogbig5_faq_q2' => 'Posso vedere i Big Five in Tanzania?',
    'blogbig5_faq_a2' => 'Sì, e un safari di quattro-cinque giorni nel circuito settentrionale dà una possibilità realistica di tutti e cinque. Leone, elefante e bufalo sono quasi certi, il leopardo è circa 55–60% nel Serengeti, e il rinoceronte circa 60% in una giornata intera nel Cratere di Ngorongoro.',
    'blogbig5_faq_q3' => 'Qual è il posto migliore per vedere il rinoceronte nero?',
    'blogbig5_faq_a3' => 'Il Cratere di Ngorongoro, dove circa 30 vivono sotto protezione armata 24 ore su 24. È l\'unica opzione realistica in Tanzania. Aspettatevi avvistamenti a distanza attraverso l\'erba aperta — portate il binocolo.',
    'blogbig5_faq_q4' => 'Qual è il posto migliore per vedere il leopardo?',
    'blogbig5_faq_a4' => 'La valle di Seronera nel Serengeti centrale. I leopardi riposano sulle acacie lungo il fiume durante il caldo del giorno, il che li rende individuabili se sapete dove guardare. Anche Ndutu è eccellente.',
    'blogbig5_faq_q5' => 'Quale parco ha più elefanti?',
    'blogbig5_faq_a5' => 'Il Ruaha con circa 12.000, la popolazione più grande dell\'Africa orientale. Nel circuito settentrionale, il Tarangire è il migliore — 2.500-3.000 animali residenti e mandrie nella stagione secca di cinquanta o più.',
    'blogbig5_faq_q6' => 'Quanti giorni servono per vedere i Big Five?',
    'blogbig5_faq_a6' => 'Quattro-cinque realisticamente. Due giorni ne coprono tre o quattro. Sei giorni danno la migliore possibilità, perché avete tempo per lavorare la valle di Seronera per il leopardo e una giornata intera nel cratere per il rinoceronte.',
    'blogbig5_faq_q7' => 'Posso vedere i Big Five solo nel Serengeti?',
    'blogbig5_faq_a7' => 'Quattro di essi, facilmente. Il rinoceronte nero è l\'eccezione — un piccolo numero sopravvive vicino ai Moru Kopjes ma gli avvistamenti sono rari. Per completare l\'elenco, aggiungete il Cratere di Ngorongoro.',
    'blogbig5_faq_q8' => 'I Big Five sono garantiti?',
    'blogbig5_faq_a8' => 'No, e diffidate di chiunque dica il contrario. Questi sono animali selvatici in aree di migliaia di chilometri quadrati. Un buon operatore migliora le vostre probabilità essendo nel posto giusto al momento giusto, ed è onesto su quali siano quelle probabilità.',
    'blogbig5_faq_q9' => 'Perché il rinoceronte nero è così raro?',
    'blogbig5_faq_a9' => 'Il bracconaggio. La popolazione di rinoceronte nero della Tanzania è scesa da migliaia negli anni \'70 a poche decine negli anni \'90. I numeri si stanno lentamente riprendendo sotto protezione intensiva, ma restano in pericolo critico.',
    'blogbig5_faq_q10' => 'Qual è la differenza tra rinoceronte nero e bianco?',
    'blogbig5_faq_a10' => 'Principalmente la forma della bocca. Il rinoceronte nero ha un labbro ricurvo per brucare gli arbusti; il rinoceronte bianco ha un labbro largo e piatto per pascolare l\'erba. La Tanzania ha il rinoceronte nero; il rinoceronte bianco si trova principalmente nell\'Africa meridionale.',
    'blogbig5_faq_q11' => 'Cosa è meglio dei Big Five?',
    'blogbig5_faq_a11' => 'Chiedete a una guida e la maggior parte dirà una caccia del ghepardo, un branco di licaoni, o la migrazione stessa. I Big Five sono un utile schema di pianificazione e una scarsa descrizione di ciò che rende memorabile un safari.',
    'blogbig5_faq_q12' => 'Dove posso vedere il ghepardo?',
    'blogbig5_faq_a12' => 'Le pianure meridionali aperte del Serengeti, in particolare intorno a Ndutu durante la stagione dei parti. I ghepardi hanno bisogno di terreno aperto per correre ed evitano aree con alta densità di leoni, poiché i leoni li uccidono.',
    'blogbig5_faq_q13' => 'I bufali sono davvero pericolosi?',
    'blogbig5_faq_a13' => 'Sì. I vecchi tori solitari — dagga boys — sono responsabili di più attacchi alle persone rispetto alla maggior parte degli altri animali africani. Da un veicolo siete completamente al sicuro; a piedi, sono il motivo per cui i safari a piedi hanno un ranger armato.',
    'blogbig5_faq_q14' => 'Serve un teleobiettivo per i Big Five?',
    'blogbig5_faq_a14' => 'Un obiettivo da 300 mm o più lungo aiuta considerevolmente, in particolare per rinoceronte e leopardo. Ma il binocolo conta più di quanto la maggior parte delle persone si aspetti — molti avvistamenti, specialmente il rinoceronte nel cratere, sono troppo distanti per qualsiasi obiettivo realistico.',
    'blogbig5_related_title' => 'Continua a esplorare la Tanzania',
    'blogbig5_related_ngorongoro' => 'Ngorongoro — per il rinoceronte',
    'blogbig5_final_title' => 'Pianifica un itinerario Big Five',
    'blogbig5_final_intro' => 'Dicci quanti giorni hai e costruiremo il percorso che ti dà la migliore possibilità reale — e ti diremo chiaramente se il tuo programma rende improbabili tutti e cinque.',

    // ===== Blog article: Kenya vs Tanzania Safari =====
    'blogkenya_meta_title' => 'Safari in Kenya o Tanzania: Un Confronto Onesto (2026)',
    'blogkenya_meta_description' => 'Kenya o Tanzania per il safari? Un confronto onesto tra Serengeti e Masai Mara, mesi della migrazione, park fee, densità di veicoli, regole fuoristrada e quale paese si adatta a quale tipo di viaggio.',
    'blogkenya_updated' => 'Aggiornato 2026',
    'blogkenya_h1' => 'Safari in Kenya o Tanzania',
    'blogkenya_hero_sub' => 'Lo stesso ecosistema, diviso da un confine — cosa fa davvero meglio ogni paese, scritto da un operatore tanzaniano che cerca di essere onesto al riguardo.',
