    'blogkenya_s1_badge' => 'In breve',
    'blogkenya_s1_title' => 'La risposta breve',
    'blogkenya_s1_p1' => 'Condividono lo stesso ecosistema e la stessa migrazione, divisi da un confine. In generale:',
    'blogkenya_s1_li1_t' => 'Tanzania',
    'blogkenya_s1_li1_d' => 'per scala, varietà e la stagione dei parti. Ha anche il Kilimanjaro, Zanzibar e il Cratere di Ngorongoro.',
    'blogkenya_s1_li2_t' => 'Kenya',
    'blogkenya_s1_li2_d' => 'per comodità e costo più basso. Gli avvistamenti arrivano più velocemente in un\'area più piccola, ed è generalmente più economico.',
    'blogkenya_s1_p2' => 'Nessuno dei due è oggettivamente migliore. Ciò che segue è il dettaglio onesto — scritto, dobbiamo dirlo chiaramente, da un operatore tanzaniano. Abbiamo cercato di essere equi.',
    'blogkenya_s2_badge' => 'Confronto',
