    'blogkenya_t1_r9_a' => 'Rinoceronte nero',
    'blogkenya_t1_r9_b' => 'Ngorongoro (~60%)',
    'blogkenya_t1_r9_c' => 'Diverse opzioni affidabili',
    'blogkenya_t1_r10_a' => 'Montagna più alta',
    'blogkenya_t1_r11_a' => 'Spiaggia',
    'blogkenya_t1_r12_a' => 'Spostamenti',
