    'blogkenya_t1_r12_c' => 'Guide più brevi',
    'blogkenya_s3_badge' => 'Migrazione',
    'blogkenya_s3_title' => 'La migrazione: chi ne ha di più?',
    'blogkenya_s3_p1' => 'Questa è la domanda che la maggior parte delle persone si sta davvero ponendo, e la risposta è più chiara di quanto suggerisca il marketing di entrambe le parti.',
    'blogkenya_s3_p2' => 'Le mandrie trascorrono circa <strong>nove-dieci mesi l\'anno in Tanzania</strong> e due-tre mesi nel Masai Mara del Kenya. I famosi attraversamenti del fiume Mara avvengono al confine, e possono essere osservati da entrambi i lati tra luglio e ottobre.',
    'blogkenya_s3_p3' => '<strong>Ciò che la Tanzania ha e il Kenya no:</strong> la stagione dei parti. Circa 400.000 gnu nascono a Ndutu tra fine gennaio e febbraio, e questo non accade da nessun\'altra parte.',
    'blogkenya_s3_p4' => '<strong>Ciò che il Kenya ha e la Tanzania no:</strong> la compattezza. Il Mara è un decimo delle dimensioni del Serengeti, quindi quando le mandrie sono lì, sono concentrate e facili da raggiungere.',
    'blogkenya_s4_badge' => 'Esperienza',
    'blogkenya_s4_title' => 'Come si sente davvero l\'esperienza',
    'blogkenya_s4_sub1' => 'Tanzania',
    'blogkenya_s4_p1' => 'Più grande, più vuota, e più lenta. Le guide tra i parchi sono lunghe — da Arusha al Serengeti sono sette-otto ore — e i paesaggi cambiano drammaticamente mentre si procede. La guida fuoristrada è proibita, quindi si resta sulle piste e gli avvistamenti avvengono a distanza rispettosa. Nei parchi meno visitati si può passare una mattinata senza vedere un altro veicolo.',
    'blogkenya_s4_sub2' => 'Kenya',
    'blogkenya_s4_p2' => 'Più compatto e con un ritmo più veloce. Le guide sono più brevi, gli avvistamenti arrivano più rapidamente, e nelle conservancy private al confine col Mara, guida fuoristrada, game drive notturni e camminate sono tutti permessi — cosa che i parchi nazionali della Tanzania non consentono. Il compromesso è la densità di veicoli: un buon avvistamento nel Mara ad agosto può attrarre una folla.',
    'blogkenya_s4_note_t' => 'Il riassunto onesto:',
    'blogkenya_s4_note_d' => 'se volete la massima varietà e la sensazione di spazio enorme, la Tanzania. Se volete la massima fauna selvatica al giorno e per dollaro speso in un viaggio più breve, il Kenya. Molti viaggiatori esperti alla fine fanno entrambi.',
    'blogkenya_s5_badge' => 'Scegliere',
    'blogkenya_s5_title' => 'Quale dovreste scegliere?',
    'blogkenya_t2_h1' => 'Se…',
    'blogkenya_t2_h2' => 'Scegliete',
    'blogkenya_t2_r1_a' => 'Volete la stagione dei parti',
    'blogkenya_t2_r2_a' => 'Volete scalare il Kilimanjaro',
    'blogkenya_t2_r3_a' => 'Volete una spiaggia dopo',
    'blogkenya_t2_r4_a' => 'Volete il Cratere di Ngorongoro',
    'blogkenya_t2_r5_a' => 'Avete 10+ giorni',
    'blogkenya_t2_r6_a' => 'Avete 5 giorni o meno',
    'blogkenya_t2_r7_a' => 'Avete un budget più limitato',
    'blogkenya_t2_r8_a' => 'Volete game drive notturni e fuoristrada',
    'blogkenya_conservancies' => 'conservancy',
    'blogkenya_t2_r9_a' => 'Volete gli attraversamenti dei fiumi lug–ott',
    'blogkenya_either' => 'Entrambi',
    'blogkenya_t2_r10_a' => 'Volete il minor numero di altri veicoli',
    'blogkenya_southern_circuit' => '(circuito meridionale)',
    'blogkenya_s5_sub1' => 'Posso fare entrambi?',
    'blogkenya_s5_p1' => 'Sì. Il Serengeti e il Masai Mara sono adiacenti, e gli itinerari combinati sono comuni — di solito volando tra i due, poiché il valico di frontiera terrestre a Isebania è lento. Nota che il <strong>Visto Turistico dell\'Africa Orientale non copre la Tanzania</strong>: servono visti separati per ogni paese. Preventivate 10-14 giorni per fare entrambi correttamente.',
    'blogkenya_faq_badge' => 'FAQ',
    'blogkenya_faq_title' => 'Kenya contro Tanzania — domande frequenti',
    'blogkenya_faq_q1' => 'La Tanzania o il Kenya è migliore per il safari?',
    'blogkenya_faq_a1' => 'Nessuno dei due è oggettivamente migliore. La Tanzania offre maggiore scala e varietà, la stagione dei parti, il Kilimanjaro, Ngorongoro e Zanzibar. Il Kenya è più compatto, generalmente più economico, e migliore per viaggi brevi.',
    'blogkenya_faq_q2' => 'Dove si trova la Grande Migrazione — Tanzania o Kenya?',
    'blogkenya_faq_a2' => 'Entrambi, ma le mandrie trascorrono circa nove-dieci mesi l\'anno in Tanzania e solo due-tre nel Masai Mara del Kenya. I famosi attraversamenti del fiume avvengono al confine tra luglio e ottobre.',
    'blogkenya_faq_q3' => 'Quale è più economico, Kenya o Tanzania?',
    'blogkenya_faq_a3' => 'Il Kenya, generalmente. Le park fee tanzaniane sono più alte — $82,60 al giorno nel Serengeti — e le distanze sono maggiori, il che significa più carburante e più giorni. La compattezza del Kenya riduce il costo totale del viaggio.',
    'blogkenya_faq_q4' => 'Il Serengeti è migliore del Masai Mara?',
    'blogkenya_faq_a4' => 'Sono lo stesso ecosistema diviso da un confine. Il Serengeti è circa dieci volte più grande con habitat più vari e minore densità di veicoli; il Mara è compatto quindi gli avvistamenti arrivano più velocemente, ma con più affollamento in alta stagione.',
    'blogkenya_faq_q5' => 'Posso vedere la stagione dei parti in Kenya?',
    'blogkenya_faq_a5' => 'No. I parti avvengono sulle pianure meridionali a erba corta a Ndutu, in Tanzania, tra fine gennaio e febbraio. È una delle ragioni più chiare per scegliere la Tanzania.',
    'blogkenya_faq_q6' => 'Posso visitare entrambi i paesi in un solo viaggio?',
    'blogkenya_faq_a6' => 'Sì, e gli itinerari combinati sono comuni — di solito volando tra il Serengeti e il Mara, poiché il valico di frontiera terrestre è lento. Preventivate 10-14 giorni, e notate che servono visti separati per ogni paese.',
    'blogkenya_faq_q7' => 'Il Visto Turistico dell\'Africa Orientale copre la Tanzania?',
    'blogkenya_faq_a7' => 'No. Copre solo Kenya, Uganda e Ruanda. La Tanzania richiede un proprio visto, attualmente $50 per la maggior parte delle nazionalità.',
    'blogkenya_faq_q8' => 'Quale paese è migliore per i Big Five?',
    'blogkenya_faq_a8' => 'Entrambi offrono facilmente quattro dei cinque. Per il rinoceronte nero, il Kenya ha diverse opzioni affidabili tra cui Ol Pejeta e il Lago Nakuru, mentre in Tanzania il Cratere di Ngorongoro è essenzialmente l\'unico posto realistico.',
    'blogkenya_faq_q9' => 'Dove ci sono meno turisti?',
    'blogkenya_faq_a9' => 'La Tanzania, in particolare il circuito meridionale — Ruaha, Nyerere e Mikumi vedono una piccola frazione dei visitatori sia del Serengeti che del Mara. Anche il Tarangire è tranquillo secondo gli standard dell\'Africa orientale.',
    'blogkenya_faq_q10' => 'Posso fare game drive notturni e guida fuoristrada?',
    'blogkenya_faq_a10' => 'Nelle conservancy private del Kenya, sì. Nei parchi nazionali tanzaniani, la guida fuoristrada è proibita e i game drive notturni non sono permessi tranne al Lago Manyara, Tarangire e alcune concessioni private.',
    'blogkenya_faq_q11' => 'Quale è meglio per un primo safari?',
    'blogkenya_faq_a11' => 'Se avete una settimana o più e volete varietà, la Tanzania. Se avete quattro o cinque giorni, il Kenya offre più fauna selvatica al giorno perché le distanze sono molto più brevi.',
    'blogkenya_faq_q12' => 'E il Kilimanjaro — è in Kenya o Tanzania?',
    'blogkenya_faq_a12' => 'Interamente in Tanzania. La famosa vista del Kilimanjaro che sorge dietro gli elefanti è spesso fotografata da Amboseli in Kenya, ma la montagna stessa e ogni percorso di scalata sono in Tanzania.',
    'blogkenya_related_badge' => 'Continua a leggere',
    'blogkenya_related_title' => 'Continua a esplorare la Tanzania',
    'blogkenya_final_title' => 'Stai ancora decidendo?',
    'blogkenya_final_intro' => 'Dicci le tue date e quanto tempo hai. Se il Kenya si adatta davvero meglio al tuo viaggio rispetto alla Tanzania, te lo diremo — preferiamo essere utili piuttosto che vincere una prenotazione di cui ti pentiresti.',
    'blogkenya_final_whatsapp' => 'Scrivici su WhatsApp',
    'blogkenya_final_contact' => 'Modulo di contatto',

    // ===== Blog article: Visto e Ingresso in Tanzania =====
    'blogvisa_meta_title' => 'Visto e Requisiti d\'Ingresso in Tanzania (2026) | Serengeti Budget Safari',
    'blogvisa_meta_description' => 'Come ottenere un visto tanzaniano nel 2026: e-visa contro visto all\'arrivo, il costo di $50, requisiti del passaporto, l\'assicurazione obbligatoria per Zanzibar, certificati di febbre gialla e come evitare siti non ufficiali che addebitano commissioni.',
    'blogvisa_updated' => 'Aggiornato 2026',
    'blogvisa_h1' => 'Visto e ingresso in Tanzania',
    'blogvisa_hero_sub' => 'Cosa vi serve, quanto costa, quanto tempo richiede — e i due requisiti che colgono di sorpresa i viaggiatori in aeroporto.',
    'blogvisa_author' => 'Team Serengeti Budget Safari',
    'blogvisa_date' => 'Agosto 2026',
    'blogvisa_quick_badge' => 'Risposte rapide',
    'blogvisa_quick_title' => 'Il visto in breve',
    'blogvisa_quick_intro' => 'Cosa serve sapere alla maggior parte dei viaggiatori.',
    'blogvisa_qq1_q' => 'Quanto costa?',
    'blogvisa_qq1_a' => '$50 per la maggior parte delle nazionalità. $100 per i cittadini USA.',
    'blogvisa_qq2_q' => 'Dove faccio domanda?',
    'blogvisa_qq2_a' => 'visa.immigration.go.tz — l\'unico sito ufficiale.',
    'blogvisa_qq3_q' => 'Quanto tempo richiede?',
    'blogvisa_qq3_a' => 'Fino a 10 giorni lavorativi. Fate domanda tre settimane prima.',
    'blogvisa_qq4_q' => 'Validità del passaporto?',
    'blogvisa_qq4_a' => 'Sei mesi oltre l\'ingresso, due pagine bianche.',
    'blogvisa_qq5_q' => 'Zanzibar?',
    'blogvisa_qq5_a' => 'Stesso visto, ma assicurazione locale obbligatoria (~$44).',
    'blogvisa_qq6_q' => 'Febbre gialla?',
    'blogvisa_qq6_a' => 'Solo se arrivate da o transitate in un paese a rischio.',
    'blogvisa_see_faq' => 'Vedi tutte le FAQ',
    'blogvisa_toc_title' => 'Indice – Visto e ingresso in Tanzania',
    'blogvisa_toc_1' => 'Le due strade',
    'blogvisa_toc_2' => 'Cosa vi serve',
    'blogvisa_toc_3' => 'Requisiti per Zanzibar',
    'blogvisa_toc_4' => 'Febbre gialla',
    'blogvisa_toc_5' => 'FAQ',
    'blogvisa_s1_badge' => 'Le opzioni',
    'blogvisa_s1_title' => 'Due modi per ottenere un visto',
    'blogvisa_s1_p1' => 'La maggior parte dei visitatori ha bisogno di un visto per la Tanzania. Il visto turistico standard costa <strong>US$50</strong> per la maggior parte delle nazionalità, è valido per <strong>90 giorni</strong>, e può essere ottenuto sia online in anticipo che all\'arrivo.',
    'blogvisa_s1_sub1' => 'e-Visa online — consigliato',
    'blogvisa_s1_p2' => 'Fate domanda su <strong>visa.immigration.go.tz</strong>, caricate i vostri documenti e pagate con carta. Una decisione richiede di solito <strong>fino a 10 giorni lavorativi</strong>, anche se può essere più lunga nei periodi di alta richiesta. Iniziate almeno <strong>tre settimane</strong> prima di partire. Riceverete un PDF da stampare e presentare all\'arrivo.',
    'blogvisa_s1_sub2' => 'Visto all\'arrivo',
    'blogvisa_s1_p3' => 'Disponibile agli aeroporti di Kilimanjaro (JRO), Dar es Salaam e Zanzibar. Funziona, ma significa fare la fila dopo un lungo volo — spesso per un\'ora o più nei momenti di punta — e pagare in contanti in dollari USA. Se avete tempo per fare domanda online, fatelo.',
    'blogvisa_s1_warn_t' => 'Attenzione ai siti non ufficiali.',
    'blogvisa_s1_warn_d' => 'Cercando un visto tanzaniano si trovano molti siti che sembrano ufficiali e addebitano €50–100 in "commissioni di servizio" per qualcosa che potete fare da soli in venti minuti. L\'unico sito ufficiale è <strong>visa.immigration.go.tz</strong> e il visto costa $50.',
    'blogvisa_s2_badge' => 'Requisiti',
    'blogvisa_s2_title' => 'Cosa vi serve',
    'blogvisa_s2_i1_t' => 'Passaporto',
    'blogvisa_s2_i1_d' => 'valido almeno sei mesi dalla data di ingresso, con due pagine bianche',
    'blogvisa_s2_i2' => 'Una <strong>foto digitale formato passaporto</strong>',
    'blogvisa_s2_i3' => 'Il vostro <strong>biglietto di ritorno o di proseguimento</strong>',
    'blogvisa_s2_i4' => 'L\'indirizzo del vostro <strong>alloggio della prima notte</strong> — lo forniamo con la conferma della prenotazione',
    'blogvisa_s2_i5' => 'Una carta di credito o debito per il pagamento online',
    'blogvisa_s2_sub1' => 'Nazionalità che pagano di più',
    'blogvisa_s2_p1' => 'Ai <strong>cittadini USA</strong> viene rilasciato un visto a ingressi multipli che costa <strong>$100</strong> anziché i $50 standard a ingresso singolo. Un piccolo numero di nazionalità richiede visti con referral e tempi di elaborazione più lunghi — se avete un passaporto al di fuori di Europa, Nord America o Commonwealth, controllate con largo anticipo.',
    'blogvisa_s3_badge' => 'Zanzibar',
    'blogvisa_s3_title' => 'Zanzibar: stesso visto, assicurazione extra',
    'blogvisa_s3_p1' => 'Zanzibar fa parte della Tanzania, quindi <strong>non serve un secondo visto</strong>. C\'è, tuttavia, un requisito aggiuntivo che coglie di sorpresa molte persone.',
    'blogvisa_s3_p2' => 'Dal 2024, tutti i visitatori stranieri a Zanzibar devono avere un\'<strong>assicurazione di viaggio obbligatoria emessa da un fornitore approvato da Zanzibar</strong>, che costa circa <strong>US$44</strong> e va acquistata online prima dell\'arrivo. La vostra polizza di viaggio europea o americana esistente, per quanto completa, <strong>non soddisfa questo requisito</strong> — è un prodotto separato, emesso localmente.',
    'blogvisa_s3_p3' => 'Questo viene controllato all\'aeroporto di Zanzibar e al terminal dei traghetti. Compratela in anticipo; possiamo organizzarla con la vostra prenotazione.',
    'blogvisa_s4_badge' => 'Ingresso sanitario',
    'blogvisa_s4_title' => 'Certificato di febbre gialla',
    'blogvisa_s4_p1' => 'Un certificato di febbre gialla è richiesto <strong>solo</strong> se arrivate da, o avete transitato per più di 12 ore attraverso, un paese a rischio di febbre gialla.',
    'blogvisa_s4_p2' => 'I viaggiatori che volano direttamente da Europa, Nord America o Asia <strong>non ne hanno bisogno</strong>. I viaggiatori in transito da Nairobi, Addis Abeba o altri hub africani <strong>potrebbero</strong> averne bisogno, a seconda della durata dello scalo — è qui che le persone vengono colte di sorpresa.',
    'blogvisa_s4_p3' => 'Il certificato viene controllato all\'arrivo, e senza di esso dove è richiesto sarete vaccinati in aeroporto a vostre spese. Controllate il vostro itinerario specifico prima di volare.',
    'blogvisa_faq_badge' => 'FAQ',
    'blogvisa_faq_title' => 'Visto Tanzania — domande frequenti',
    'blogvisa_faq_q1' => 'Ho bisogno di un visto per la Tanzania?',
    'blogvisa_faq_a1' => 'La maggior parte delle nazionalità sì. Il visto turistico standard costa US$50, è valido per 90 giorni, e può essere ottenuto online in anticipo o all\'arrivo nei principali aeroporti.',
    'blogvisa_faq_q2' => 'Quanto costa un visto tanzaniano?',
    'blogvisa_faq_a2' => 'US$50 per la maggior parte delle nazionalità. I cittadini USA pagano $100 per un visto a ingressi multipli. Attenzione ai siti web non ufficiali che addebitano €50–100 di commissioni aggiuntive per la stessa cosa.',
    'blogvisa_faq_q3' => 'Quanto tempo richiede l\'e-visa?',
    'blogvisa_faq_a3' => 'Di solito fino a 10 giorni lavorativi, a volte di più nei periodi di alta richiesta. Fate domanda almeno tre settimane prima di partire per sicurezza.',
    'blogvisa_faq_q4' => 'Qual è il sito web ufficiale del visto?',
    'blogvisa_faq_a4' => 'visa.immigration.go.tz — è l\'unico portale ufficiale. Molti siti dall\'aspetto convincente addebitano commissioni sostanziali per un servizio che potete completare da soli in circa venti minuti.',
    'blogvisa_faq_q5' => 'Posso ottenere un visto all\'arrivo?',
    'blogvisa_faq_a5' => 'Sì, agli aeroporti di Kilimanjaro, Dar es Salaam e Zanzibar, pagando in contanti in dollari USA. Funziona, ma aspettatevi di fare la fila — a volte per oltre un\'ora dopo un lungo volo. Fare domanda online è l\'opzione più tranquilla.',
    'blogvisa_faq_q6' => 'Serve un visto separato per Zanzibar?',
    'blogvisa_faq_a6' => 'No. Zanzibar fa parte della Tanzania e lo stesso visto la copre. Ma dal 2024 serve un\'assicurazione di viaggio obbligatoria da un fornitore approvato da Zanzibar, che costa circa US$44, acquistata prima dell\'arrivo.',
    'blogvisa_faq_q7' => 'La mia normale assicurazione di viaggio copre il requisito di Zanzibar?',
    'blogvisa_faq_a7' => 'No. L\'assicurazione obbligatoria di Zanzibar è un prodotto separato, emesso localmente. La vostra polizza europea o americana, per quanto completa, non soddisfa il requisito e viene controllata all\'arrivo.',
    'blogvisa_faq_q8' => 'Per quanto tempo deve essere valido il mio passaporto?',
    'blogvisa_faq_a8' => 'Almeno sei mesi oltre la data di ingresso, con due pagine bianche. Questo viene controllato e fatto rispettare.',
    'blogvisa_faq_q9' => 'Serve un certificato di febbre gialla?',
    'blogvisa_faq_a9' => 'Solo se arrivate da o avete transitato per più di 12 ore attraverso un paese a rischio di febbre gialla. I voli diretti dall\'Europa non lo richiedono — ma uno scalo lungo a Nairobi o Addis Abeba potrebbe.',
    'blogvisa_faq_q10' => 'Per quanto tempo posso restare?',
    'blogvisa_faq_a10' => 'Il visto turistico standard è valido per 90 giorni. Le proroghe sono possibili tramite gli uffici immigrazione in Tanzania ma sono burocratiche, quindi pianificate bene le vostre date.',
    'blogvisa_faq_q11' => 'Posso lavorare o fare volontariato con un visto turistico?',
    'blogvisa_faq_a11' => 'No. Il volontariato richiede un permesso diverso anche se non retribuito, e le regole sono fatte rispettare. Se state pianificando un lavoro di volontariato, organizzate il permesso corretto con largo anticipo.',
    'blogvisa_faq_q12' => 'Cosa succede se il mio visto viene rifiutato o ritardato?',
    'blogvisa_faq_a12' => 'I ritardi sono più comuni dei rifiuti. Se la vostra data di viaggio si avvicina e non è arrivata alcuna decisione, il visto all\'arrivo resta disponibile ai principali aeroporti come alternativa — portate contanti in dollari USA.',
    'blogvisa_faq_q13' => 'I bambini hanno bisogno di un visto?',
    'blogvisa_faq_a13' => 'Sì, ogni viaggiatore ha bisogno del proprio visto indipendentemente dall\'età, e ogni bambino ha bisogno del proprio passaporto. Ai bambini che viaggiano con un solo genitore può essere richiesta una lettera di consenso dell\'altro.',
    'blogvisa_faq_q14' => 'Il Visto Turistico dell\'Africa Orientale è valido per la Tanzania?',
    'blogvisa_faq_a14' => 'No. Il Visto Turistico dell\'Africa Orientale copre Kenya, Uganda e Ruanda ma non la Tanzania. Se state combinando la Tanzania con il Kenya, servono visti separati per ciascuno.',
    'blogvisa_related_badge' => 'Continua a leggere',
    'blogvisa_related_title' => 'Continua a esplorare la Tanzania',
    'blogvisa_related_contact' => 'Facci una domanda',
    'blogvisa_final_title' => 'Serve aiuto con la burocrazia?',
    'blogvisa_final_intro' => 'Forniamo l\'indirizzo dell\'alloggio necessario per la domanda di visto, e possiamo organizzare l\'assicurazione obbligatoria per Zanzibar con la vostra prenotazione. Basta chiedere.',
    'blogvisa_final_whatsapp' => 'Scrivici su WhatsApp',
    'blogvisa_final_contact' => 'Modulo di contatto',

    // ===== Blog article: Cosa Portare per un Safari =====
    'blogpack_meta_title' => 'Cosa Portare per un Safari in Tanzania (Checklist 2026) | Serengeti Budget Safari',
    'blogpack_meta_description' => 'Una lista pratica per il safari: abbigliamento, kit medico, attrezzatura fotografica, documenti e denaro — più cosa lasciare a casa, inclusi oggetti che sono effettivamente illegali in Tanzania.',
    'blogpack_h1' => 'Cosa portare per un safari',
    'blogpack_hero_sub' => 'Strati, colori neutri e 15 kg in una borsa morbida — più gli oggetti che i viaggiatori dimenticano più spesso, e quelli effettivamente illegali in Tanzania.',
    'blogpack_updated' => 'Aggiornato 2026',
    'blogpack_author' => 'Team Serengeti Budget Safari',
    'blogpack_date' => 'Agosto 2026',
    'blogpack_quick_badge' => 'Risposte rapide',
    'blogpack_quick_title' => 'La valigia in breve',
    'blogpack_quick_intro' => 'Gli essenziali, prima della lista completa.',
    'blogpack_qq1_q' => 'La regola unica?',
    'blogpack_qq1_a' => 'Strati. 14°C all\'alba, 28°C a mezzogiorno.',
    'blogpack_qq2_q' => 'Limite bagaglio?',
    'blogpack_qq2_a' => 'Borsa morbida da 15 kg sui voli interni. Rispettato rigorosamente.',
    'blogpack_qq3_q' => 'Che colori?',
    'blogpack_qq3_a' => 'Kaki e verde oliva. Evitate blu e nero — mosche tse-tse.',
    'blogpack_qq4_q' => 'Oggetto più dimenticato?',
    'blogpack_qq4_a' => 'Il binocolo. Più utile di un teleobiettivo.',
    'blogpack_qq5_q' => 'Cosa è vietato?',
    'blogpack_qq5_a' => 'Abbigliamento mimetico e sacchetti di plastica monouso.',
    'blogpack_qq6_q' => 'Quanti vestiti?',
    'blogpack_qq6_a' => 'Per quattro giorni. Il bucato è disponibile quasi ovunque.',
    'blogpack_see_faq' => 'Vedi tutte le FAQ',
    'blogpack_toc_title' => 'Indice – Cosa portare per un safari',
    'blogpack_toc_1' => 'La regola unica',
    'blogpack_toc_2' => 'Abbigliamento',
    'blogpack_toc_3' => 'Kit medico',
    'blogpack_toc_4' => 'Kit fotografico',
    'blogpack_toc_5' => 'Documenti e denaro',
    'blogpack_toc_6' => 'Cosa lasciare a casa',
    'blogpack_toc_7' => 'FAQ',
    'blogpack_s1_badge' => 'Il principio',
    'blogpack_s1_title' => 'La regola unica che conta',
    'blogpack_s1_p1' => '<strong>Vestitevi a strati.</strong> Una giornata di safari inizia intorno ai 14°C — 5°C sul bordo di Ngorongoro — e raggiunge i 28°C a mezzogiorno, e sperimenterete entrambi da un veicolo aperto. Un cappotto pesante è la risposta sbagliata; uno strato base, un pile e una giacca antivento sono quella giusta.',
    'blogpack_s1_p2' => 'La seconda regola, se avete voli interni: <strong>15 kg in una borsa morbida</strong>. Gli aerei leggeri in Tanzania la applicano rigorosamente, e le valigie rigide vengono rifiutate perché non entrano nella stiva. La maggior parte dei lodge offre bucato in giornata, quindi fare la valigia per quattro giorni anziché dieci è quasi sempre la scelta giusta.',
    'blogpack_s2_badge' => 'Abbigliamento',
    'blogpack_s2_title' => 'Abbigliamento',
    'blogpack_s2_i1_t' => 'Pile o giacca imbottita',
    'blogpack_s2_i1_d' => 'essenziale, e l\'oggetto più comunemente dimenticato',
    'blogpack_s2_i2_t' => 'Giacca antivento',
    'blogpack_s2_i2_d' => 'il freddo del vento in un veicolo aperto all\'alba è notevole',
    'blogpack_s2_i3_t' => 'Camicie a maniche lunghe',
    'blogpack_s2_i3_d' => 'protezione dal sole e dalle zanzare',
    'blogpack_s2_i4' => 'Magliette in tessuto traspirante',
    'blogpack_s2_i5' => 'Pantaloni lunghi leggeri — più utili dei pantaloncini',
    'blogpack_s2_i6' => 'Cappello a tesa larga e occhiali da sole',
    'blogpack_s2_i7_t' => 'Scarpe chiuse comode',
    'blogpack_s2_i7_d' => 'scarponi solo se fate trekking',
    'blogpack_s2_i8_t' => 'Un buff o una sciarpa',
    'blogpack_s2_i8_d' => 'la polvere della stagione secca è implacabile',
    'blogpack_s2_i9' => 'Costume da bagno — molti lodge hanno piscine',
    'blogpack_s2_i10' => 'Qualcosa di elegante-casual per cena nei lodge migliori',
    'blogpack_s2_sub1' => 'I colori contano più di quanto pensiate',
    'blogpack_s2_p1' => 'Indossate <strong>kaki, verde oliva, beige e marrone</strong>. Ci sono tre cose specifiche da evitare:',
    'blogpack_s2_n1_t' => 'Blu e nero',
    'blogpack_s2_n1_d' => 'attraggono le mosche tse-tse, presenti nel Tarangire e nella foresta di miombo dei parchi meridionali. Il loro morso è doloroso.',
    'blogpack_s2_n2_t' => 'Bianco',
    'blogpack_s2_n2_d' => 'smette di essere bianco dopo mezza giornata su una pista polverosa.',
    'blogpack_s2_n3_t' => 'Il mimetico è illegale per i civili in Tanzania.',
    'blogpack_s2_n3_d' => 'È riservato ai militari, e indossarlo può davvero causare problemi.',
    'blogpack_s3_badge' => 'Salute',
    'blogpack_s3_title' => 'Kit medico e articoli da toeletta',
    'blogpack_s3_i1_t' => 'Compresse antimalariche',
    'blogpack_s3_i1_d' => 'prescritte dal vostro medico',
    'blogpack_s3_i2_t' => 'Repellente per insetti al DEET',
    'blogpack_s3_i2_d' => 'la concentrazione più forte che tollerate',
    'blogpack_s3_i3_t' => 'Crema solare ad alta protezione',
    'blogpack_s3_i3_d' => 'e balsamo labbra con SPF; i raggi UV in quota sono intensi',
    'blogpack_s3_i4' => 'Antidolorifici, antidiarroici e sali reidratanti',
    'blogpack_s3_i5' => 'Cerotti, antisettico, trattamento per le vesciche',
    'blogpack_s3_i6' => 'Qualsiasi farmaco su prescrizione <strong>nel bagaglio a mano</strong>, con una copia della prescrizione',
    'blogpack_s3_i7' => 'Disinfettante per le mani e salviette umide — genuinamente utili sui lunghi tragitti',
    'blogpack_s3_i8' => 'Compresse per il mal d\'auto se ne siete soggetti; le piste sono accidentate',
    'blogpack_s3_link' => 'Guida completa a vaccinazioni e salute',
    'blogpack_s4_badge' => 'Fotografia',
    'blogpack_s4_title' => 'Fotografia e ottica',
    'blogpack_tag_binoculars' => 'Binocolo',
    'blogpack_tag_lens' => 'Obiettivo 300mm+',
    'blogpack_tag_wide' => 'Obiettivo grandangolare',
    'blogpack_tag_battery' => 'Batterie di riserva',
    'blogpack_tag_memory' => 'Schede di memoria',
    'blogpack_tag_dustbag' => 'Borsa antipolvere',
    'blogpack_tag_beanbag' => 'Sacco di fagioli',
    'blogpack_s4_p1' => 'Il <strong>binocolo</strong> è l\'oggetto singolarmente più sottovalutato — molti avvistamenti, in particolare il rinoceronte nel cratere, sono semplicemente troppo distanti per una macchina fotografica. Portate <strong>un obiettivo da 300 mm o più lungo</strong> se siete seri riguardo alla fotografia naturalistica, ma <strong>anche un obiettivo grandangolare</strong> — baobab, il cratere, le pianure all\'alba — vi pentirete di aver portato solo un teleobiettivo. I campi spesso usano generatori solo per ore limitate, quindi portate batterie di riserva e più schede di memoria di quanto pensiate. Una borsa antipolvere conta: la polvere della stagione secca entra ovunque, e cambiare obiettivi in un veicolo in movimento è il modo in cui i sensori si rovinano. Un sacco di fagioli o un sostituto è utile per stabilizzare i teleobiettivi sul portellone del tetto.',
    'blogpack_s5_badge' => 'Documenti',
    'blogpack_s5_title' => 'Documenti e denaro',
    'blogpack_s5_i1_t' => 'Passaporto',
    'blogpack_s5_i1_d' => 'valido almeno sei mesi oltre l\'ingresso, con due pagine bianche',
    'blogpack_s5_i2_t' => 'Conferma del visto stampata',
    'blogpack_s5_i2_d' => 'e polizza assicurativa di viaggio',
    'blogpack_s5_i3_t' => 'Certificato di febbre gialla',
    'blogpack_s5_i3_d' => 'se arrivate da o transitate in un paese a rischio',
    'blogpack_s5_i4' => '<strong>Dollari USA in contanti</strong> per mance ed extra — e questo conta: <strong>le banconote devono essere emesse dopo il 2009</strong>. Le banconote più vecchie vengono rifiutate in tutta la Tanzania.',
    'blogpack_s5_i5' => 'Piccoli tagli per le mance ($1, $5, $10)',
    'blogpack_s5_i6' => 'Una carta di credito come riserva, anche se la connettività è inaffidabile',
    'blogpack_s5_i7_t' => 'Adattatore di tipo G',
    'blogpack_s5_i7_d' => 'lo standard britannico a tre poli',
    'blogpack_s5_i8' => 'Copie digitali di tutto, conservate da qualche parte raggiungibile offline',
    'blogpack_s6_badge' => 'Non portare',
    'blogpack_s6_title' => 'Cosa lasciare a casa',
    'blogpack_s6_i1_t' => 'Valigie rigide',
    'blogpack_s6_i1_d' => 'se avete voli interni — verranno rifiutate',
    'blogpack_s6_i2_t' => 'Abbigliamento mimetico',
    'blogpack_s6_i2_d' => 'illegale per i civili',
    'blogpack_s6_i3_t' => 'Sacchetti di plastica monouso',
    'blogpack_s6_i3_d' => 'vietati in tutta la Tanzania dal 2019, e confiscati in aeroporto',
    'blogpack_s6_i4_t' => 'Droni',
    'blogpack_s6_i4_d' => 'richiedono un permesso scritto del TANAPA, raramente concesso',
    'blogpack_s6_i5_t' => 'Un asciugacapelli',
    'blogpack_s6_i5_d' => 'la maggior parte dei lodge li ha, e drenano l\'energia limitata del generatore',
    'blogpack_s6_i6_t' => 'Dieci giorni di vestiti',
    'blogpack_s6_i6_d' => 'il bucato è disponibile quasi ovunque e di solito in giornata',
    'blogpack_s6_i7_t' => 'Gioielli di valore',
    'blogpack_s6_i7_d' => 'non c\'è dove indossarli né dove lasciarli in sicurezza',
    'blogpack_tip_t' => 'Il consiglio singolo più utile:',
    'blogpack_tip_d' => 'fate la valigia per quattro giorni, non dieci, e usate il servizio lavanderia. Quasi ogni viaggiatore che ospitiamo dice poi di aver portato circa il doppio di quanto gli serviva.',
    'blogpack_faq_badge' => 'FAQ',
    'blogpack_faq_title' => 'Valigia per il safari — domande frequenti',
    'blogpack_faq_q1' => 'Cosa dovrei indossare in safari?',
    'blogpack_faq_a1' => 'Strati in colori neutri — kaki, verde oliva, beige, marrone. Le mattine sono intorno ai 14°C e i pomeriggi vicino ai 28°C, e sperimenterete entrambi da un veicolo aperto. Evitate blu e nero, che attraggono le mosche tse-tse.',
    'blogpack_faq_q2' => 'Perché dovrei evitare abiti blu e neri?',
    'blogpack_faq_a2' => 'Le mosche tse-tse sono attratte da quei colori, e sono presenti nel Tarangire e nella foresta di miombo dei parchi meridionali. Il morso è doloroso, anche se non c\'è rischio di malattia del sonno nelle principali aree turistiche.',
    'blogpack_faq_q3' => 'Posso indossare abbigliamento mimetico?',
    'blogpack_faq_a3' => 'No. Il mimetico è riservato ai militari in Tanzania ed è illegale per i civili. Indossarlo può causare veri problemi ai posti di blocco, quindi lasciatelo a casa.',
    'blogpack_faq_q4' => 'Qual è il limite di bagaglio sui voli interni?',
    'blogpack_faq_a4' => '15 kg in una borsa morbida, rigorosamente rispettato sugli aerei leggeri. Le valigie rigide vengono rifiutate perché non entrano nella stiva. Se avete una borsa più grande, la maggior parte degli hotel di Arusha la conserverà mentre volate.',
    'blogpack_faq_q5' => 'Servono scarponi da trekking per un safari?',
    'blogpack_faq_a5' => 'No — scarpe chiuse comode bastano per un safari di game drive, poiché passate la maggior parte del tempo in un veicolo. Scarponi veri servono solo per il Kilimanjaro, il Monte Meru o safari a piedi impegnativi.',
    'blogpack_faq_q6' => 'Quanto fa freddo davvero?',
    'blogpack_faq_a6' => 'Il bordo di Ngorongoro scende a circa 5°C prima dell\'alba e il Serengeti a 13–15°C. In un veicolo aperto in movimento a 30 km/h si sente considerevolmente più freddo. Un pile e uno strato antivento non sono opzionali.',
    'blogpack_faq_q7' => 'Dovrei portare il binocolo?',
    'blogpack_faq_a7' => 'Sì, ed è l\'oggetto più comunemente dimenticato. Molti avvistamenti — il rinoceronte nel Cratere di Ngorongoro soprattutto — sono troppo distanti per un obiettivo fotografico ma perfetti attraverso il binocolo.',
    'blogpack_faq_q8' => 'Che attrezzatura fotografica mi serve?',
    'blogpack_faq_a8' => 'Un obiettivo da 300 mm o più lungo per la fauna selvatica, più un grandangolare per i paesaggi. Portate batterie di riserva, poiché i campi spesso usano i generatori solo a ore stabilite, e una borsa antipolvere — la polvere della stagione secca distrugge i sensori.',
    'blogpack_faq_q9' => 'Posso fare il bucato in safari?',
    'blogpack_faq_a9' => 'Sì, in quasi ogni lodge e campo, di solito in giornata. Ecco perché fare la valigia per quattro giorni anziché dieci è quasi sempre la decisione giusta, in particolare con un limite di volo di 15 kg.',
    'blogpack_faq_q10' => 'Che denaro dovrei portare?',
    'blogpack_faq_a10' => 'Dollari USA in contanti per mance ed extra, in banconote emesse dopo il 2009 — le banconote più vecchie vengono rifiutate in tutta la Tanzania. Portate piccoli tagli per le mance. Le carte funzionano nei lodge ma la connettività è inaffidabile.',
    'blogpack_faq_q11' => 'I sacchetti di plastica sono davvero vietati?',
    'blogpack_faq_a11' => 'Sì, dal 2019, ed è fatto rispettare in aeroporto dove vengono confiscati all\'arrivo. Portate borse di tessuto o rete invece. I sacchetti ziplock per gli articoli da toeletta sono generalmente tollerati ma l\'approccio più sicuro è evitarli tutti.',
    'blogpack_faq_q12' => 'Serve un adattatore per la presa?',
    'blogpack_faq_a12' => 'Sì, tipo G — lo standard britannico a tre poli. La tensione è 230V. Portate un adattatore multi-presa se avete diversi dispositivi, perché i campi spesso hanno solo una o due prese per tenda.',
    'blogpack_faq_q13' => 'Posso portare un drone?',
    'blogpack_faq_a13' => 'Solo con permesso scritto del TANAPA, raramente concesso per il turismo. Volare senza rischia la confisca e una multa. Assumete che la risposta sia no a meno che non abbiate i documenti in mano.',
    'blogpack_related_badge' => 'Continua a leggere',
    'blogpack_related_title' => 'Continua a esplorare la Tanzania',
    'blogpack_related_trekking' => 'La valigia per il Kilimanjaro è diversa',
    'blogpack_final_title' => 'Domande su cosa portare?',
    'blogpack_final_intro' => 'Inviaci il tuo itinerario e ti diremo esattamente cosa ti serve per quei parchi specifici e quella stagione — incluso se il limite di volo di 15 kg si applica a te.',
    'blogpack_final_whatsapp' => 'Scrivici su WhatsApp',
    'blogpack_final_contact' => 'Modulo di contatto',

    // ===== Blog article: Vaccinazioni e Salute =====
    'blogvax_meta_title' => 'Guida a Vaccinazioni e Salute per la Tanzania (2026) | Serengeti Budget Safari',
    'blogvax_meta_description' => 'Cosa vi serve davvero prima di viaggiare in Tanzania — vaccinazioni, malaria, acqua, altitudine e la clausola assicurativa che la maggior parte delle persone trascura. Informazione, non consiglio medico.',
    'blogvax_updated' => 'Aggiornato 2026',
