    'blogvax_s0_warn_t' => 'Questa pagina è informazione, non consiglio medico.',
    'blogvax_s0_warn_d' => 'Parlate con il vostro medico o una clinica di viaggio <strong>sei-otto settimane prima di partire</strong>. I requisiti dipendono dalla vostra storia medica, dal vostro itinerario esatto e dal vostro percorso, e solo un medico può consigliarvi correttamente.',
    'blogvax_s0_p1' => 'Detto questo, ecco cosa la maggior parte dei viaggiatori verso la Tanzania deve considerare.',
    'blogvax_s1_badge' => 'Vaccinazioni',
    'blogvax_s1_title' => 'Vaccinazioni',
    'blogvax_s1_sub1' => 'Obbligatoria in un caso specifico',
    'blogvax_s1_p1' => 'La <strong>febbre gialla</strong> è l\'unica vaccinazione che è un requisito legale d\'ingresso, e solo se arrivate da — o avete transitato per più di 12 ore attraverso — un paese a rischio di febbre gialla. I voli diretti dall\'Europa non la richiedono; uno scalo lungo a Nairobi o Addis Abeba potrebbe.',
