    'blogvax_s2_badge' => 'Malaria',
    'blogvax_s2_title' => 'Malaria — quella che conta di più',
    'blogvax_s2_p1' => 'La malaria è presente in tutta la Tanzania, <strong>inclusa Zanzibar</strong>. Il rischio è più basso in altitudine — Arusha, Ngorongoro e gli altopiani del Serengeti — e più alto sulla costa e nei parchi meridionali a bassa quota come Nyerere e Mikumi.',
    'blogvax_s2_sub1' => 'Profilassi',
    'blogvax_s2_p2' => 'Il vostro medico prescriverà una delle opzioni standard — atovaquone/proguanil, doxiciclina o meflochina — ciascuna con dosaggi ed effetti collaterali diversi. Prendetela esattamente come indicato, incluse le dosi <em>dopo</em> il ritorno, che è la parte che le persone dimenticano.',
    'blogvax_s2_sub2' => 'La prevenzione dalle punture conta altrettanto',
    'blogvax_s2_p3' => 'Nessuna profilassi è efficace al 100%, quindi le misure fisiche non sono opzionali:',
    'blogvax_s2_b1_t' => 'Repellente DEET',
    'blogvax_s2_b1_d' => 'sulla pelle esposta, riapplicato al tramonto',
    'blogvax_s2_b2_t' => 'Maniche lunghe e pantaloni',
    'blogvax_s2_b2_d' => 'dopo il tramonto — la zanzara della malaria punge tra il tramonto e l\'alba',
    'blogvax_s2_b3_t' => 'Dormite sotto la zanzariera',
    'blogvax_s2_b3_d' => 'fornita; controllatela per buchi',
    'blogvax_s2_b4_t' => 'Aria condizionata o un ventilatore',
    'blogvax_s2_b4_d' => 'durante la notte dove disponibile',
    'blogvax_s2_warn_t' => 'Dopo il rientro:',
    'blogvax_s2_warn_d' => 'se sviluppate febbre entro dodici mesi dal rientro — e in particolare entro i primi tre mesi — consultate immediatamente un medico e ditegli che siete stati in una zona malarica. La malaria è completamente curabile se scoperta presto e pericolosa se non lo è.',
    'blogvax_s3_badge' => 'Cibo e acqua',
    'blogvax_s3_title' => 'Cibo e acqua',
    'blogvax_s3_i1_t' => 'Bevete solo acqua in bottiglia o filtrata.',
    'blogvax_s3_i1_d' => 'È fornita nei nostri veicoli durante ogni game drive.',
    'blogvax_s3_i2' => 'Evitate il ghiaccio dove non siete sicuri della fonte dell\'acqua.',
    'blogvax_s3_i3' => 'Sbucciate la frutta voi stessi.',
    'blogvax_s3_i4' => 'Il cibo di lodge e campi è preparato secondo standard elevati ed è sicuro.',
    'blogvax_s3_i5' => 'Per il cibo di strada, applicate il test abituale: appena cucinato, servito caldo, e affollato di locali.',
    'blogvax_s3_i6' => 'Lavatevi i denti con acqua in bottiglia se lo stomaco è sensibile.',
    'blogvax_s3_p1' => 'La diarrea del viaggiatore è il disturbo più comune, ed è di solito lieve. Portate sali reidratanti e un antidiarroico, e consultate un medico se dura più di un paio di giorni o comporta febbre o sangue.',
    'blogvax_s4_badge' => 'Altitudine',
    'blogvax_s4_title' => 'Altitudine',
    'blogvax_s4_p1' => 'La maggior parte dei viaggiatori in safari non avrà problemi di altitudine, ma vale la pena conoscere due luoghi.',
    'blogvax_s4_p2' => 'Il bordo di Ngorongoro si trova a 2.200–2.400 m. Un lieve mal di testa la prima notte è comune. Bevete più acqua di quanto pensiate di aver bisogno e di solito passa.',
    'blogvax_s4_p3' => 'Il Kilimanjaro è tutta un\'altra questione. A 5.895 m c\'è circa la metà dell\'ossigeno disponibile al livello del mare, e il mal di montagna è la principale ragione per cui le scalate falliscono. Sintomi, prevenzione e segnali d\'allarme sono trattati in dettaglio nella nostra',
    'blogvax_s4_link' => 'guida al Kilimanjaro',
    'blogvax_s5_badge' => 'Assicurazione',
    'blogvax_s5_title' => 'Assicurazione di viaggio',
    'blogvax_s5_p1' => 'L\'assicurazione di viaggio è <strong>obbligatoria</strong> nei nostri viaggi, e non è una formalità. Dentro i parchi l\'ospedale più vicino può essere a ore di distanza su strada, e i casi gravi vengono trasportati in aereo ad Arusha, Dar es Salaam o Nairobi. L\'evacuazione medica costa molte migliaia di dollari.',
    'blogvax_s5_p2' => 'La vostra polizza deve coprire:',
    'blogvax_s5_i1_t' => 'Spese mediche',
    'blogvax_s5_i1_d' => 'e cure ospedaliere',
    'blogvax_s5_i2' => 'Evacuazione di emergenza e rimpatrio',
    'blogvax_s5_i3_t' => 'Trekking fino a 6.000 m',
    'blogvax_s5_i3_d' => 'se state scalando il Kilimanjaro o il Meru — molte polizze standard escludono l\'attività ad alta quota, ed è la lacuna più comune',
    'blogvax_s5_i4' => 'Cancellazione del viaggio, che consigliamo anche',
    'blogvax_s5_p3' => 'Per Zanzibar, ricordate la separata <strong>assicurazione locale obbligatoria (~$44)</strong> introdotta nel 2024, che la vostra polizza normale non sostituisce.',
    'blogvax_s6_badge' => 'Pratico',
    'blogvax_s6_title' => 'Altri punti pratici sulla salute',
    'blogvax_s6_i1_t' => 'Sole.',
    'blogvax_s6_i1_d' => 'I raggi UV a 1.500–2.400 m vicino all\'equatore sono intensi anche quando l\'aria è fresca. Crema solare ad alta protezione, cappello e occhiali da sole, ogni giorno.',
    'blogvax_s6_i2_t' => 'Mosche tse-tse.',
    'blogvax_s6_i2_d' => 'Presenti nel Tarangire e nel miombo meridionale. Il morso fa male; la malattia del sonno non è un rischio pratico nelle aree turistiche. Evitate abiti blu e neri.',
    'blogvax_s6_i3_t' => 'Polvere.',
    'blogvax_s6_i3_d' => 'La polvere della stagione secca irrita occhi e vie respiratorie. Portate un buff, e collirio se portate lenti a contatto.',
    'blogvax_s6_i4_t' => 'Schistosomiasi (bilharzia).',
    'blogvax_s6_i4_d' => 'Presente in alcune acque dolci. Non nuotate in laghi o fiumi a meno che la vostra guida non confermi che sia sicuro.',
    'blogvax_s6_i5_t' => 'Farmaci su prescrizione.',
    'blogvax_s6_i5_d' => 'Portateli nel bagaglio a mano nella confezione originale con una copia della prescrizione.',
    'blogvax_s6_i6_t' => 'Farmacie.',
    'blogvax_s6_i6_d' => 'Arusha e Moshi ne hanno di ben fornite. Dentro i parchi non ce ne sono — portate ciò che vi serve.',
    'blogvax_faq_badge' => 'FAQ',
    'blogvax_faq_title' => 'Salute e vaccinazioni — domande frequenti',
    'blogvax_faq_q1' => 'Quali vaccinazioni mi servono per la Tanzania?',
    'blogvax_faq_a1' => 'La febbre gialla è un requisito legale solo se arrivate da o transitate in un paese a rischio. Epatite A e tifo sono consigliate per la maggior parte dei viaggiatori, insieme ai richiami di routine per tetano, difterite e polio. Consultate una clinica di viaggio sei-otto settimane prima.',
    'blogvax_faq_q2' => 'Serve la vaccinazione contro la febbre gialla?',
    'blogvax_faq_a2' => 'Solo se arrivate da, o avete transitato per più di 12 ore attraverso, un paese a rischio di febbre gialla. I viaggiatori con volo diretto dall\'Europa non ne hanno bisogno, ma uno scalo lungo a Nairobi o Addis Abeba potrebbe far scattare il requisito.',
    'blogvax_faq_q3' => 'C\'è la malaria in Tanzania?',
    'blogvax_faq_a3' => 'Sì, in tutto il paese inclusa Zanzibar. Il rischio è più basso in altitudine ad Arusha e sugli altopiani di Ngorongoro, e più alto sulla costa e nei parchi meridionali a bassa quota. Profilassi più prevenzione delle punture è l\'approccio standard.',
    'blogvax_faq_q4' => 'Quale antimalarico dovrei prendere?',
    'blogvax_faq_a4' => 'Questa è una decisione per il vostro medico. Le opzioni comuni sono atovaquone/proguanil, doxiciclina e meflochina, ciascuna con dosaggi ed effetti collaterali diversi. Completate l\'intero ciclo incluse le dosi dopo il rientro a casa.',
    'blogvax_faq_q5' => 'C\'è la malaria a Zanzibar?',
    'blogvax_faq_a5' => 'Sì. Zanzibar è una zona malarica ed essere sulla costa significa che il rischio è più alto che negli altopiani settentrionali, non più basso. Prendete le stesse precauzioni che in safari.',
    'blogvax_faq_q6' => 'Posso bere l\'acqua del rubinetto?',
    'blogvax_faq_a6' => 'No. Bevete solo acqua in bottiglia o filtrata, evitate il ghiaccio dove non siete sicuri della fonte, e sbucciate la vostra frutta. L\'acqua da bere è fornita nei nostri veicoli durante ogni game drive.',
    'blogvax_faq_q7' => 'Serve l\'assicurazione di viaggio?',
    'blogvax_faq_a7' => 'Sì — è obbligatoria nei nostri viaggi. Deve coprire le spese mediche e l\'evacuazione di emergenza, perché l\'ospedale più vicino a un parco può essere a ore di distanza e i casi gravi vengono trasportati in aereo a costi considerevoli.',
    'blogvax_faq_q8' => 'La mia assicurazione deve coprire l\'altitudine?',
    'blogvax_faq_a8' => 'Se state scalando il Kilimanjaro o il Monte Meru, sì — deve coprire esplicitamente il trekking fino a 6.000 m. Molte polizze di viaggio standard escludono l\'attività ad alta quota, ed è la lacuna più comune che vediamo.',
    'blogvax_faq_q9' => 'Cosa succede se mi ammalo in safari?',
    'blogvax_faq_a9' => 'Dite immediatamente alla vostra guida. Le guide portano kit di pronto soccorso e conoscono le strutture più vicine. Arusha e Moshi hanno buone cliniche private; dai parchi remoti, i casi gravi vengono evacuati via aerea, ed è per questo che serve l\'assicurazione.',
    'blogvax_faq_q10' => 'C\'è mal di montagna in safari?',
    'blogvax_faq_a10' => 'Raramente. Il bordo di Ngorongoro a 2.200–2.400 m può causare un lieve mal di testa la prima notte, di solito risolto bevendo più acqua. Il Kilimanjaro è tutta un\'altra questione ed è trattato nella nostra guida al Kilimanjaro.',
    'blogvax_faq_q11' => 'Le mosche tse-tse sono pericolose?',
    'blogvax_faq_a11' => 'Il morso è doloroso ma la malattia del sonno non è un rischio pratico nelle principali aree turistiche. Sono presenti nel Tarangire e nel miombo meridionale, e sono attratte da abiti blu scuro e neri.',
    'blogvax_faq_q12' => 'Posso nuotare in laghi e fiumi?',
    'blogvax_faq_a12' => 'Non a meno che la vostra guida non confermi che sia sicuro. La bilharzia è presente in alcune acque dolci, e ippopotami e coccodrilli sono presenti in molte di esse. Le piscine dei lodge vanno bene, e le sorgenti termali di Maji Moto a Nyerere sono sicure per nuotare.',
    'blogvax_faq_q13' => 'Cosa succede se sviluppo febbre dopo il rientro a casa?',
    'blogvax_faq_a13' => 'Consultate immediatamente un medico e ditegli che siete stati in una zona malarica. La malaria può manifestarsi fino a dodici mesi dopo l\'esposizione, più comunemente entro tre mesi. È completamente curabile se scoperta presto.',
    'blogvax_related_badge' => 'Continua a leggere',
    'blogvax_related_title' => 'Continua a esplorare la Tanzania',
    'blogvax_related_contact' => 'Facci una domanda',
    'blogvax_final_title' => 'Domande sul tuo viaggio?',
    'blogvax_final_intro' => 'Non possiamo dare consigli medici, ma possiamo dirti esattamente quali aree e altitudini copre il tuo itinerario — informazioni utili da portare alla tua clinica di viaggio.',
    'blogvax_final_whatsapp' => 'Scrivici su WhatsApp',
    'blogvax_final_contact' => 'Modulo di contatto',

    // ===== Blog article: Serengeti contro Ngorongoro =====
    'blogsvn_meta_title' => 'Serengeti contro Ngorongoro: Quale Scegliere? | Serengeti Budget Safari',
    'blogsvn_meta_description' => 'Serengeti o Cratere di Ngorongoro — un confronto onesto di dimensioni, costo, densità di fauna selvatica e cosa offre davvero ognuno, da un operatore che li gestisce entrambi.',
    'blogsvn_updated' => 'Aggiornato 2026',
    'blogsvn_h1' => 'Serengeti contro Ngorongoro',
    'blogsvn_hero_sub' => 'Due dei parchi più conosciuti della Tanzania, uno accanto all\'altro e completamente diversi nel carattere — quale si adatta al vostro viaggio?',
    'blogsvn_quick_badge' => 'Risposte rapide',
    'blogsvn_quick_title' => 'Serengeti o Ngorongoro, in breve',
    'blogsvn_quick_intro' => 'Le differenze principali prima del dettaglio.',
    'blogsvn_qq1_q' => 'Quale è più grande?',
    'blogsvn_qq1_a' => 'Il Serengeti, di gran lunga — 14.763 km² contro i 260 km² del cratere.',
    'blogsvn_qq2_q' => 'Quale ha il rinoceronte?',
    'blogsvn_qq2_a' => 'Ngorongoro. Il Serengeti ne ha quasi nessuno.',
    'blogsvn_qq3_q' => 'Quale ha la migrazione?',
    'blogsvn_qq3_a' => 'Il Serengeti, per la maggior parte dell\'anno. Ngorongoro la vede solo brevemente.',
    'blogsvn_qq4_q' => 'Quale richiede meno tempo?',
    'blogsvn_qq4_a' => 'Ngorongoro — una giornata intera copre il cratere.',
    'blogsvn_qq5_q' => 'Quale costa di più?',
    'blogsvn_qq5_a' => 'Ngorongoro, una volta aggiunta la tassa di discesa nel cratere di $295.',
    'blogsvn_qq6_q' => 'Posso fare entrambi?',
    'blogsvn_qq6_a' => 'Sì, e la maggior parte degli itinerari lo fa — sono uno accanto all\'altro.',
    'blogsvn_see_faq' => 'Vedi tutte le FAQ',
    'blogsvn_toc_title' => 'Indice – Serengeti contro Ngorongoro',
    'blogsvn_toc_1' => 'La risposta breve',
    'blogsvn_toc_2' => 'A confronto',
    'blogsvn_toc_3' => 'Cosa fa meglio il Serengeti',
    'blogsvn_toc_4' => 'Cosa fa meglio Ngorongoro',
    'blogsvn_toc_5' => 'Fare entrambi',
    'blogsvn_toc_6' => 'FAQ',
    'blogsvn_s1_badge' => 'In breve',
    'blogsvn_s1_title' => 'La risposta breve',
    'blogsvn_s1_p1' => 'Non sono davvero concorrenti — la maggior parte degli itinerari visita <strong>entrambi</strong>, perché sono uno accanto all\'altro e svolgono funzioni diverse. Il Serengeti è vasto, vario, e ospita la Grande Migrazione per la maggior parte dell\'anno. Il Cratere di Ngorongoro è piccolo, autonomo, e offre la più densa concentrazione di fauna selvatica in Africa in una sola giornata, incluso il rinoceronte nero che al Serengeti manca in gran parte.',
    'blogsvn_s1_p2' => 'Se potete scegliere solo uno: scegliete il Serengeti per la scala e la migrazione, scegliete Ngorongoro se il vostro tempo è molto limitato e volete la massima fauna selvatica per ora.',
    'blogsvn_cta_label' => 'Vedi Entrambi in un Viaggio',
    'blogsvn_s2_badge' => 'Confronto',
    'blogsvn_s2_title' => 'A confronto',
    'blogsvn_t1_h1' => 'Fattore',
    'blogsvn_t1_r1_a' => 'Dimensione',
    'blogsvn_crater_floor' => 'fondo del cratere',
    'blogsvn_t1_r2_a' => 'Istituito',
    'blogsvn_t1_r3_a' => 'Stato',
    'blogsvn_t1_r3_b' => 'Patrimonio Mondiale UNESCO',
    'blogsvn_t1_r3_c' => 'Patrimonio Mondiale UNESCO',
    'blogsvn_t1_r4_a' => 'Costo d\'ingresso (2026)',
    'blogsvn_per_vehicle' => 'per veicolo per scendere',
    'blogsvn_t1_r5_a' => 'Ideale per',
    'blogsvn_t1_r5_b' => 'Scala, varietà, la migrazione',
    'blogsvn_t1_r5_c' => 'Densità, rinoceronte, una singola giornata indimenticabile',
    'blogsvn_t1_r6_a' => 'Leoni',
    'blogsvn_t1_r6_c' => '~60 (in 260 km²)',
    'blogsvn_t1_r7_a' => 'Rinoceronte nero',
    'blogsvn_t1_r8_a' => 'Durata tipica della visita',
    'blogsvn_t1_r8_b' => '2–4 notti',
    'blogsvn_t1_r8_c' => '1 giornata intera',
    'blogsvn_s2_note' => 'Dati dalle nostre guide dei parchi — vedi le pagine complete di Serengeti e Ngorongoro per i dettagli.',
    'blogsvn_s3_badge' => 'Serengeti',
    'blogsvn_s3_title' => 'Cosa fa meglio il Serengeti',
    'blogsvn_s3_p1' => 'Il Serengeti è il parco di punta della Tanzania per una buona ragione: è enorme, ecologicamente vario, e ha una delle densità di leoni più alte in Africa. È anche la casa tutto l\'anno della Grande Migrazione — le mandrie sono da qualche parte dentro l\'ecosistema in ogni singolo mese, muovendosi in un ciclo continuo guidato dalle piogge.',
    'blogsvn_s3_i1' => 'Pianure infinite e habitat vari — da praterie aperte a foreste ripariali',
    'blogsvn_s3_i2' => 'La Grande Migrazione, in qualche forma, quasi ogni mese dell\'anno',
    'blogsvn_s3_i3' => 'Alcuni dei migliori avvistamenti di leopardo in Tanzania, specialmente nella valle di Seronera',
    'blogsvn_s3_p2' => 'Ciò che non ha: numeri significativi di rinoceronte nero, e una sensazione di vera privatezza in alta stagione vicino alle aree centrali popolari.',
    'blogsvn_s3_link' => 'Guida completa al parco del Serengeti',
    'blogsvn_s4_badge' => 'Ngorongoro',
    'blogsvn_s4_title' => 'Cosa fa meglio Ngorongoro',
    'blogsvn_s4_p1' => 'Il Cratere di Ngorongoro è una caldera vulcanica collassata, 260 km² di prateria racchiusi da un bordo di 600 metri. Nulla ne migra fuori, quindi la densità di fauna selvatica è straordinaria — circa 25.000 grandi animali vivono al suo interno tutto l\'anno, visibili in un singolo game drive.',
    'blogsvn_s4_i1' => 'Il posto più affidabile in Tanzania per vedere il rinoceronte nero, con circa 30 che vivono sotto protezione',
    'blogsvn_s4_i2' => 'Densità di fauna selvatica ineguagliata per il tempo investito — un giorno, non diversi',
    'blogsvn_s4_i3' => 'Scenari spettacolari dal bordo, guardando giù nel fondo del cratere',
    'blogsvn_s4_warn_t' => 'Il problema:',
    'blogsvn_s4_warn_d' => 'una tassa separata di $295 per veicolo solo per scendere nel cratere, addebitata ogni volta che scendete — oltre all\'ingresso standard del parco. Diminuisce drasticamente per persona man mano che il gruppo cresce.',
    'blogsvn_s4_p2' => 'Ciò che non ha: la scala del Serengeti, o la migrazione per la maggior parte dell\'anno — Ngorongoro fa tecnicamente parte dello stesso ecosistema (le zone di parto a Ndutu si trovano dentro l\'Area di Conservazione), ma il fondo del cratere stesso vede le mandrie solo brevemente.',
    'blogsvn_s4_link' => 'Guida completa al parco di Ngorongoro',
    'blogsvn_s5_badge' => 'Insieme',
    'blogsvn_s5_title' => 'Perché la maggior parte delle persone fa entrambi',
    'blogsvn_s5_p1' => 'I due parchi sono adiacenti, collegati da un breve tragitto, ed è per questo che la stragrande maggioranza degli itinerari del circuito settentrionale li combina invece di sceglierne uno. Una struttura tipica: due o tre notti nel Serengeti per lo spazio e la varietà, poi una notte al o vicino al bordo del cratere per una discesa mattutina il giorno seguente — il cratere è meglio farlo alla prima luce, prima che arrivino gli escursionisti giornalieri da Karatu.',
    'blogsvn_s5_p2' => 'Il nostro <strong>Safari 5 Giorni Serengeti e Ngorongoro</strong> è costruito esattamente intorno a questa combinazione.',
    'blogsvn_faq_badge' => 'FAQ',
    'blogsvn_faq_title' => 'Serengeti contro Ngorongoro — domande frequenti',
    'blogsvn_faq_q1' => 'Ngorongoro fa parte del Serengeti?',
    'blogsvn_faq_a1' => 'No, sono aree protette separate amministrate diversamente — il Serengeti dal TANAPA, Ngorongoro dalla NCAA — anche se sono ecologicamente collegate e adiacenti l\'una all\'altra.',
    'blogsvn_faq_q2' => 'Quale è migliore per i Big Five?',
    'blogsvn_faq_a2' => 'Insieme, non separatamente. Il Serengeti offre facilmente leone, leopardo, elefante e bufalo; Ngorongoro è essenzialmente l\'unico posto affidabile in Tanzania per il rinoceronte nero. Visitare entrambi è come la maggior parte dei viaggiatori completa l\'elenco.',
    'blogsvn_faq_q3' => 'Quanti giorni mi servono per Ngorongoro?',
    'blogsvn_faq_a3' => 'Una giornata intera copre a fondo il fondo del cratere — è abbastanza piccolo che un singolo game drive, fatto presto, vede la maggior parte di ciò che c\'è da vedere.',
    'blogsvn_faq_q4' => 'Quanti giorni mi servono per il Serengeti?',
    'blogsvn_faq_a4' => 'Due-quattro notti minimo per apprezzarne la scala. In quale regione alloggiate dovrebbe corrispondere al mese, poiché la migrazione si muove attraverso diverse parti del parco durante l\'anno.',
    'blogsvn_faq_q5' => 'Perché Ngorongoro è molto più costoso al giorno?',
    'blogsvn_faq_a5' => 'La tassa di discesa nel cratere di $295, addebitata per veicolo ogni volta che scendete. Distribuita su un gruppo diventa ragionevole — circa $50 a testa per sei persone — ma per due persone è un costo reale oltre all\'ingresso standard del parco.',
    'blogsvn_faq_q6' => 'Posso saltarne uno e fare solo l\'altro?',
    'blogsvn_faq_a6' => 'Sì. Se il vostro tempo è molto limitato, Ngorongoro da solo offre un\'osservazione densa della fauna in una sola giornata. Se avete una settimana o più, il Serengeti da solo vi dà scala e varietà. La maggior parte dei viaggiatori con 4+ giorni fa entrambi.',
    'blogsvn_related_parks' => 'Tutti i parchi a confronto',
    'blogsvn_final_title' => 'Stai ancora decidendo tra i due?',
    'blogsvn_final_intro' => 'Dicci quanti giorni hai e cosa conta di più per te — ti diremo onestamente se fare uno, l\'altro, o entrambi.',

