    'legal_contact_body' => 'Scrivici a <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a> oppure su <a href="https://wa.me/255697612865" rel="noopener">WhatsApp +255 697 612 865</a>.',
    'legal_nav_privacy' => 'Privacy Policy',
