    // ===== Privacy Policy =====
    'privacy_meta_title' => 'Privacy Policy | Serengeti Budget Safari',
    'privacy_meta_description' => 'Come Serengeti Budget Safari raccoglie, utilizza e protegge i tuoi dati personali, e i diritti che hai secondo il GDPR.',
    'privacy_h1' => 'Privacy Policy',
    'privacy_intro' => 'Questa informativa spiega quali dati personali raccoglie <strong>Serengeti Budget Safari</strong> quando visiti questo sito o ci chiedi un preventivo, per quale motivo li trattiamo e quali diritti puoi esercitare. Il trattamento avviene nel rispetto del Regolamento UE 2016/679 (GDPR).',
    'privacy_h2_1' => '1. Titolare del trattamento',
    'privacy_h2_2' => '2. Quali dati raccogliamo',
    'privacy_h3_1' => 'Dati che ci fornisci tu',
    'privacy_you_i1' => 'nome e cognome;',
    'privacy_you_i2' => 'indirizzo e-mail e numero di telefono;',
    'privacy_you_i3' => 'paese di residenza;',
    'privacy_you_i4' => 'date di viaggio, numero di partecipanti e preferenze indicate nella richiesta;',
    'privacy_you_i5' => 'eventuali informazioni che scegli di comunicarci (esigenze alimentari, necessità di accessibilità, richieste particolari).',
    'privacy_h3_2' => 'Dati raccolti automaticamente',
    'privacy_auto_i1' => 'indirizzo IP, tipo di browser e di dispositivo;',
    'privacy_auto_i2' => 'pagine visitate e data/ora della visita;',
    'privacy_auto_i3' => 'sito di provenienza.',
    'privacy_h2_3' => '3. Perché trattiamo i tuoi dati',
    'privacy_why_i1' => '<strong>Rispondere alle tue richieste</strong> e preparare un preventivo — base giuridica: misure precontrattuali su tua richiesta (art. 6.1.b GDPR).',
    'privacy_why_i2' => '<strong>Organizzare ed erogare il viaggio</strong> che hai prenotato — base giuridica: esecuzione del contratto (art. 6.1.b GDPR).',
    'privacy_why_i3' => '<strong>Adempiere a obblighi fiscali e di legge</strong> — base giuridica: obbligo legale (art. 6.1.c GDPR).',
    'privacy_why_i4' => '<strong>Migliorare il sito</strong> attraverso statistiche aggregate — base giuridica: legittimo interesse (art. 6.1.f GDPR).',
    'privacy_why_note' => 'Non inviamo comunicazioni commerciali senza il tuo consenso esplicito e non vendiamo i tuoi dati a terzi.',
    'privacy_h2_4' => '4. A chi comunichiamo i dati',
    'privacy_share_intro' => 'Condividiamo i dati solo con chi è necessario per realizzare il tuo viaggio:',
    'privacy_share_i1' => 'lodge, campi tendati e hotel presso cui pernotti;',
    'privacy_share_i2' => 'compagnie aeree per i voli interni e operatori di trasferimento;',
    'privacy_share_i3' => 'autorità dei parchi nazionali, quando il permesso di ingresso richiede i dati dei visitatori;',
    'privacy_share_i4' => 'fornitori di servizi tecnici del sito (hosting, posta elettronica);',
    'privacy_share_i5' => 'autorità pubbliche, quando previsto dalla legge.',
    'privacy_share_note' => 'Poiché operiamo dalla Tanzania, i tuoi dati sono trattati anche al di fuori dello Spazio Economico Europeo. Il trasferimento avviene sulla base dell\'art. 49.1.b GDPR, in quanto necessario all\'esecuzione del contratto di viaggio che hai richiesto.',
    'privacy_h2_5' => '5. Per quanto tempo li conserviamo',
    'privacy_keep_i1' => '<strong>Richieste di preventivo senza prenotazione:</strong> 24 mesi dall\'ultimo contatto.',
    'privacy_keep_i2' => '<strong>Viaggi confermati:</strong> 10 anni, per obblighi contabili e fiscali.',
    'privacy_keep_i3' => '<strong>Dati di navigazione:</strong> massimo 26 mesi in forma aggregata.',
    'privacy_h2_6' => '6. Cookie',
    'privacy_cookies_p1' => 'Il sito utilizza cookie tecnici necessari al funzionamento delle pagine e alla memorizzazione della lingua scelta. Utilizziamo inoltre servizi esterni per i font e le icone (Google Fonts, Font Awesome via CDN), che possono registrare il tuo indirizzo IP. Puoi bloccare o cancellare i cookie dalle impostazioni del browser: alcune funzioni del sito potrebbero risultare limitate. Consulta la nostra',
    'privacy_cookies_link' => 'cookie policy',
    'privacy_h2_7' => '7. I tuoi diritti',
    'privacy_rights_intro' => 'Ai sensi degli articoli 15-22 del GDPR hai diritto di:',
    'privacy_rights_i1' => 'accedere ai dati che ti riguardano e ottenerne copia;',
    'privacy_rights_i2' => 'chiederne la rettifica o la cancellazione;',
    'privacy_rights_i3' => 'chiedere la limitazione del trattamento od opporti ad esso;',
    'privacy_rights_i4' => 'ricevere i dati in formato strutturato (portabilità);',
    'privacy_rights_i5' => 'revocare in qualsiasi momento il consenso prestato;',
    'privacy_rights_i6' => 'proporre reclamo all\'autorità di controllo competente (in Italia: Garante per la protezione dei dati personali).',
    'privacy_rights_note' => 'Per esercitare questi diritti scrivi a <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a>: rispondiamo entro 30 giorni.',
    'privacy_h2_8' => '8. Sicurezza',
    'privacy_security_p1' => 'Adottiamo misure tecniche e organizzative ragionevoli per proteggere i dati da accessi non autorizzati, perdita o divulgazione. Nessuna trasmissione via Internet è però sicura al 100%: non inviarci mai per e-mail o WhatsApp numeri completi di carte di credito.',
    'privacy_h2_9' => '9. Minori',
    'privacy_children_p1' => 'Il sito non è destinato a minori di 16 anni. I dati dei minori che partecipano a un viaggio sono forniti dai genitori o da chi ne esercita la responsabilità genitoriale.',
    'privacy_h2_10' => '10. Modifiche',
    'privacy_changes_p1' => 'Possiamo aggiornare questa informativa; la data in cima alla pagina indica sempre l\'ultima revisione.',

    // ===== Termini e Condizioni =====
    'terms_meta_title' => 'Termini e Condizioni | Serengeti Budget Safari',
    'terms_meta_description' => 'Condizioni di prenotazione di Serengeti Budget Safari: acconti, pagamenti, penali di cancellazione, requisiti assicurativi, responsabilità e reclami.',
    'terms_h1' => 'Termini e Condizioni',
    'terms_intro' => 'Questi termini regolano le prenotazioni di safari, trekking, escursioni giornaliere e soggiorni a Zanzibar organizzati da <strong>Serengeti Budget Safari</strong>, con sede ad Arusha, Tanzania. Confermando una prenotazione dichiari di averli letti e accettati.',
    'terms_note_title' => 'Importante:',
    'terms_note_body' => 'gli importi, le percentuali e le scadenze qui sotto sono le nostre condizioni standard. I termini vincolanti per il tuo viaggio sono quelli indicati nel preventivo scritto che ti inviamo — in caso di differenza, prevale il preventivo.',
    'terms_h2_1' => '1. Prenotazione e conferma',
    'terms_booking_i1' => 'Richiedere un preventivo è gratuito e non comporta alcun obbligo.',
    'terms_booking_i2' => 'Una prenotazione è confermata solo dopo aver ricevuto la nostra conferma scritta e l\'acconto.',
    'terms_booking_i3' => 'La disponibilità di lodge e campi non è bloccata fino alla conferma. In alta stagione la disponibilità può cambiare nel giro di poche ore.',
    'terms_booking_i4' => 'Fornisci i nomi esattamente come compaiono sul passaporto; correzioni successive possono comportare costi da parte di lodge e compagnie aeree.',
    'terms_h2_2' => '2. Prezzi',
    'terms_prices_i1' => 'I prezzi sono indicati in euro (EUR) o dollari statunitensi (USD) come specificato nel preventivo, per persona salvo diversa indicazione.',
    'terms_prices_i2' => 'Salvo diversa indicazione nel preventivo, il prezzo copre: veicolo 4x4 con autista-guida, carburante, tasse d\'ingresso ai parchi previsti nell\'itinerario, alloggio e pasti come descritto, e acqua potabile durante i game drive.',
    'terms_prices_i3' => 'Il prezzo esclude: voli internazionali, visto, assicurazione di viaggio, bevande, mance, spese personali, escursioni facoltative e voli interni salvo espressamente indicati.',
    'terms_prices_i4' => 'Le tasse d\'ingresso ai parchi sono stabilite dalle autorità tanzaniane (TANAPA, NCAA). Se aumentano dopo la conferma della prenotazione, la differenza è a carico del viaggiatore.',
    'terms_h2_3' => '3. Pagamento',
    'terms_pay_deposit_t' => 'Acconto:',
    'terms_pay_deposit_d' => '30% del totale alla conferma.',
    'terms_pay_balance_t' => 'Saldo:',
    'terms_pay_balance_d' => 'dovuto 30 giorni prima della partenza. Per prenotazioni effettuate entro 30 giorni dalla partenza, l\'intero importo è dovuto alla conferma.',
    'terms_pay_i3' => 'Le commissioni bancarie e di trasferimento sono a carico del viaggiatore.',
    'terms_pay_i4' => 'Se il saldo non viene pagato entro la scadenza, possiamo considerare la prenotazione cancellata e applicare le penali di cui alla clausola 4.',
    'terms_h2_4' => '4. Cancellazione da parte tua',
    'terms_cancel_intro' => 'Le cancellazioni devono essere comunicate per iscritto. Si applicano le seguenti penali, calcolate sul prezzo totale del viaggio:',
    'terms_cancel_th1' => 'Preavviso prima della partenza',
    'terms_cancel_th2' => 'Penale',
    'terms_cancel_r1_a' => 'Più di 60 giorni',
    'terms_cancel_r1_b' => 'Acconto trattenuto (30%)',
    'terms_cancel_r2_a' => 'Da 60 a 30 giorni',
    'terms_cancel_r2_b' => '50% del totale',
    'terms_cancel_r3_a' => 'Da 29 a 15 giorni',
    'terms_cancel_r3_b' => '75% del totale',
    'terms_cancel_r4_a' => 'Meno di 15 giorni, o mancata presentazione',
    'terms_cancel_r4_b' => '100% del totale',
    'terms_cancel_note' => 'Alcuni lodge, campi mobili e voli interni impongono condizioni proprie più severe; quando è così, te lo indichiamo nel preventivo.',
    'terms_h2_5' => '5. Modifiche',
    'terms_changes_i1' => 'Le modifiche richieste più di 30 giorni prima della partenza sono gratuite, salvo eventuali differenze nel costo dei servizi e commissioni dei fornitori.',
    'terms_changes_i2' => 'Le modifiche richieste entro 30 giorni dalla partenza sono trattate come cancellazione e nuova prenotazione.',
    'terms_changes_i3' => 'Possiamo modificare un itinerario per ragioni di sicurezza, condizioni meteo, condizioni stradali, chiusura dei parchi o disponibilità di alloggio, fornendo servizi di standard equivalente.',
    'terms_h2_6' => '6. Assicurazione di viaggio',
    'terms_insurance_p1' => '<strong>L\'assicurazione di viaggio è obbligatoria</strong> per tutti i nostri viaggi. Deve coprire spese mediche, evacuazione di emergenza e rimpatrio. Per il Kilimanjaro e il Monte Meru, la polizza deve coprire esplicitamente il trekking ad alta quota fino a 6.000 m. Consigliamo anche una copertura per l\'annullamento. Non siamo responsabili per costi derivanti da un\'assicurazione inadeguata.',
    'terms_h2_7' => '7. Documenti, salute e sicurezza',
    'terms_docs_i1' => 'Il passaporto deve essere valido per almeno sei mesi dalla data di ingresso e avere due pagine bianche.',
    'terms_docs_i2' => 'Ottenere il visto tanzaniano è responsabilità del viaggiatore.',
    'terms_docs_i3' => 'È richiesto un certificato di febbre gialla se si arriva da, o si è transitati in, un paese a rischio.',
    'terms_docs_i4' => 'Ti preghiamo di comunicarci al momento della prenotazione eventuali condizioni mediche, allergie o farmaci rilevanti per il viaggio.',
    'terms_docs_i5' => 'Durante i game drive devi seguire le istruzioni della guida: non scendere dal veicolo senza permesso e non avvicinarti agli animali.',
    'terms_h2_8' => '8. Responsabilità',
    'terms_liability_i1' => 'Organizziamo il tuo viaggio con cura professionale e siamo responsabili della corretta erogazione dei servizi che forniamo direttamente.',
    'terms_liability_i2' => 'Non siamo responsabili per ritardi, cancellazioni o perdite causate da eventi al di fuori del nostro ragionevole controllo: condizioni meteo, disastri naturali, epidemie, disordini civili, scioperi, decisioni delle autorità o guasti alle infrastrutture pubbliche.',
    'terms_liability_i3' => 'Non siamo responsabili per servizi che prenoti autonomamente con terze parti.',
    'terms_liability_i4' => 'Gli avvistamenti di fauna selvatica avvengono in natura e non possono essere garantiti.',
    'terms_liability_i5' => 'Bagagli e oggetti personali restano sotto la responsabilità del viaggiatore.',
    'terms_h2_9' => '9. Comportamento',
    'terms_conduct_p1' => 'Ci riserviamo il diritto di allontanare da un viaggio, senza rimborso, chiunque metta a rischio la propria o altrui sicurezza, danneggi l\'ambiente o la fauna selvatica, o si comporti con grave mancanza di rispetto verso le comunità locali o il nostro staff.',
    'terms_h2_10' => '10. Reclami',
    'terms_complaints_p1' => 'Se qualcosa va storto durante il tuo viaggio, informa subito la tua guida o il nostro ufficio — la maggior parte dei problemi può essere risolta sul posto. I reclami scritti devono pervenire a <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a> entro 30 giorni dalla fine del viaggio.',
    'terms_h2_11' => '11. Legge applicabile',
    'terms_law_p1' => 'Questo contratto è regolato dalla legge della Repubblica Unita di Tanzania. Prima di intraprendere azioni legali, entrambe le parti concordano di tentare una composizione amichevole.',
    'terms_contact_title' => 'Domande prima di prenotare?',
    'terms_contact_body' => 'Scrivici a <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a> oppure su <a href="https://wa.me/255697612865" rel="noopener">WhatsApp +255 697 612 865</a>. Rispondiamo ogni giorno tra le 07:00 e le 21:00 ora della Tanzania.',

    // ===== Cookie Policy =====
    'cookies_meta_title' => 'Cookie Policy | Serengeti Budget Safari',
    'cookies_meta_description' => 'Quali cookie e servizi di terze parti utilizza questo sito, e come controllarli dal tuo browser.',
    'cookies_h1' => 'Cookie Policy',
    'cookies_intro' => 'I cookie sono piccoli file di testo che un sito salva sul tuo dispositivo. Questa pagina spiega quali utilizziamo e come puoi controllarli.',
    'cookies_h2_1' => '1. Cookie tecnici',
    'cookies_technical_intro' => 'Sono necessari al funzionamento del sito e non richiedono consenso:',
    'cookies_th_name' => 'Nome',
    'cookies_th_purpose' => 'Finalità',
    'cookies_th_duration' => 'Durata',
    'cookies_row_lang_purpose' => 'Memorizza la lingua scelta per non richiederla ad ogni visita',
    'cookies_row_lang_duration' => 'Fino alla cancellazione manuale',
    'cookies_technical_note' => 'Questo dato è salvato nel <em>local storage</em> del browser, resta sul tuo dispositivo e non viene trasmesso ai nostri server.',
    'cookies_h2_2' => '2. Servizi di terze parti',
    'cookies_third_party_intro' => 'Per la resa grafica delle pagine il sito carica risorse da fornitori esterni. Questi fornitori possono registrare il tuo indirizzo IP e i dati del browser:',
    'cookies_gfonts_purpose' => 'caratteri tipografici',
    'cookies_fa_purpose' => 'icone',
    'cookies_google_notice' => 'Informativa Google',
    'cookies_cloudflare_notice' => 'Informativa Cloudflare',
    'cookies_h2_3' => '3. Contenuti incorporati',
    'cookies_embed_p1' => 'Alcune pagine possono includere video o mappe ospitati da servizi esterni (ad esempio YouTube o Google Maps). Se una pagina contiene questi contenuti, il fornitore può installare cookie propri quando avvii la riproduzione o interagisci con la mappa.',
    'cookies_h2_4' => '4. Cookie che non usiamo',
    'cookies_notuse_p1' => 'Non utilizziamo cookie di profilazione pubblicitaria e non rivendiamo dati di navigazione a inserzionisti.',
    'cookies_h2_5' => '5. Come gestire i cookie',
    'cookies_manage_intro' => 'Puoi bloccare o cancellare i cookie dalle impostazioni del tuo browser:',
    'cookies_manage_chrome' => 'Impostazioni → Privacy e sicurezza → Cookie',
    'cookies_manage_safari' => 'Preferenze → Privacy',
    'cookies_manage_firefox' => 'Impostazioni → Privacy e sicurezza',
    'cookies_manage_edge' => 'Impostazioni → Cookie e autorizzazioni sito',
    'cookies_manage_note' => 'Disattivando i cookie tecnici il sito resta consultabile, ma dovrai riselezionare la lingua ad ogni visita.',
    'cookies_h2_6' => '6. Contatti',
    'cookies_contact_p1' => 'Per qualsiasi domanda scrivi a <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a>.',

    // Booking flow
    'booking_meta_title' => 'Prenota il Tuo Safari — Serengeti Budget Safari',
    'booking_meta_description' => 'Richiedi la prenotazione del tuo safari in Tanzania. Il nostro team ti contatterà su WhatsApp per confermare le date e organizzare il pagamento.',
    'booking_hero_badge' => 'Richiesta di Prenotazione',
    'booking_hero_title' => 'Richiedi la Tua Prenotazione Safari',
    'booking_form_title' => 'I Tuoi Dati',
    'booking_form_intro' => 'Compila il modulo qui sotto e il nostro team ti contatterà su WhatsApp o telefono per confermare la disponibilità e organizzare il pagamento. Nessun pagamento viene effettuato su questo sito.',
    'booking_form_required' => 'Compila tutti i campi obbligatori con un indirizzo email valido.',
    'booking_form_safari' => 'Safari',
